      // test still isolates the RENAMED_WITHOUT_COMPLETE property.
      const intentPath = cleanupIntentPathFor(repoId, instanceId);
      fs.mkdirSync(path.dirname(intentPath), { recursive: true });
      fs.writeFileSync(intentPath, JSON.stringify({
        schema: 'coordination/cleanup-intent/v1', instanceId, repoId, runId: crypto.randomBytes(16).toString('hex'),
        intendedPath: path.join(rll.registryRepoDir({ repoId }), 'isolation-roots', instanceId), rootInode: { dev: '111', ino: '222' }, outcome: 'PID_ABSENT',
        pid: process.pid, birthToken: 'synthetic', executableIdentity: process.execPath,
        instanceRecordIdentity: { dev: '555', ino: '666', mode: '33152', uid: '501' },
        intentAt: new Date().toISOString(),
      }), { mode: 0o600 });
      // Deliberately no cleanup-complete/v1 and no cleanup-integrity-failure/v1.

