describe('CORRECTION ROUND -- Section B: broker/checkpoint evidence attacks', () => {
  test('ATTACK: a role present in expectedRoster but ABSENT from rootRoster is still accepted by bindConnection -- rootRoster is accepted but never actually consulted (this file\'s own necessarily-inventive resolution of an underspecified term: a role must be root-confined -- i.e. present in rootRoster -- to bind at all; flagged explicitly, see report)', async () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-attack-rootroster-'));
    const fixture = makeSealedIsolationFixture(tmp);
    try {
      const deps = validAuthoritiesDeps(fixture, {
        expectedRoster: [{ role: 'verifier', ordinal: 0 }, { role: 'quality-gater', ordinal: 0 }],
        rootRoster: ['verifier'], // quality-gater deliberately absent
      });
      const authorities = rbc.createRunAuthorities(deps);
      const result = authorities.bindConnection({ role: 'quality-gater', ordinal: 0 });
      assert.strictEqual(result.ok, false, 'a role not present in rootRoster must be rejected at bind time -- currently rootRoster is accepted but never consulted at all, so this binding wrongly succeeds: ' + JSON.stringify(result));
    } finally {
      cleanupDir(tmp);
    }
  });

  for (const layer of ['home', 'tmp', 'xdgCache', 'cwd']) {
    test('ATTACK: a secret physically present ONLY in the sealed root\'s "' + layer + '" topology directory (never in config.toml) is NOT caught by the checkpoint scan -- only config.toml is ever scanned', async () => {
      const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-attack-topology-leak-'));
      const fixture = makeSealedIsolationFixture(tmp);
      const KNOWN_SECRET = syntheticSecret('topology-leak-' + layer);
      try {
        const deps = validAuthoritiesDeps(fixture, {
          sourceProvider: fakeSourceProviderBlock2({ read: () => ({ ok: true, credentials: { token: KNOWN_SECRET }, otherCredentialFields: {}, expiresAt: futureIso(), sourceIdentity: 'x' }) }),
        });
        const authorities = rbc.createRunAuthorities(deps);
        const bound = authorities.bindConnection({ role: 'verifier', ordinal: 0 });
        assert.strictEqual(typeof bound.reason, 'undefined', JSON.stringify(bound));
        bound.refreshProvider({}); // registers KNOWN_SECRET into secretMatcher

        const layerDir = fixture.sealHandle.topologyPaths[layer];
        assert.ok(layerDir, 'test precondition: topologyPaths must expose a "' + layer + '" directory');
        fs.writeFileSync(path.join(layerDir, 'leak.txt'), 'leaked here: ' + KNOWN_SECRET, 'utf8');

        const afterLeak = authorities.bindConnection({ role: 'verifier', ordinal: 1 });
        assert.strictEqual(afterLeak.ok, false, 'a secret physically present in the sealed root\'s "' + layer + '" directory must poison the broker -- the current scan only ever reads config.toml, missing this leak entirely: ' + JSON.stringify(afterLeak));
      } finally {
        cleanupDir(tmp);
      }
    });
  }

  test('ATTACK: a read failure during the sealed-root scan (config.toml removed underneath) crashes with an UNCAUGHT exception instead of failing closed as a clean result', async () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-attack-scan-crash-'));
    const fixture = makeSealedIsolationFixture(tmp);
    try {
      const authorities = rbc.createRunAuthorities(validAuthoritiesDeps(fixture));
      const bound = authorities.bindConnection({ role: 'verifier', ordinal: 0 });
      assert.strictEqual(typeof bound.reason, 'undefined', JSON.stringify(bound));

      fs.unlinkSync(fixture.sealHandle.configPath); // the sealed root's own config.toml, now unreadable

      let threw = false;
      try {
        bound.refreshProvider({});
      } catch (err) {
        threw = true;
      }
      assert.strictEqual(threw, false, 'a read failure during the sealed-root scan must never propagate as an uncaught exception -- it must fail closed as a structured, clean result instead');
    } finally {
      cleanupDir(tmp);
    }
  });

  test('ATTACK: no durable credential-absence-checkpoints/v1 (or any other durable evidence record) is EVER published as a result of login/turn/refresh checkpoints -- checkout()/refreshProvider only ever produce in-memory attestations', async () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-attack-no-durable-evidence-'));
    const fixture = makeSealedIsolationFixture(tmp);
    try {
      const registryDir = rll.registryRepoDir({ repoId: fixture.repoId });
      const before = listFilesRecursive(registryDir);
      const authorities = rbc.createRunAuthorities(validAuthoritiesDeps(fixture));
      const bound = authorities.bindConnection({ role: 'verifier', ordinal: 0 });
      assert.strictEqual(typeof bound.reason, 'undefined', JSON.stringify(bound));
      const binding = bound.checkout();
      binding.recordLogin('pre');
      binding.recordLogin('post');
      binding.recordTurn('pre');
      binding.recordTurn('during');
      binding.recordTurn('post');
      bound.refreshProvider({});
      const after = listFilesRecursive(registryDir);
      const newFiles = after.filter((f) => !before.includes(f));
      assert.ok(newFiles.length > 0, 'at least one durable credential-absence-checkpoints/v1 record must be published as a result of these genuine checkpoint scans -- currently NOTHING is ever written to disk; evidence exists only in memory and is lost the instant the process exits: ' + JSON.stringify(newFiles));
    } finally {
      cleanupDir(tmp);
      cleanupRegistryFor(fixture.repoId);
    }
  });

  test('FIX (replaces the weak Block-1 proxy): copy-on-register is now proven at CONTENT level, via the real secret-scanning mechanism -- mutating the caller\'s buffer after registering must NOT erase evidence of a leak that was captured before the mutation', async () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-fix-copy-on-register-'));
    const fixture = makeSealedIsolationFixture(tmp);
    const KNOWN_SECRET = syntheticSecret('copy-on-register-proof');
    try {
      const deps = validAuthoritiesDeps(fixture, {
        sourceProvider: fakeSourceProviderBlock2({ read: () => ({ ok: true, credentials: { token: KNOWN_SECRET }, otherCredentialFields: {}, expiresAt: futureIso(), sourceIdentity: 'x' }) }),
      });
      const authorities = rbc.createRunAuthorities(deps);
      const bound = authorities.bindConnection({ role: 'verifier', ordinal: 0 });
      assert.strictEqual(typeof bound.reason, 'undefined', JSON.stringify(bound));
      bound.refreshProvider({}); // registers KNOWN_SECRET into secretMatcher

      const buffer = Buffer.from('captured output mentioning ' + KNOWN_SECRET, 'utf8');
      const registerResult = authorities.captureSink.register(buffer);
      assert.deepStrictEqual(registerResult, { ok: true });
      // Mutate the CALLER'S OWN buffer in place, AFTER registering, so it no
      // longer contains the secret at all:
      buffer.fill(0);

      const afterMutation = authorities.bindConnection({ role: 'verifier', ordinal: 1 });
      assert.strictEqual(afterMutation.ok, false, 'the STORED copy must still contain the original captured bytes (including the secret) even after the caller mutates their own buffer to erase it -- if this test ever passes with a real aliasing bug (no copy-on-register), the stored "evidence" would already be zeroed and this bind would wrongly succeed: ' + JSON.stringify(afterMutation));
    } finally {
      cleanupDir(tmp);
      cleanupRegistryFor(fixture.repoId);
    }
  });
});

describe('CORRECTION ROUND -- Section C: spawn attacks', () => {
  test('ATTACK: a fake child with NO genuine pid/executable/birth-token still reaches BORN -- requireProvenProcessIdentity verifies the HOST\'s own identity, never the CHILD\'s, so an entirely unverified child is accepted', async () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-attack-nopid-'));
    const fixture = makeSpawnFixture(tmp);
    try {
      const instanceId = crypto.randomBytes(16).toString('hex');
      const registry = rbc.createSupervisorOwnedChildRegistry();
      const spawnFn = () => {
        const child = new EventEmitter();
        child.pid = undefined; // no genuine PID at all
        setImmediate(() => child.emit('spawn'));
        return child;
      };
      const result = await withFakeProcessIdentity(VALID_FAKE_IDENTITY, () =>
        rbc.spawnWithIntent({ instanceId, repoId: fixture.repoId, runId: fixture.runId, rootIdentity: fixture.rootIdentity }, spawnFn, { registry, stopOwnedChild: (child) => child.kill('SIGTERM') }));
      assert.notStrictEqual(result.state, 'BORN', 'a child with no genuine pid/executable/birth-token must never reach BORN -- identity verification must be about the CHILD, not merely the calling host: ' + JSON.stringify(result));
    } finally {
      cleanupDir(tmp);
    }
  });

  test('ATTACK (timeout->late-spawn race): a "spawn" event arriving AFTER the identity timeout already started STOPPING (kill() already called) must never resolve BORN', async () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-attack-race-'));
    const fixture = makeSpawnFixture(tmp);
    try {
      const instanceId = crypto.randomBytes(16).toString('hex');
      const registry = rbc.createSupervisorOwnedChildRegistry();
      let killCalled = false;
      const spawnFn = () => {
        const child = new EventEmitter();
        child.pid = 99999;
        child.kill = function () { killCalled = true; /* never confirms exit within this test */ };
        setTimeout(() => child.emit('spawn'), 50); // deliberately LATE
        return child;
      };
      const result = await withFakeProcessIdentity(VALID_FAKE_IDENTITY, () =>
        rbc.spawnWithIntent({ instanceId, repoId: fixture.repoId, runId: fixture.runId, rootIdentity: fixture.rootIdentity }, spawnFn,
          { registry, identityTimeoutMs: 10, stopConfirmTimeoutMs: 100, stopOwnedChild: (child) => child.kill('SIGTERM') }));
      assert.strictEqual(killCalled, true, 'test precondition: the identity timeout must have already triggered stopping (kill()) before the late spawn event');
      assert.notStrictEqual(result.state, 'BORN', 'a "spawn" event arriving AFTER stopping has already begun (the process is already being killed) must never resolve BORN: ' + JSON.stringify(result));
    } finally {
      cleanupDir(tmp);
    }
  });

  test('ATTACK: a failed spawn-failed-before-process/v1 publish is silently swallowed -- the outer FAILED_BEFORE_PROCESS result claims clean settlement even though the durable record was never actually written', async () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-attack-failedpublish-'));
    const fixture = makeSpawnFixture(tmp);
    try {
      const instanceId = crypto.randomBytes(16).toString('hex');
      const failedPath = spawnFailedPathFor(fixture.repoId, instanceId);
      fs.mkdirSync(path.dirname(failedPath), { recursive: true });
      fs.writeFileSync(failedPath, JSON.stringify({ conflicting: true }), { mode: 0o600 }); // pre-existing conflict

      const registry = rbc.createSupervisorOwnedChildRegistry();
      const spawnFn = () => { throw new Error('synthetic-synchronous-spawn-failure'); };
      const result = await rbc.spawnWithIntent({ instanceId, repoId: fixture.repoId, runId: fixture.runId, rootIdentity: fixture.rootIdentity }, spawnFn, { registry, stopOwnedChild: (child) => child.kill('SIGTERM') });
      assert.strictEqual(result.ok, false, 'the outer result must reflect that the durable spawn-failed-before-process/v1 record could not actually be published -- currently this failure is silently swallowed and the wrapper still reports a clean FAILED_BEFORE_PROCESS settlement with no distinguishing signal at all: ' + JSON.stringify(result));
    } finally {
      cleanupDir(tmp);
    }
  });

  // FOLLOW-UP dispatch: the original fake's own injected stopOwnedChild
  // called `child.kill('SIGTERM')` internally -- the SAME function reference
  // directKillCalled was watching, so BOTH "production bypasses the
  // authority" and "the authority itself legitimately decides to kill" set
  // directKillCalled=true, making the two cases indistinguishable. Redesigned
  // below: the injected fake now confirms the stop via `child.emit('exit',
  // ...)` directly, WITHOUT ever calling `child.kill`, so directKillCalled
  // can only become true if production itself bypasses the authority.
  test('ATTACK (proposed opts.stopOwnedChild(child) injection point): stopping a child calls child.kill() DIRECTLY -- never goes through an injectable stop authority a host could substitute', async () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-attack-directkill-'));
    const fixture = makeSpawnFixture(tmp);
    try {
      const instanceId = crypto.randomBytes(16).toString('hex');
      const registry = rbc.createSupervisorOwnedChildRegistry();
      let stopOwnedChildCalled = false;
      let directKillCalled = false;
      const spawnFn = () => {
        const child = new EventEmitter();
        child.pid = 99999;
        child.kill = function () { directKillCalled = true; setImmediate(() => child.emit('exit', null, 'SIGTERM')); };
        setImmediate(() => child.emit('spawn'));
        return child;
      };
      await withFakeProcessIdentity(INVALID_FAKE_IDENTITY, () => rbc.spawnWithIntent(
        { instanceId, repoId: fixture.repoId, runId: fixture.runId, rootIdentity: fixture.rootIdentity },
        spawnFn,
        {
          registry, identityTimeoutMs: 200, stopConfirmTimeoutMs: 200,
          // Confirms the stop through an entirely separate mechanism -- never
          // touches child.kill -- so this fake's own action can never be
          // confused with production calling child.kill() directly.
          stopOwnedChild: (child) => { stopOwnedChildCalled = true; setImmediate(() => child.emit('exit', null, 'SIGTERM')); },
        },
      ));
      assert.strictEqual(stopOwnedChildCalled, true, 'stopping must go through an injectable stopOwnedChild authority -- currently child.kill() is called directly, with no such injection point at all');
      assert.strictEqual(directKillCalled, false, 'child.kill() must never be called directly by spawnWithIntent itself -- only the injected stop authority may ultimately decide to call it (and this fake now confirms the stop WITHOUT ever calling child.kill itself, so this assertion genuinely isolates production\'s own behavior)');
    } finally {
      cleanupDir(tmp);
    }
  });

  test('ATTACK: UNKNOWN_OWNED is returned even when the durable quarantine record publish itself failed', async () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-attack-quarantinefail-'));
    const fixture = makeSpawnFixture(tmp);
    try {
      const instanceId = crypto.randomBytes(16).toString('hex');
      const quarantinePath = quarantinePathFor(fixture.repoId, instanceId);
      fs.mkdirSync(path.dirname(quarantinePath), { recursive: true });
      fs.writeFileSync(quarantinePath, JSON.stringify({ conflicting: true }), { mode: 0o600 }); // pre-existing conflict

      const registry = rbc.createSupervisorOwnedChildRegistry();
      const spawnFn = () => {
        const child = new EventEmitter();
        child.pid = 99999;
        child.kill = function () { /* never confirms -- forces UNKNOWN_OWNED */ };
        setImmediate(() => child.emit('spawn'));
        return child;
      };
      const result = await withFakeProcessIdentity(INVALID_FAKE_IDENTITY, () => rbc.spawnWithIntent(
        { instanceId, repoId: fixture.repoId, runId: fixture.runId, rootIdentity: fixture.rootIdentity },
        spawnFn,
        { registry, identityTimeoutMs: 50, stopConfirmTimeoutMs: 50, stopOwnedChild: (child) => child.kill('SIGTERM') },
      ));
      assert.strictEqual(result.state, 'UNKNOWN_OWNED', 'test precondition: ' + JSON.stringify(result));
      assert.strictEqual(Object.keys(result).length > 2, true, 'the UNKNOWN_OWNED result must reflect whether the durable quarantine record was actually published -- currently the result is blind to this, always exactly {state,ownedChildId} regardless of whether the quarantine write succeeded: ' + JSON.stringify(result));
    } finally {
      cleanupDir(tmp);
    }
  });
});

