describe('FOURTH HARD NO-GO RESPONSE -- Block A: real C2/Broker settlement', () => {
  // Shared helper: drives a REAL createAppServerConnection through
  // initialize() + login() to AUTHENTICATED, using a schema-valid
  // LoginAccountResponse shape empirically confirmed against the real
  // connection (not guessed) -- required before account/chatgptAuthTokens/
  // refresh server-requests are even considered (phase!=='AUTHENTICATED'
  // is rejected). Returns {connection, stdin, stdout, capturedIds}.
  async function createAuthenticatedConnection(refreshProvider) {
    const stdin = new PassThrough();
    const stdout = new PassThrough();
    const connection = rbc.createAppServerConnection({ stdin, stdout, refreshProvider });
    const capturedIds = {};
    stdin.on('data', (chunk) => {
      for (const line of chunk.toString('utf8').split('\n')) {
        if (!line.trim()) continue;
        try { const frame = JSON.parse(line); if (frame.method) capturedIds[frame.method] = frame.id; } catch (err) { /* partial/non-JSON chunk fragment -- ignored, later chunks complete the line */ }
      }
    });
    const initPromise = connection.initialize();
    await new Promise((resolve) => setImmediate(resolve));
    await new Promise((resolve) => rbc.writeJsonlFrame(stdout, { id: capturedIds['initialize'], result: { codexHome: '/fake', platformFamily: 'unix', platformOs: 'macos', userAgent: 'fake' } }, resolve));
    await initPromise;
    const loginPromise = connection.login({ accessToken: 'fake-access-token', chatgptAccountId: 'acct-fourth-nogo', chatgptPlanType: 'plus' });
    await new Promise((resolve) => setImmediate(resolve));
    await new Promise((resolve) => rbc.writeJsonlFrame(stdout, { id: capturedIds['account/login/start'], result: { type: 'chatgptAuthTokens', accessToken: 'fake-access-token', chatgptAccountId: 'acct-fourth-nogo', chatgptPlanType: 'plus' } }, resolve));
    await new Promise((resolve) => rbc.writeJsonlFrame(stdout, { method: 'account/updated', params: { authMode: 'chatgptAuthTokens', planType: 'plus' } }, resolve));
    const loginResult = await loginPromise;
    if (!loginResult.ok) throw new Error('createAuthenticatedConnection test-fixture precondition failed: ' + JSON.stringify(loginResult));
    return { connection, stdin, stdout, capturedIds };
  }

  test('ATTACK: C2\'s real account/chatgptAuthTokens/refresh server-request handler never awaits a Promise-returning refreshProvider -- it reads .ok synchronously on the very next line, so a genuinely async (real-source-backed) refresh is misread as shape-invalid and the connection is wrongly terminated BEFORE the real, would-be-successful credentials ever arrive', async () => {
    let resolveDeferred;
    const deferred = new Promise((resolve) => { resolveDeferred = resolve; });
    let refreshProviderCalled = false;
    const refreshProvider = () => {
      refreshProviderCalled = true;
      return deferred.then(() => ({ ok: true, accessToken: 'genuinely-async-fresh-token', chatgptAccountId: 'acct-fourth-nogo', chatgptPlanType: 'plus' }));
    };
    const { connection, stdin, stdout } = await createAuthenticatedConnection(refreshProvider);
    const postAuthWrites = [];
    stdin.on('data', (chunk) => postAuthWrites.push(chunk.toString('utf8')));

    const writePromise = new Promise((resolve) => rbc.writeJsonlFrame(stdout, { id: 999, method: 'account/chatgptAuthTokens/refresh', params: { reason: 'unauthorized' } }, resolve));
    await writePromise;
    await new Promise((resolve) => setImmediate(resolve));

    assert.strictEqual(refreshProviderCalled, true, 'test precondition: refreshProvider must genuinely have been invoked: ' + JSON.stringify(postAuthWrites));
    assert.strictEqual(connection.isStopped(), false, 'the connection must NOT be terminated yet -- the real refresh is still genuinely in flight (the deferred Promise has not resolved), so nothing about it can be known as failed at this point: currently stopped=' + connection.isStopped() + ' reason=' + connection.stopReason() + ' writes=' + JSON.stringify(postAuthWrites));

    resolveDeferred();
    await new Promise((resolve) => setImmediate(resolve));
    await new Promise((resolve) => setImmediate(resolve));

    assert.ok(postAuthWrites.some((w) => w.includes('genuinely-async-fresh-token')), 'once the genuinely async refresh resolves with real, valid credentials, C2 must deliver them as the refresh server-request\'s own successful result -- currently the connection already terminated the request as shape-invalid the instant the (unread) Promise was returned, long before this real result ever had a chance to arrive: writes=' + JSON.stringify(postAuthWrites) + ' stopped=' + connection.isStopped() + ' reason=' + connection.stopReason());
  });

  test('ATTACK: the host-wide lock releases (and hostWideBoundAccountId commits) the INSTANT the credential source read resolves -- not after any confirmation that the result was actually flushed/used over the wire -- so a second attempt can acquire the lock and proceed while the FIRST attempt\'s own credentials have not yet been confirmed delivered to anyone', async () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-nogo4-a-early-release-'));
    const fixture = makeSealedIsolationFixture(tmp);
    try {
      const authorities = rbc.createRunAuthorities(validAuthoritiesDeps(fixture, {
        expectedRoster: [{ role: 'verifier', ordinal: 0 }],
        sourceProvider: {
          read: () => Promise.resolve({ ok: true, credentials: { accessToken: syntheticSecret('nogo4-a-early-release'), chatgptAccountId: 'acct-early-release', chatgptPlanType: 'plus' }, otherCredentialFields: {}, expiresAt: futureIso(400 * 1000), sourceIdentity: 'nogo4-fixture' }),
        },
      }));
      const bound = authorities.bindConnection({ role: 'verifier', ordinal: 0 });
      assert.strictEqual(typeof bound.reason, 'undefined', JSON.stringify(bound));

      const firstResult = await bound.refreshProvider({});
      assert.strictEqual(firstResult.ok, true, 'test precondition: ' + JSON.stringify(firstResult));

      // IMMEDIATELY after the first attempt's source read resolved (and
      // therefore, per the current implementation, immediately after its
      // lock already released) -- no external confirmation of any kind
      // (a flush, a delivery ack) has happened for this first attempt at
      // all; nothing outside the broker itself could possibly know it
      // succeeded yet. A second attempt should still be LOCK_DENIED if the
      // lock genuinely stayed held until real settlement.
      const secondResult = await bound.refreshProvider({});
      assert.notStrictEqual(secondResult.reason, undefined, 'a second refresh attempt, made in the very next tick after the first attempt\'s source read merely resolved (never confirmed flushed/used anywhere), must still find the lock held -- currently it is not: ' + JSON.stringify(secondResult));
    } finally {
      cleanupDir(tmp);
    }
  });

  test('CONFIRMATION (regression guard for the broker\'s OWN internal settlement discipline -- necessary but not sufficient for the FULL exactly-once guarantee, which also depends on C2\'s own not-yet-fixed consumption of the Promise): onRefreshOutcome fires EXACTLY ONCE per attempt across multiple distinct termination causes -- never zero, never twice', async () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-nogo4-a-exactly-once-'));
    const fixture = makeSealedIsolationFixture(tmp);
    try {
      const outcomes = [];
      const authorities = rbc.createRunAuthorities(validAuthoritiesDeps(fixture, {
        expectedRoster: [{ role: 'verifier', ordinal: 0 }],
        sourceProvider: {
          read: () => Promise.reject(new Error('synthetic async source throw')),
        },
      }));
      const bound = authorities.bindConnection({ role: 'verifier', ordinal: 0 });
      assert.strictEqual(typeof bound.reason, 'undefined', JSON.stringify(bound));
      bound.onRefreshOutcome((outcome, reason) => outcomes.push({ outcome, reason }));

      const result = await bound.refreshProvider({});
      assert.strictEqual(result.ok, false, 'test precondition: an async source that rejects must settle as a failure: ' + JSON.stringify(result));
      assert.strictEqual(outcomes.length, 1, 'onRefreshOutcome must fire EXACTLY ONCE for an async source that rejects -- never zero (silently dropped), never twice (double-settled): ' + JSON.stringify(outcomes));
      assert.strictEqual(outcomes[0].reason, 'SOURCE_READ_THREW', JSON.stringify(outcomes));
    } finally {
      cleanupDir(tmp);
    }
  });

  test('ATTACK: close() does not abort its OWN genuinely in-flight async refresh attempt -- a source read that resolves AFTER close() has already been called still settles normally, its own onRefreshOutcome still fires reporting success, and nothing distinguishes this post-close settlement from a legitimate pre-close one', async () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-nogo4-a-close-races-inflight-'));
    const fixture = makeSealedIsolationFixture(tmp);
    try {
      let resolveDeferred;
      const deferred = new Promise((resolve) => { resolveDeferred = resolve; });
      const authorities = rbc.createRunAuthorities(validAuthoritiesDeps(fixture, {
        expectedRoster: [{ role: 'verifier', ordinal: 0 }],
        sourceProvider: {
          read: () => deferred.then(() => ({ ok: true, credentials: { accessToken: syntheticSecret('nogo4-a-close-races'), chatgptAccountId: 'acct-close-races', chatgptPlanType: 'plus' }, otherCredentialFields: {}, expiresAt: futureIso(400 * 1000), sourceIdentity: 'nogo4-fixture' })),
        },
      }));
      const bound = authorities.bindConnection({ role: 'verifier', ordinal: 0 });
      assert.strictEqual(typeof bound.reason, 'undefined', JSON.stringify(bound));
      const outcomes = [];
      bound.onRefreshOutcome((outcome, reason) => outcomes.push({ outcome, reason }));

      const refreshPromise = bound.refreshProvider({}); // genuinely in-flight -- deferred has not resolved.
      await new Promise((resolve) => setImmediate(resolve));

      const closeResult = bound.close();
      assert.strictEqual(closeResult.ok, true, 'test precondition: ' + JSON.stringify(closeResult));

      // The in-flight attempt's own source read resolves AFTER close().
      resolveDeferred();
      const lateResult = await refreshPromise;

      assert.notStrictEqual(lateResult.ok, true, 'a refresh attempt whose own source read resolves AFTER close() has already been called must never settle as a success -- close() must genuinely abort its OWN in-flight attempt, not merely mark the connection closed for FUTURE attempts: ' + JSON.stringify(lateResult));
      assert.notStrictEqual((outcomes[outcomes.length - 1] || {}).outcome && outcomes[outcomes.length - 1].outcome.ok, true, 'onRefreshOutcome must never report a success for an attempt that resolved after its own connection was closed: ' + JSON.stringify(outcomes));
    } finally {
      cleanupDir(tmp);
    }
  });
});

describe('THIRD HARD NO-GO RESPONSE -- Block A: real broker/C2 settlement', () => {
  test('STRUCTURAL: createAppServerConnection never references onRefreshOutcome anywhere in its own body -- the entire CredentialBroker/refreshProvider machinery from the last 2 rounds is never actually wired to the real C2 connection object', () => {
    const sourceText = fs.readFileSync(path.resolve(__dirname, '../lib/runtime-bridge-codex.cjs'), 'utf8');
    const connStart = sourceText.indexOf('function createAppServerConnection');
    assert.ok(connStart >= 0, 'test precondition: createAppServerConnection must exist as a named function');
    const nextTopLevelFn = sourceText.indexOf('\nfunction createBroker');
    const connBody = sourceText.slice(connStart, nextTopLevelFn > connStart ? nextTopLevelFn : connStart + 200000);
    assert.ok(connBody.includes('onRefreshOutcome'), 'createAppServerConnection must call bindConnection\'s (or an equivalent real broker\'s) onRefreshOutcome to receive settlement -- currently zero references exist anywhere in its own body, confirmed by direct source scan of ' + connBody.length + ' characters: the two subsystems are architecturally disconnected');
  });

  test('STRUCTURAL: the host-wide refresh lock is released INSIDE the synchronous runRefreshCheckpointOrder call (in its own finally block), never held until a real, external settlement -- confirmed via direct source read', () => {
    const sourceText = fs.readFileSync(path.resolve(__dirname, '../lib/runtime-bridge-codex.cjs'), 'utf8');
    const fnStart = sourceText.indexOf('function runRefreshCheckpointOrder');
    assert.ok(fnStart >= 0, 'test precondition: runRefreshCheckpointOrder must exist as a named function');
    const fnBody = sourceText.slice(fnStart, sourceText.indexOf('\n    function refreshProvider', fnStart));
    assert.ok(!/releaseRefreshLock\(connectionId\);\s*\}\s*\}\s*attestor\('post'/.test(fnBody.replace(/\s+/g, ' ')), 'the lock release must be deferred until a genuine external settlement callback fires (confirmed flush/write-failure/timeout/STOP), never happen synchronously inside this same call\'s own finally block before returning: ' + fnBody.slice(0, 400));
  });

  test('STRUCTURAL: the refresh lock\'s owner identity is the connectionId, never a fresh CSPRNG attemptId minted per attempt', () => {
    const sourceText = fs.readFileSync(path.resolve(__dirname, '../lib/runtime-bridge-codex.cjs'), 'utf8');
    const fnStart = sourceText.indexOf('function acquireRefreshLock');
    assert.ok(fnStart >= 0, 'test precondition: acquireRefreshLock must exist');
    const callSiteIdx = sourceText.indexOf('acquireRefreshLock(connectionId)');
    assert.strictEqual(callSiteIdx, -1, 'acquireRefreshLock must be called with a fresh, per-attempt CSPRNG attemptId, never the connectionId directly -- currently called as acquireRefreshLock(connectionId), confirmed by direct source scan (a caller who learns a connectionId could otherwise correlate/interfere with lock ownership across unrelated attempts on the same connection)');
  });

  test('ATTACK: account binding is scoped to a SINGLE connection (boundAccountId is a per-connection closure variable) -- two DIFFERENT connections on the SAME composition root can each bind a DIFFERENT account with zero cross-connection conflict, when PLAN.md\'s own account-integrity intent implies ONE host-wide bound account per run', () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-nogo3-a-hostwide-account-'));
    const fixture = makeSealedIsolationFixture(tmp);
    try {
      // A SINGLE shared sourceProvider (matching the real host-wide
      // singleton this composition root actually injects -- sourceProvider
      // is constructor-injected ONCE, never per-connection). Call-ordered:
      // the first 2 refreshProvider() calls (A, B) report the SAME shared
      // account; the 3rd (C) reports a DIFFERENT one -- all three against
      // the SAME composition root instance, never a second one.
      let readCallCount = 0;
      const deps = validAuthoritiesDeps(fixture, {
        // A 3rd verifier ordinal (rather than quality-gater, which is not
        // in DEFAULT_ROOT_ROSTER and fails ROLE_NOT_IN_ROOT_ROSTER) so all
        // three connections stay compatible with rootRoster's default.
        expectedRoster: [{ role: 'verifier', ordinal: 0 }, { role: 'verifier', ordinal: 1 }, { role: 'verifier', ordinal: 2 }],
        sourceProvider: {
          read: () => {
            readCallCount += 1;
            if (readCallCount <= 2) {
              return { ok: true, credentials: { accessToken: syntheticSecret('nogo3-a-acct-' + readCallCount), chatgptAccountId: 'shared-run-should-only-ever-bind-once', chatgptPlanType: 'plus' }, otherCredentialFields: {}, expiresAt: futureIso(400 * 1000), sourceIdentity: 'nogo3-fixture' };
            }
            return { ok: true, credentials: { accessToken: syntheticSecret('nogo3-a-acct-different'), chatgptAccountId: 'DIFFERENT-ACCOUNT-should-be-rejected-if-host-wide', chatgptPlanType: 'plus' }, otherCredentialFields: {}, expiresAt: futureIso(400 * 1000), sourceIdentity: 'nogo3-fixture' };
          },
        },
      });
      const authorities = rbc.createRunAuthorities(deps);
      const boundA = authorities.bindConnection({ role: 'verifier', ordinal: 0 });
      const boundB = authorities.bindConnection({ role: 'verifier', ordinal: 1 });
      assert.strictEqual(typeof boundA.reason, 'undefined', JSON.stringify(boundA));
      assert.strictEqual(typeof boundB.reason, 'undefined', JSON.stringify(boundB));
      // Fourth HARD NO-GO fix: the host-wide lock now stays held until a
      // confirmed settlement -- registering onRefreshOutcome (matching what
      // a real caller would do) lets each connection's own attempt settle
      // and release the shared lock so the NEXT connection's own attempt
      // can proceed, matching this test's own intent (host-wide ACCOUNT
      // scoping, not lock-contention).
      boundA.onRefreshOutcome(() => {});
      boundB.onRefreshOutcome(() => {});

      const resultA = boundA.refreshProvider({});
      assert.strictEqual(resultA.ok, true, 'test precondition: connection A must bind the shared account cleanly: ' + JSON.stringify(resultA));

      // Connection B, on the SAME composition root/run, now ALSO reads and
      // reports the SAME account (not a different one) -- if account
      // binding were genuinely host-wide, B would either need to observe
      // the SAME already-bound account (which it does here) OR, if B tried
      // a DIFFERENT account, be rejected. This test isolates the narrower,
      // more direct structural fact: boundAccountId itself is declared
      // inside bindConnection's own per-connection closure (source-read
      // confirmed above in the STRUCTURAL test), so B's own binding can
      // never even observe what A bound in the first place.
      const resultB = boundB.refreshProvider({});
      assert.strictEqual(resultB.ok, true, JSON.stringify(resultB));

      // The actual gap: a THIRD connection, on the SAME composition root
      // (the SAME authorities instance -- never a second createRunAuthorities
      // call, which would be a materially different, cross-instance-durable
      // feature nobody's asked for), asserting a DIFFERENT account must be
      // rejected if account binding is genuinely host-wide.
      const boundC = authorities.bindConnection({ role: 'verifier', ordinal: 2 });
      assert.strictEqual(typeof boundC.reason, 'undefined', JSON.stringify(boundC));
      boundC.onRefreshOutcome(() => {});
      const resultC = boundC.refreshProvider({});
      assert.strictEqual(resultC.ok, false, 'a THIRD connection, on the SAME composition root as A and B, asserting a DIFFERENT account than what PLAN.md intends as the SAME run\'s single bound account must be rejected (ACCOUNT_MISMATCH) if account binding is genuinely host-wide -- currently each connection\'s own boundAccountId is independent, so this succeeds cleanly: ' + JSON.stringify(resultC));
    } finally {
      cleanupDir(tmp);
    }
  });

  test('ATTACK: a dirty pre/during checkpoint (LEAK_DETECTED) does not abort the in-flight refresh attempt -- real credentials are still returned as long as the source read itself happens to succeed, even though the broker was JUST poisoned by this exact attempt\'s own pre/during scan', () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-nogo3-a-dirtycheckpoint-'));
    const fixture = makeSealedIsolationFixture(tmp);
    const PLANTED_SECRET = syntheticSecret('nogo3-a-dirty-precheck');
    try {
      // sourceProvider.read() must return PLANTED_SECRET ITSELF (not a
      // separately-generated one) so the prior refresh below genuinely
      // registers PLANTED_SECRET into secretMatcher's history -- otherwise
      // the later capture mentioning it can never be caught as a leak at
      // all, making this test structurally unsatisfiable regardless of
      // whether the production code is correct.
      const authorities = rbc.createRunAuthorities(validAuthoritiesDeps(fixture, {
        sourceProvider: {
          read: () => ({ ok: true, credentials: { accessToken: PLANTED_SECRET, chatgptAccountId: 'acct-dirty-test', chatgptPlanType: 'plus' }, otherCredentialFields: {}, expiresAt: futureIso(400 * 1000), sourceIdentity: 'nogo3-fixture' }),
        },
      }));
      const bound = authorities.bindConnection({ role: 'verifier', ordinal: 0 });
      assert.strictEqual(typeof bound.reason, 'undefined', JSON.stringify(bound));

      // A prior refresh registers PLANTED_SECRET into secretMatcher's
      // history (clean at the time -- nothing captured it yet).
      const priorRefresh = bound.refreshProvider({});
      assert.strictEqual(priorRefresh.ok, true, 'test precondition: ' + JSON.stringify(priorRefresh));

      // NOW plant a capture mentioning that already-known secret -- the
      // NEXT refresh's own pre/during checkpoint (a genuine fullWalk) must
      // catch this and poison the broker BEFORE the source read/settlement
      // even happens.
      authorities.captureSink.register(Buffer.from('later child output mentioning ' + PLANTED_SECRET, 'utf8'));

      const dirtyRefresh = bound.refreshProvider({});
      assert.strictEqual(dirtyRefresh.ok, false, 'a refresh attempt whose OWN pre/during checkpoint detects a dirty capture (poisoning the broker) must abort and never return real credentials, regardless of whether the underlying source read would have otherwise succeeded: ' + JSON.stringify(dirtyRefresh));
    } finally {
      cleanupDir(tmp);
    }
  });

  test('CONFIRMATION (was ATTACK, genuine deterministic reentrancy, replacing the sequential-only "race" test; discovered already passing during the Round 8 inventory reconciliation pass -- the async-refreshProvider fix this test was waiting on has since landed, confirmed genuine via all 4 of its own specific assertions, not a masked pass): connection A\'s sourceProvider.read() is mid-flight (deliberately held open under test control) while connection B attempts its OWN refresh -- B is correctly rejected LOCK_DENIED without perturbing A, and B still produces its own real pre/during/post checkpoint triplet, never silently skipping it', async () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-nogo3-a-reentrancy-'));
    const fixture = makeSealedIsolationFixture(tmp);
    try {
      let resolveADeferredRead;
      const aDeferredRead = new Promise((resolve) => { resolveADeferredRead = resolve; });
      let readCallCountForA = 0;
      let readCallCountForB = 0;

      const authorities = rbc.createRunAuthorities(validAuthoritiesDeps(fixture, {
        sourceProvider: {
          // A single shared sourceProvider (matching the real host-wide
          // singleton this composition root actually injects) -- the FIRST
          // call (connection A's) deliberately hangs on aDeferredRead,
          // under this test's own control, until explicitly resolved below.
          // Any SUBSEQUENT call (connection B's, while A is still pending)
          // resolves immediately -- this test asserts B must never even
          // REACH this second call in the first place (rejected earlier, at
          // the lock).
          read: async () => {
            readCallCountForA === 0 ? readCallCountForA++ : readCallCountForB++;
            if (readCallCountForA === 1 && readCallCountForB === 0) {
              await aDeferredRead;
              return { ok: true, credentials: { accessToken: syntheticSecret('nogo3-a-reentrant-A'), chatgptAccountId: 'acct-reentrant', chatgptPlanType: 'plus' }, otherCredentialFields: {}, expiresAt: futureIso(400 * 1000), sourceIdentity: 'nogo3-fixture' };
            }
            return { ok: true, credentials: { accessToken: syntheticSecret('nogo3-a-reentrant-B'), chatgptAccountId: 'acct-reentrant', chatgptPlanType: 'plus' }, otherCredentialFields: {}, expiresAt: futureIso(400 * 1000), sourceIdentity: 'nogo3-fixture' };
          },
        },
      }));
      const boundA = authorities.bindConnection({ role: 'verifier', ordinal: 0 });
      const boundB = authorities.bindConnection({ role: 'verifier', ordinal: 1 });
      assert.strictEqual(typeof boundA.reason, 'undefined', JSON.stringify(boundA));
      assert.strictEqual(typeof boundB.reason, 'undefined', JSON.stringify(boundB));

      // Fire A's refresh WITHOUT awaiting it yet -- it should immediately
      // enter its own source read and hang on aDeferredRead.
      const resultAPromise = Promise.resolve(boundA.refreshProvider({}));

      // Give the event loop a turn so A genuinely reaches its own pending
      // read before B is attempted.
      await new Promise((resolve) => setImmediate(resolve));

      // B attempts its OWN refresh WHILE A is still holding the lock.
      const resultB = await Promise.resolve(boundB.refreshProvider({}));
      assert.strictEqual(resultB.reason, 'LOCK_DENIED', 'connection B must be rejected LOCK_DENIED while connection A genuinely still holds the host-wide lock (mid-flight, not yet settled): ' + JSON.stringify(resultB));
      assert.strictEqual(readCallCountForB, 0, 'B must never even reach its own sourceProvider.read() call once rejected at the lock -- B was rejected BEFORE attempting a read, confirmed by this counter staying at 0');

      // Now let A's own read resolve, and confirm A settles normally,
      // undisturbed by B's rejected attempt.
      resolveADeferredRead();
      const resultA = await resultAPromise;
      assert.strictEqual(resultA.ok, true, 'connection A must settle normally, undisturbed by B\'s rejected concurrent attempt: ' + JSON.stringify(resultA));

      // B must still have produced its own real pre/during/post checkpoint
      // triplet for ITS OWN rejected attempt -- never silently skipped.
      const checkpointFile = path.join(rll.registryRepoDir({ repoId: fixture.repoId }), 'credential-absence-checkpoints', fixture.runId + '.json');
      const record = readJsonFile(checkpointFile);
      // Third HARD NO-GO Block B fixture fix: names now carry an
      // "@role:ordinal" correlation suffix (e.g. "refresh:1:pre@verifier:0").
      const bAttemptNames = record.checkpoints.filter((c) => /^refresh:\d+:(pre|during|post)@/.test(c.name)).map((c) => c.name);
      // At least 6 total entries across A and B combined (2 full triplets);
      // this alone does not prove B specifically produced all 3, but a
      // LOCK_DENIED-rejected attempt that skipped its own checkpoints
      // entirely would leave fewer than 6.
      assert.ok(bAttemptNames.length >= 6, 'both connections\' refresh attempts must each produce a real pre/during/post checkpoint triplet, including B\'s own rejected one -- never silently skipped just because the attempt was ultimately LOCK_DENIED: ' + JSON.stringify(bAttemptNames));
    } finally {
      cleanupDir(tmp);
    }
  });
});

describe('THIRD HARD NO-GO RESPONSE -- Block B: real sequence/cardinality machine and durable evidence', () => {
  test('ATTACK: completeness is Set-membership only, blind to ORDER -- calling recordLogin("post") BEFORE recordLogin("pre") still reaches complete:true once every required NAME has appeared at least once, regardless of the sequence they appeared in', () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-nogo3-b-order-'));
    const fixture = makeSealedIsolationFixture(tmp);
    try {
      const authorities = rbc.createRunAuthorities(validAuthoritiesDeps(fixture, { expectedRoster: [{ role: 'verifier', ordinal: 0 }] }));
      const bound = authorities.bindConnection({ role: 'verifier', ordinal: 0 });
      assert.strictEqual(typeof bound.reason, 'undefined', JSON.stringify(bound));
      const recorder = bound.checkout();

      const postFirst = recorder.recordLogin('post');
      assert.strictEqual(postFirst.ok, true, 'test precondition: ' + JSON.stringify(postFirst));
      const preSecond = recorder.recordLogin('pre');
      assert.strictEqual(preSecond.ok, true, 'test precondition: ' + JSON.stringify(preSecond));
      recorder.recordTurn('pre');
      recorder.recordTurn('during');
      recorder.recordTurn('post');
      bound.close();

      const checkpointFile = path.join(rll.registryRepoDir({ repoId: fixture.repoId }), 'credential-absence-checkpoints', fixture.runId + '.json');
      const record = readJsonFile(checkpointFile);
      assert.strictEqual(record.complete, false, 'a checkpoint sequence recorded OUT OF ORDER (login:post BEFORE login:pre) must never be treated as a valid complete sequence, regardless of whether every required NAME eventually appeared -- currently completeness is a bare Set-membership check with zero order validation: ' + JSON.stringify(record.checkpoints.map((c) => c.name)));
    } finally {
      cleanupDir(tmp);
    }
  });

  test('ATTACK: a dangling PARTIAL refresh attestation (checkout().recordRefresh("pre") called once, with no matching during/post) has ZERO effect on completeness either way -- confirms refresh checkpoints are entirely outside the required sequence/cardinality machine', () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-nogo3-b-refresh-cardinality-'));
    const fixture = makeSealedIsolationFixture(tmp);
    try {
      const authorities = rbc.createRunAuthorities(validAuthoritiesDeps(fixture, { expectedRoster: [{ role: 'verifier', ordinal: 0 }] }));
      const bound = authorities.bindConnection({ role: 'verifier', ordinal: 0 });
      assert.strictEqual(typeof bound.reason, 'undefined', JSON.stringify(bound));
      const recorder = bound.checkout();
      recorder.recordLogin('pre');
      recorder.recordLogin('post');
      recorder.recordTurn('pre');
      recorder.recordTurn('during');
      recorder.recordTurn('post');
      const danglingRefresh = recorder.recordRefresh('pre');
      assert.strictEqual(danglingRefresh.ok, true, 'test precondition: ' + JSON.stringify(danglingRefresh));
      bound.close();

      const checkpointFile = path.join(rll.registryRepoDir({ repoId: fixture.repoId }), 'credential-absence-checkpoints', fixture.runId + '.json');
      const record = readJsonFile(checkpointFile);
      assert.strictEqual(record.complete, false, 'a refresh attempt that started (pre) but never recorded its own during/post must invalidate completeness (an abandoned/hung refresh attempt must never be silently ignored) -- currently refresh-family checkpoint names are outside REQUIRED_NAMES entirely, so a dangling partial attempt has no effect on the result either way: ' + JSON.stringify(record.checkpoints.map((c) => c.name)));
    } finally {
      cleanupDir(tmp);
    }
  });

  test('CONFIRMATION (was STRUCTURAL/ATTACK; discovered already passing during the Round 8 inventory reconciliation pass -- recordCleanup has since been genuinely implemented): the connection recorder surface exposes a genuine recordCleanup(phase) method distinguishing pre/post cleanup, matching the pre/during/post pattern already used for login and turn', () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-nogo3-b-recordcleanup-'));
    const fixture = makeSealedIsolationFixture(tmp);
    try {
      const authorities = rbc.createRunAuthorities(validAuthoritiesDeps(fixture, { expectedRoster: [{ role: 'verifier', ordinal: 0 }] }));
      const bound = authorities.bindConnection({ role: 'verifier', ordinal: 0 });
      assert.strictEqual(typeof bound.reason, 'undefined', JSON.stringify(bound));
      const recorder = bound.checkout();
      assert.strictEqual(typeof recorder.recordCleanup, 'function', 'the connection recorder surface must expose a genuine recordCleanup(phase) method distinguishing pre/post cleanup, matching the pre/during/post pattern already used for login and turn: ' + JSON.stringify(Object.keys(recorder).sort()));
    } finally {
      cleanupDir(tmp);
    }
  });

  test('ATTACK: completeness never requires the FULL expectedRoster to close -- with a 3-member roster, only ONE member ever binding and completing its own sequence is enough to reach complete:true, even though the other two roster members never bound at all', () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-nogo3-b-roster-closure-'));
    const fixture = makeSealedIsolationFixture(tmp);
    try {
      const authorities = rbc.createRunAuthorities(validAuthoritiesDeps(fixture)); // DEFAULT_EXPECTED_ROSTER: 3 members.
      const onlyBound = authorities.bindConnection({ role: 'verifier', ordinal: 0 });
      assert.strictEqual(typeof onlyBound.reason, 'undefined', JSON.stringify(onlyBound));
      const recorder = onlyBound.checkout();
      recorder.recordLogin('pre');
      recorder.recordLogin('post');
      recorder.recordTurn('pre');
      recorder.recordTurn('during');
      recorder.recordTurn('post');
      onlyBound.close();
      // { role: 'verifier', ordinal: 1 } and { role: 'quality-gater', ordinal: 0 } never bind at all.

      const checkpointFile = path.join(rll.registryRepoDir({ repoId: fixture.repoId }), 'credential-absence-checkpoints', fixture.runId + '.json');
      const record = readJsonFile(checkpointFile);
      assert.strictEqual(record.complete, false, 'completeness must require EVERY member of the injected expectedRoster (3 members here) to have bound and completed its own required sequence -- currently completeness is checked as a single run-wide Set of names with no per-roster-member accounting, so ONE connection completing its own sequence satisfies the whole run even though 2 of the 3 roster members never bound at all: ' + JSON.stringify(record.checkpoints.map((c) => c.name)));
    } finally {
      cleanupDir(tmp);
    }
  });

  test('ATTACK: a transient checkpoint write failure (temp-write/fsync/rename/barrier) does not permanently invalidate evidence -- the failed checkpoint is pushed into shared in-memory state as ok:true regardless, and a LATER successful checkpoint write silently re-publishes (heals) the entire array including the never-durably-recorded entry, reaching complete:true despite the earlier failure', () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-nogo3-b-write-failure-heals-'));
    const fixture = makeSealedIsolationFixture(tmp);
    try {
      const authorities = rbc.createRunAuthorities(validAuthoritiesDeps(fixture, { expectedRoster: [{ role: 'verifier', ordinal: 0 }] }));
      const bound = authorities.bindConnection({ role: 'verifier', ordinal: 0 }); // 'bind' checkpoint durably recorded; creates the checkpoints dir.
      assert.strictEqual(typeof bound.reason, 'undefined', JSON.stringify(bound));
      const recorder = bound.checkout();

      const checkpointDir = path.join(rll.registryRepoDir({ repoId: fixture.repoId }), 'credential-absence-checkpoints');
      const checkpointFile = path.join(checkpointDir, fixture.runId + '.json');
      assert.ok(fs.existsSync(checkpointFile), 'test precondition: bind must have already created the checkpoint file');

      fs.chmodSync(checkpointDir, 0o500);
      let loginPreResult;
      try {
        loginPreResult = recorder.recordLogin('pre');
      } finally {
        fs.chmodSync(checkpointDir, 0o700); // always restore, even if the assertion below throws.
      }
      assert.strictEqual(loginPreResult.ok, false, 'test precondition: the write must genuinely fail while the directory is unwritable: ' + JSON.stringify(loginPreResult));
      assert.strictEqual(loginPreResult.reason, 'CHECKPOINT_WRITE_FAILED', 'test precondition: ' + JSON.stringify(loginPreResult));

      const loginPost = recorder.recordLogin('post');
      assert.strictEqual(loginPost.ok, true, 'test precondition: ' + JSON.stringify(loginPost));
      recorder.recordTurn('pre');
      recorder.recordTurn('during');
      recorder.recordTurn('post');
      bound.close();

      const record = readJsonFile(checkpointFile);
      assert.strictEqual(record.complete, false, 'a run that ever experienced a genuine checkpoint write/fsync/rename/barrier failure must be PERMANENTLY invalidated (poisoned) for the rest of its lifetime, never allowed to silently "heal" back to complete:true once a later, unrelated checkpoint happens to write successfully -- currently the failed checkpoint is still pushed into shared in-memory state as ok:true and gets transparently re-published by the next successful write: ' + JSON.stringify(record));
    } finally {
      cleanupDir(tmp);
    }
  });

  test('ATTACK: publishAndFinalize() trusts an on-disk complete:true flag at face value -- a tampered/corrupted record claiming complete:true with an OBVIOUSLY incomplete checkpoints array (empty) is never re-derived or rejected', async () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-nogo3-b-finalize-blind-trust-'));
    const fixture = makeSealedIsolationFixture(tmp);
    try {
      // findings-3+5 item 1: the run's own mode must equal tamperedRecord's
      // mode below (app-server), or EVIDENCE_MODE_MISMATCH fires before this
      // test's own intended (empty-checkpoints) check is ever reached.
      const authorities = rbc.createRunAuthorities(validAuthoritiesDeps(fixture, { mode: 'app-server', expectedRoster: [{ role: 'verifier', ordinal: 0 }] }));
      const bound = authorities.bindConnection({ role: 'verifier', ordinal: 0 });
      assert.strictEqual(typeof bound.reason, 'undefined', JSON.stringify(bound));
      bound.close(); // release the lease so publishAndFinalize doesn't reject on LEASES_ACTIVE first.

      const checkpointFile = path.join(rll.registryRepoDir({ repoId: fixture.repoId }), 'credential-absence-checkpoints', fixture.runId + '.json');
      const tamperedRecord = {
        schema: 'coordination/credential-absence-checkpoints/v1',
        run_id: fixture.runId,
        mode: 'app-server', // fourth HARD NO-GO fix: mode is now validated against PLAN.md ~L555's real enum (app-server|mcp) -- 'conformance' would be rejected EVIDENCE_MODE_INVALID before ever reaching this test's own intended (empty-checkpoints) check.
        root_ids: [rbc.computeRootId(fixture.instanceId)], // findings-3+5 item 2: root_ids is now validated against this run's own sealHandle-derived id.
        checkpoints: [], // OBVIOUSLY incomplete -- not even one required name present.
        complete: true, // the lie.
      };
      // Explicit mode:0o600 -- matches the real production writer exactly, so
      // the fd-bound reader's exact-mode check never rejects this fabrication.
      fs.writeFileSync(checkpointFile, JSON.stringify(tamperedRecord), { mode: 0o600 });

      const result = await authorities.publishAndFinalize();
      // findings-3+5 item 8 landed AFTER this test was first written: a
      // record whose complete:true LIES against a fresh re-derivation off
      // its own checkpoints array is now caught by the MORE SPECIFIC
      // EVIDENCE_COMPLETE_FLAG_MISMATCH gate (checked before the plain
      // incompleteness fallback) rather than the generic EVIDENCE_INCOMPLETE
      // -- the security property this test exists to prove (complete:true is
      // never blindly trusted, state never leaves OPEN) is unchanged; only
      // the diagnostic reason got more precise.
      assert.strictEqual(result && result.state, 'OPEN', 'a tampered record must never be accepted: ' + JSON.stringify(result));
      assert.strictEqual(result && result.reason, 'EVIDENCE_COMPLETE_FLAG_MISMATCH', 'publishAndFinalize must re-derive completeness from the checkpoints array itself, never trust a bare complete:true flag at face value -- a record with an EMPTY checkpoints array claiming complete:true must still be rejected, but currently the flag is trusted as-is and the call proceeds past this gate: ' + JSON.stringify(result));
    } finally {
      cleanupDir(tmp);
    }
  });

  test('ATTACK: publishAndFinalize() never cross-checks the checkpoint record\'s own run_id against the run actually being finalized -- a tampered record that is otherwise legitimately complete, but for a COMPLETELY DIFFERENT run_id, is accepted at face value (confused-deputy risk)', async () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-nogo3-b-finalize-runid-'));
    const fixture = makeSealedIsolationFixture(tmp);
    try {
      // mode: 'app-server' override -- the ambient default ('conformance') is
      // not a valid mode (PLAN.md ~L555's real enum is app-server|mcp), so the
      // genuine record built below would otherwise carry an invalid mode and
      // the tampered-run_id check this test targets would never be reached
      // (EVIDENCE_MODE_INVALID fires first, before the run_id check).
      const authorities = rbc.createRunAuthorities(validAuthoritiesDeps(fixture, { expectedRoster: [{ role: 'verifier', ordinal: 0 }], mode: 'app-server' }));
      const bound = authorities.bindConnection({ role: 'verifier', ordinal: 0 });
      assert.strictEqual(typeof bound.reason, 'undefined', JSON.stringify(bound));
      const recorder = bound.checkout();
      recorder.recordLogin('pre');
      recorder.recordLogin('post');
      recorder.recordTurn('pre');
      recorder.recordTurn('during');
      recorder.recordTurn('post');
      recorder.recordCleanup('pre'); // now mandatory -- Block B item 3, this round.
      recorder.recordCleanup('post');
      bound.close();

      const checkpointFile = path.join(rll.registryRepoDir({ repoId: fixture.repoId }), 'credential-absence-checkpoints', fixture.runId + '.json');
      const genuineRecord = readJsonFile(checkpointFile);
      assert.strictEqual(genuineRecord.complete, true, 'test precondition: the genuine record must be legitimately complete on its own before this test tampers only its run_id: ' + JSON.stringify(genuineRecord));
      const tamperedRecord = Object.assign({}, genuineRecord, { run_id: 'a-totally-different-run-id-than-this-one' });
      // Explicit mode:0o600 -- matches the real production writer exactly, so
      // the fd-bound reader's exact-mode check never rejects this fabrication.
      fs.writeFileSync(checkpointFile, JSON.stringify(tamperedRecord), { mode: 0o600 });

      const result = await authorities.publishAndFinalize();
      // Reason taxonomy is now specific (isCredentialEvidenceComplete's own
      // run_id cross-check, this round's Block B fix) -- EVIDENCE_RUN_ID_MISMATCH,
      // not the older generic EVIDENCE_INCOMPLETE.
      assert.strictEqual(result && result.reason, 'EVIDENCE_RUN_ID_MISMATCH', 'publishAndFinalize must reject a checkpoint record whose own run_id does not match the run actually being finalized, regardless of its complete flag -- currently run_id is never even inspected: ' + JSON.stringify(result));
    } finally {
      cleanupDir(tmp);
    }
  });

  test('ATTACK (incidental finding, flagged by team-lead): TWO independently-named, entirely uncorrelated refresh checkpoint families exist -- checkout().recordRefresh uses "refresh-checkout:<phase>", while refreshProvider()/runRefreshCheckpointOrder uses "refresh:<attemptId>:<phase>" -- a fully-complete provider-family refresh coexisting with a DANGLING, incomplete checkout-family refresh (pre only, no during/post) still reaches complete:true, since REQUIRED_NAMES validates NEITHER family, so an abandoned/hung refresh in either one is invisible regardless of what else on the connection completed cleanly', () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-nogo3-b-two-refresh-families-'));
    const fixture = makeSealedIsolationFixture(tmp);
    try {
      const authorities = rbc.createRunAuthorities(validAuthoritiesDeps(fixture, {
        expectedRoster: [{ role: 'verifier', ordinal: 0 }],
        sourceProvider: fakeSourceProviderBlock2({ read: () => ({ ok: true, credentials: { token: syntheticSecret('two-families-source') }, otherCredentialFields: {}, expiresAt: futureIso(400 * 1000), sourceIdentity: 'two-families-fixture' }) }),
      }));
      const bound = authorities.bindConnection({ role: 'verifier', ordinal: 0 });
      assert.strictEqual(typeof bound.reason, 'undefined', JSON.stringify(bound));
      const recorder = bound.checkout();
      recorder.recordLogin('pre'); recorder.recordLogin('post');
      recorder.recordTurn('pre'); recorder.recordTurn('during'); recorder.recordTurn('post');

      // Provider family: a genuinely COMPLETE refresh (all 3 phases fire
      // automatically inside runRefreshCheckpointOrder).
      const providerResult = bound.refreshProvider({});
      assert.strictEqual(providerResult.ok, true, 'test precondition: ' + JSON.stringify(providerResult));

      // Checkout family: a DANGLING, incomplete refresh -- pre only, never
      // followed by during/post (an abandoned/hung attempt).
      const danglingCheckoutRefresh = recorder.recordRefresh('pre');
      assert.strictEqual(danglingCheckoutRefresh.ok, true, 'test precondition: ' + JSON.stringify(danglingCheckoutRefresh));
      bound.close();

      const checkpointFile = path.join(rll.registryRepoDir({ repoId: fixture.repoId }), 'credential-absence-checkpoints', fixture.runId + '.json');
      const record = readJsonFile(checkpointFile);
      const checkoutFamilyNames = record.checkpoints.filter((c) => c.name.startsWith('refresh-checkout:')).map((c) => c.name);
      const providerFamilyNames = record.checkpoints.filter((c) => c.name.startsWith('refresh:')).map((c) => c.name);
      assert.ok(checkoutFamilyNames.length === 1 && providerFamilyNames.length === 3, 'test precondition: one dangling checkout-family entry, one complete 3-phase provider-family attempt: ' + JSON.stringify({ checkoutFamilyNames, providerFamilyNames }));
      assert.strictEqual(record.complete, false, 'a dangling, incomplete refresh in EITHER checkpoint family must invalidate completeness, even while the OTHER family completed cleanly -- currently REQUIRED_NAMES validates neither family by name, so this abandoned checkout-family attempt has zero effect: ' + JSON.stringify(record));
    } finally {
      cleanupDir(tmp);
    }
  });
});

// ══════════════════════════════════════════════════════════════════════════
// FOURTH HARD NO-GO RESPONSE -- Block B: durable credential evidence,
// fail-open paths. Verified directly against current source (computeCredential
// EvidenceComplete/isCredentialEvidenceComplete, ~L4433-5046) and PLAN.md's
// own frozen text (~L550-560) before writing anything:
//   - isCredentialEvidenceComplete() STILL has `if (!fs.existsSync(p)) return
//     true;` -- a run that never bound any connection (zero checkpoint
//     activity, zero evidence either way) is treated as complete.
//   - PLAN.md ~L557 lists "pre/post cleanup" in the SAME mandatory-coverage
//     sentence as pre/post login and pre/during/post turn -- but the shipped
//     CHECKPOINT_FAMILY_REQUIRED_PHASES object deliberately excludes
//     'cleanup', treating it as merely optional-if-started.
//   - PLAN.md ~L554 requires the literal schema string, ~L555 requires mode
//     to be the enum app-server|mcp, ~L560 says "schema validation... required
//     before evidence manifest publication" -- but isCredentialEvidenceComplete
//     only ever checks run_id, never schema or mode at all.
// ══════════════════════════════════════════════════════════════════════════

describe('FOURTH HARD NO-GO RESPONSE -- Block B: durable evidence fail-open paths', () => {
  test('ATTACK: a run that never bound ANY connection at all (zero checkpoint file, zero evidence either way) is treated as complete -- publishAndFinalize proceeds past the evidence gate with no positive proof that credential evidence was ever genuinely unnecessary for this run', async () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-nogo4-b-missing-file-'));
    const fixture = makeSealedIsolationFixture(tmp);
    try {
      const authorities = rbc.createRunAuthorities(validAuthoritiesDeps(fixture, { expectedRoster: [{ role: 'verifier', ordinal: 0 }] }));
      // Deliberately NEVER bind any connection -- no checkpoint file is ever
      // created for this run at all.
      const checkpointFile = path.join(rll.registryRepoDir({ repoId: fixture.repoId }), 'credential-absence-checkpoints', fixture.runId + '.json');
      assert.strictEqual(fs.existsSync(checkpointFile), false, 'test precondition: no checkpoint file must exist for this run');

      const result = await authorities.publishAndFinalize();
      assert.notStrictEqual(result.reason, 'CONFIRMED_BEFORE_WRITE', 'a run with a totally absent checkpoint file (zero evidence either way, not proven-unnecessary) must not proceed past the evidence gate as if positively confirmed complete -- currently it does: ' + JSON.stringify(result));
    } finally {
      cleanupDir(tmp);
    }
  });

  test('ATTACK: recordCleanup is optional, never required, despite PLAN.md ~L557 listing "pre/post cleanup" in the SAME mandatory-coverage sentence as pre/post login and pre/during/post turn -- a connection that completes login+turn fully but NEVER calls recordCleanup at all still reaches complete:true', () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-nogo4-b-cleanup-optional-'));
    const fixture = makeSealedIsolationFixture(tmp);
    try {
      const authorities = rbc.createRunAuthorities(validAuthoritiesDeps(fixture, { expectedRoster: [{ role: 'verifier', ordinal: 0 }] }));
      const bound = authorities.bindConnection({ role: 'verifier', ordinal: 0 });
      assert.strictEqual(typeof bound.reason, 'undefined', JSON.stringify(bound));
      const recorder = bound.checkout();
      recorder.recordLogin('pre'); recorder.recordLogin('post');
      recorder.recordTurn('pre'); recorder.recordTurn('during'); recorder.recordTurn('post');
      // recordCleanup is NEVER called at all -- not even started.
      bound.close();

      const checkpointFile = path.join(rll.registryRepoDir({ repoId: fixture.repoId }), 'credential-absence-checkpoints', fixture.runId + '.json');
      const record = readJsonFile(checkpointFile);
      const cleanupEntries = record.checkpoints.filter((c) => c.name.startsWith('cleanup:'));
      assert.strictEqual(cleanupEntries.length, 0, 'test precondition: recordCleanup must genuinely never have been called: ' + JSON.stringify(record.checkpoints));
      assert.strictEqual(record.complete, false, 'PLAN.md ~L557 requires checkpoint names to cover "pre/post cleanup" as part of the SAME mandatory list as login/turn -- a connection that never calls recordCleanup at all (not merely started-and-abandoned) must not reach complete:true -- currently it does: ' + JSON.stringify(record));
    } finally {
      cleanupDir(tmp);
    }
  });

  test('ATTACK: publishAndFinalize() never validates the durable record\'s own schema field -- a tampered record with a WRONG schema string, but otherwise genuinely complete checkpoints and a matching run_id, is still accepted', async () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-nogo4-b-wrong-schema-'));
    const fixture = makeSealedIsolationFixture(tmp);
    try {
      const authorities = rbc.createRunAuthorities(validAuthoritiesDeps(fixture, { expectedRoster: [{ role: 'verifier', ordinal: 0 }] }));
      const bound = authorities.bindConnection({ role: 'verifier', ordinal: 0 });
      assert.strictEqual(typeof bound.reason, 'undefined', JSON.stringify(bound));
      const recorder = bound.checkout();
      recorder.recordLogin('pre'); recorder.recordLogin('post');
      recorder.recordTurn('pre'); recorder.recordTurn('during'); recorder.recordTurn('post');
      recorder.recordCleanup('pre'); recorder.recordCleanup('post');
      bound.close();

      const checkpointFile = path.join(rll.registryRepoDir({ repoId: fixture.repoId }), 'credential-absence-checkpoints', fixture.runId + '.json');
      const genuineRecord = readJsonFile(checkpointFile);
      const tamperedRecord = Object.assign({}, genuineRecord, { schema: 'totally-wrong-schema/v99' });
      // Explicit mode:0o600 -- matches the real production writer exactly, so
      // the fd-bound reader's exact-mode check never rejects this fabrication.
      fs.writeFileSync(checkpointFile, JSON.stringify(tamperedRecord), { mode: 0o600 });

      const result = await authorities.publishAndFinalize();
      assert.notStrictEqual(result.reason, 'CONFIRMED_BEFORE_WRITE', 'PLAN.md ~L554 requires the literal schema string "coordination/credential-absence-checkpoints/v1", and ~L560 explicitly requires schema validation before evidence manifest publication -- a record with the WRONG schema string must be rejected regardless of otherwise-complete checkpoints, but currently schema is never inspected at all: ' + JSON.stringify(result));
    } finally {
      cleanupDir(tmp);
    }
  });

  test('ATTACK: publishAndFinalize() never validates the durable record\'s own mode field against its PLAN.md-mandated enum (app-server|mcp) -- a tampered record with an out-of-enum mode, but otherwise genuinely complete, is still accepted', async () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-nogo4-b-wrong-mode-'));
    const fixture = makeSealedIsolationFixture(tmp);
    try {
      const authorities = rbc.createRunAuthorities(validAuthoritiesDeps(fixture, { expectedRoster: [{ role: 'verifier', ordinal: 0 }] }));
      const bound = authorities.bindConnection({ role: 'verifier', ordinal: 0 });
      assert.strictEqual(typeof bound.reason, 'undefined', JSON.stringify(bound));
      const recorder = bound.checkout();
      recorder.recordLogin('pre'); recorder.recordLogin('post');
      recorder.recordTurn('pre'); recorder.recordTurn('during'); recorder.recordTurn('post');
      recorder.recordCleanup('pre'); recorder.recordCleanup('post');
      bound.close();

      const checkpointFile = path.join(rll.registryRepoDir({ repoId: fixture.repoId }), 'credential-absence-checkpoints', fixture.runId + '.json');
      const genuineRecord = readJsonFile(checkpointFile);
      const tamperedRecord = Object.assign({}, genuineRecord, { mode: 'totally-bogus-mode-not-in-the-enum' });
      // Explicit mode:0o600 -- matches the real production writer exactly, so
      // the fd-bound reader's exact-mode check never rejects this fabrication.
      fs.writeFileSync(checkpointFile, JSON.stringify(tamperedRecord), { mode: 0o600 });

      const result = await authorities.publishAndFinalize();
      assert.notStrictEqual(result.reason, 'CONFIRMED_BEFORE_WRITE', 'PLAN.md ~L555 requires mode to be the enum app-server|mcp -- a record with an out-of-enum mode string must be rejected regardless of otherwise-complete checkpoints, but currently mode is never inspected at all: ' + JSON.stringify(result));
    } finally {
      cleanupDir(tmp);
    }
  });

  test('ATTACK: a MALFORMED checkpoint name (doesn\'t match the family:phase@role:ordinal shape at all) is silently ignored by the cardinality computation -- neither helping nor invalidating completeness -- rather than being treated as a sign of a corrupted/tampered record that should fail closed', async () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-nogo4-b-malformed-name-'));
    const fixture = makeSealedIsolationFixture(tmp);
    try {
      const authorities = rbc.createRunAuthorities(validAuthoritiesDeps(fixture, { expectedRoster: [{ role: 'verifier', ordinal: 0 }] }));
      const bound = authorities.bindConnection({ role: 'verifier', ordinal: 0 });
      assert.strictEqual(typeof bound.reason, 'undefined', JSON.stringify(bound));
      const recorder = bound.checkout();
      recorder.recordLogin('pre'); recorder.recordLogin('post');
      recorder.recordTurn('pre'); recorder.recordTurn('during'); recorder.recordTurn('post');
      recorder.recordCleanup('pre'); recorder.recordCleanup('post');
      bound.close();

      const checkpointFile = path.join(rll.registryRepoDir({ repoId: fixture.repoId }), 'credential-absence-checkpoints', fixture.runId + '.json');
      const genuineRecord = readJsonFile(checkpointFile);
      const genuinelyComplete = genuineRecord.complete;
      assert.strictEqual(genuinelyComplete, true, 'test precondition: the genuine record must be legitimately complete before tampering: ' + JSON.stringify(genuineRecord));

      // Inject one additional, MALFORMED checkpoint entry (no '@role:ordinal'
      // suffix at all -- a shape a corrupted/tampered record could plausibly
      // have) alongside the otherwise-genuine, complete checkpoints.
      const tamperedRecord = Object.assign({}, genuineRecord, {
        checkpoints: genuineRecord.checkpoints.concat([{ name: 'not-a-well-formed-checkpoint-name-at-all', at: new Date().toISOString(), roots_scanned: 0, captures_scanned: 0, ok: true }]),
      });
      // Explicit mode:0o600 -- matches the real production writer exactly, so
      // the fd-bound reader's exact-mode check never rejects this fabrication.
      fs.writeFileSync(checkpointFile, JSON.stringify(tamperedRecord), { mode: 0o600 });

      const result = await authorities.publishAndFinalize();
      assert.notStrictEqual(result.reason, 'CONFIRMED_BEFORE_WRITE', 'a record containing a checkpoint entry whose name does not match the expected family:phase@role:ordinal shape at all is a sign of a corrupted or tampered record and must fail closed, never be silently ignored as if it had no bearing on completeness: ' + JSON.stringify(result));
    } finally {
      cleanupDir(tmp);
    }
  });
});

describe('THIRD HARD NO-GO RESPONSE -- Block C: root creation/cleanup/reaper hardening', () => {
  test('ATTACK: createRunRoot silently accepts and reuses a PRE-EXISTING plain (non-symlink) directory at the host-derived isolation root -- only a pre-existing SYMLINK is rejected (fs.lstatSync().isSymbolicLink()); a real, already-populated directory (planted by a prior run, or an attacker) is claimed as if newly created, since ensureSecureRegistryDir\'s mkdirSync({recursive:true}) is a silent no-op on an existing directory (Group C redesign: intendedPath is no longer caller-chosen -- host-derived as registryRepoDir({repoId})/isolation-roots/instanceId, cjs:4078 -- but both repoId and instanceId are minted fresh by this test itself, so the exact future leaf path is predictable in advance; pre-populate it directly with real content before ever calling createRunRoot, no ancestor/symlink tampering needed since this test is about the LEAF itself, not an ancestor)', () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-nogo3-c-existing-dir-'));
    const repoId = crypto.randomBytes(16).toString('hex');
    const instanceId = crypto.randomBytes(16).toString('hex');
    try {
      const issuer = createFakeReadViewIssuer();
      const isolationProvider = rbc.createIsolationProvider({ readViewAuthority: issuer.asReadViewAuthority(), strictConfigValidator: () => ({ ok: true }), projectRoot: process.cwd() });
      const predictedIntendedPath = path.join(rll.registryRepoDir({ repoId }), 'isolation-roots', instanceId);
      fs.mkdirSync(predictedIntendedPath, { recursive: true, mode: 0o700 });
      fs.writeFileSync(path.join(predictedIntendedPath, 'planted-file.txt'), 'pre-existing content that must never be silently claimed');

      const created = isolationProvider.createRunRoot({
        instanceId, repoId,
        runId: crypto.randomBytes(16).toString('hex'),
        ownerIdentity: fakeOwnerIdentityBlock2(),
      });
      assert.strictEqual(created.ok, false, 'createRunRoot must reject any intendedPath that already exists as anything other than freshly created by this exact call, never silently reuse/adopt a pre-existing directory -- currently it succeeds and claims the pre-populated directory as its own: ' + JSON.stringify(created));
    } finally {
      cleanupRegistryFor(repoId);
      cleanupDir(tmp);
    }
  });

  test('ATTACK: cleanupRoot has no way to observe or reject based on a LIVE child still using the root -- a genuinely BORN (alive, never stopped) child associated with this exact root does not block cleanupRoot from renaming the root away out from under it', async () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-nogo3-c-live-child-'));
    const fixture = makeSpawnFixture(tmp);
    try {
      const registry = rbc.createSupervisorOwnedChildRegistry();
      const child = makeFakeChildProcess();
      const spawnFn = () => {
        setImmediate(() => child.emit('spawn'));
        return child;
      };
      const spawnResult = await withFakeProcessIdentity(VALID_FAKE_IDENTITY, () =>
        rbc.spawnWithIntent({ instanceId: fixture.instanceId, repoId: fixture.repoId, runId: fixture.runId, rootIdentity: fixture.rootIdentity }, spawnFn, { registry, stopOwnedChild: (c) => c.kill('SIGTERM') }));
      assert.strictEqual(spawnResult.state, 'BORN', 'test precondition: the child must be genuinely alive (BORN) and never stopped: ' + JSON.stringify(spawnResult));

      // CORRECTION PASS ROUND 8 (Finding 2 cascade fix): reaching BORN
      // publishes a genuine spawn-intent/v1 record -- NEVER_SPAWNED (this
      // test's old default authorization) is no longer valid once one exists
      // with no corresponding instance record (classifyGenuineNeverSpawnedAbsence).
      // PID_ABSENT is the semantically-correct outcome here anyway, fully
      // accredited against a real, matching instance record using the fake
      // child's own real pid (this test process's own, always-alive).
      const birthToken = 'synthetic-r8-f2-birth-token';
      const executablePath = process.execPath;
      const instancePath = instanceRecordPathFor(fixture.repoId, fixture.instanceId);
      fs.mkdirSync(path.dirname(instancePath), { recursive: true, mode: 0o700 });
      fs.writeFileSync(instancePath, JSON.stringify(Object.assign(makeInstanceRecordFixture(), {
        instance_id: fixture.instanceId, pid: child.pid, os_birth_token: birthToken, executable_path: executablePath,
      })), { mode: 0o600 });
      const instanceRecordStat = fs.statSync(instancePath, { bigint: true });
      const instanceRecordIdentity = {
        dev: instanceRecordStat.dev.toString(), ino: instanceRecordStat.ino.toString(),
        mode: instanceRecordStat.mode.toString(), uid: instanceRecordStat.uid.toString(),
      };

      const cleanupResult = fixture.isolationProvider.cleanupRoot(fixture.sealHandle, minimalValidCleanupAuthorization(fixture.sealHandle, fixture.ownerToken, {
        outcome: 'PID_ABSENT', pid: child.pid, birthToken, executableIdentity: executablePath, instanceRecordIdentity,
      }));
      assert.strictEqual(cleanupResult.ok, false, 'cleanupRoot must reject (never rename the root away) while a genuinely live, unstopped child associated with this exact root still exists -- currently cleanupRoot accepts only the handle itself and has no way to consult any child registry or liveness signal at all, so a live child has zero effect on whether cleanup proceeds: ' + JSON.stringify(cleanupResult));
    } finally {
      cleanupDir(tmp);
    }
  });

  test('CONFIRMATION (was ATTACK; discovered already fixed via ROUND 9 P0-2c\'s exact-match containment check, a stronger fix than the canonicalization this test originally asked for): a <container>/../../victim traversal-shaped finalPath is rejected (CLEANUP_COMPLETE_FINAL_PATH_NOT_CONTAINED), never causing rmSync to touch anything outside the tombstone container', () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-nogo3-c-reap-traversal-'));
    try {
      const repoId = crypto.randomBytes(16).toString('hex');
      const instanceId = crypto.randomBytes(16).toString('hex');
      const containerDir = path.join(rll.registryRepoDir({ repoId }), '.tombstone', instanceId);
      fs.mkdirSync(containerDir, { recursive: true, mode: 0o700 });

      const victimPath = path.resolve(containerDir, '../../victim-' + crypto.randomBytes(4).toString('hex'));
      fs.writeFileSync(victimPath, 'must never be deleted by a reap of an unrelated container');
      assert.ok(fs.existsSync(victimPath), 'test precondition');

      // ROUND 9 (P0-2a cascade fix): intent.json brought up to the full
      // valid shape so this test reaches the completeRecord containment
      // check it targets, rather than being masked by an earlier,
      // unrelated rejection at validateCleanupIntentRecord (which would
      // trivially satisfy "victim survives" without ever proving THIS
      // property -- caught via a full-suite-shape audit this round).
      const traversalTestRunId = crypto.randomBytes(16).toString('hex');
      fs.writeFileSync(path.join(containerDir, 'intent.json'), JSON.stringify({
        schema: 'coordination/cleanup-intent/v1', instanceId, repoId, runId: traversalTestRunId,
        intendedPath: path.join(rll.registryRepoDir({ repoId }), 'isolation-roots', instanceId), rootInode: { dev: '111', ino: '222' }, outcome: 'NEVER_SPAWNED',
        intentAt: new Date().toISOString(),
      }), { mode: 0o600 });
      const traversalFinalPath = containerDir + path.sep + '..' + path.sep + '..' + path.sep + path.basename(victimPath);
      fs.writeFileSync(path.join(containerDir, 'complete.json'), JSON.stringify({
        schema: 'coordination/cleanup-complete/v1', instanceId, repoId, runId: traversalTestRunId,
        finalPath: traversalFinalPath, rootInodeAfter: { dev: '333', ino: '444' }, completedAt: new Date().toISOString(),
      }), { mode: 0o600 });

      const result = rbc.reapTombstonedRoot({ repoId, instanceId });

      assert.ok(fs.existsSync(victimPath), 'reapTombstonedRoot must NEVER delete anything outside its own tombstone container directory -- the containment check must canonicalize (path.resolve/realpath) before comparing, never a lexical startsWith on the raw string, which a "' + traversalFinalPath + '"-shaped finalPath defeats entirely: victim at ' + victimPath + (fs.existsSync(victimPath) ? ' still exists' : ' was DELETED') + ', reap result: ' + JSON.stringify(result));
      assert.strictEqual(result.ok, false, JSON.stringify(result));
      assert.strictEqual(result.reason, 'CLEANUP_COMPLETE_FINAL_PATH_NOT_CONTAINED', 'a traversal-shaped finalPath must now be rejected by the exact-match containment check specifically, not merely happen to leave the victim untouched for an unrelated reason: ' + JSON.stringify(result));
    } finally {
      cleanupDir(tmp);
    }
  });

  test('CONFIRMATION (was ATTACK; discovered already fixed by direct source read -- the rmSync call is wrapped in its own try/catch returning CLEANUP_REAP_REMOVAL_FAILED, not swallowed): a genuine rmSync permission failure during removal is reported as a fail-closed rejection, never silently treated as a successful reap', () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-nogo3-c-reap-swallow-'));
    try {
      const repoId = crypto.randomBytes(16).toString('hex');
      const instanceId = crypto.randomBytes(16).toString('hex');
      const containerDir = path.join(rll.registryRepoDir({ repoId }), '.tombstone', instanceId);
      const finalPath = path.join(containerDir, 'root');
      const stubbornSubdir = path.join(finalPath, 'stubborn');
      fs.mkdirSync(stubbornSubdir, { recursive: true, mode: 0o700 });
      fs.writeFileSync(path.join(stubbornSubdir, 'file.txt'), 'x');
      fs.chmodSync(finalPath, 0o500); // finalPath itself no longer writable -> cannot unlink 'stubborn' from within it.

      // ROUND 9 (P0-2a cascade fix): both durable records brought up to
      // their own full valid shape so this test reaches the rmSync call it
      // targets, rather than being masked by an earlier, unrelated
      // rejection at validateCleanupIntentRecord (which would trivially
      // satisfy "reaped !== true" without ever exercising rmSync at all --
      // caught via a full-suite-shape audit this round).
      const finalPathStat = fs.statSync(finalPath, { bigint: true });
      const rmSyncTestRunId = crypto.randomBytes(16).toString('hex');
      const rmSyncTestRootInode = { dev: finalPathStat.dev.toString(), ino: finalPathStat.ino.toString() };
      fs.writeFileSync(path.join(containerDir, 'intent.json'), JSON.stringify({
        schema: 'coordination/cleanup-intent/v1', instanceId, repoId, runId: rmSyncTestRunId,
        intendedPath: path.join(rll.registryRepoDir({ repoId }), 'isolation-roots', instanceId), rootInode: rmSyncTestRootInode, outcome: 'NEVER_SPAWNED',
        intentAt: new Date().toISOString(),
      }), { mode: 0o600 });
      fs.writeFileSync(path.join(containerDir, 'complete.json'), JSON.stringify({
        schema: 'coordination/cleanup-complete/v1', instanceId, repoId, runId: rmSyncTestRunId,
        finalPath, rootInodeAfter: rmSyncTestRootInode, completedAt: new Date().toISOString(),
      }), { mode: 0o600 });
      const provIntentPath = path.join(rll.registryRepoDir({ repoId }), 'root-provisioning', instanceId + '.intent.json');
      fs.mkdirSync(path.dirname(provIntentPath), { recursive: true, mode: 0o700 });
      fs.writeFileSync(provIntentPath, JSON.stringify(makeFullProvisioningIntentFixture(repoId, instanceId, rmSyncTestRunId)), { mode: 0o600 });

      let result;
      try {
        result = rbc.reapTombstonedRoot({ repoId, instanceId });
      } finally {
        fs.chmodSync(finalPath, 0o700); // restore so cleanupDir(tmp) can actually remove everything afterward.
      }

      assert.ok(fs.existsSync(stubbornSubdir), 'test precondition: the permission failure must have genuinely prevented removal');
      assert.strictEqual(result.ok, false, 'reapTombstonedRoot must never report reaped:true when the underlying rmSync genuinely failed for a reason OTHER than absence (e.g. a real permission error): ' + JSON.stringify(result));
      assert.strictEqual(result.reason, 'CLEANUP_REAP_REMOVAL_FAILED', JSON.stringify(result));
    } finally {
      cleanupDir(tmp);
    }
  });

  test('CONFIRMATION (was ATTACK; discovered already fixed as ROUND 9 P0-2b, schema check runs first): reapTombstonedRoot rejects (CLEANUP_COMPLETE_SCHEMA_INVALID) a complete.json record with a WRONG schema string and a MISMATCHED instanceId, never trusting an unvalidated record just because it was found at the expected container path', () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-nogo3-c-reap-schema-'));
    try {
      const repoId = crypto.randomBytes(16).toString('hex');
      const instanceId = crypto.randomBytes(16).toString('hex');
      const containerDir = path.join(rll.registryRepoDir({ repoId }), '.tombstone', instanceId);
      const finalPath = path.join(containerDir, 'root');
      fs.mkdirSync(finalPath, { recursive: true, mode: 0o700 });
      fs.writeFileSync(path.join(finalPath, 'file.txt'), 'x');

      // ROUND 9 (P0-2a cascade fix): intent.json brought up to the full
      // valid shape so this test reaches the completeRecord schema/
      // correlation check it targets, rather than being masked by an
      // earlier, unrelated rejection at validateCleanupIntentRecord (which
      // would trivially satisfy "reaped !== true" without ever exercising
      // this check at all -- caught via a full-suite-shape audit this round).
      const finalPathStat = fs.statSync(finalPath, { bigint: true });
      fs.writeFileSync(path.join(containerDir, 'intent.json'), JSON.stringify({
        schema: 'coordination/cleanup-intent/v1', instanceId, repoId, runId: crypto.randomBytes(16).toString('hex'),
        intendedPath: path.join(rll.registryRepoDir({ repoId }), 'isolation-roots', instanceId), rootInode: { dev: finalPathStat.dev.toString(), ino: finalPathStat.ino.toString() }, outcome: 'NEVER_SPAWNED',
        intentAt: new Date().toISOString(),
      }), { mode: 0o600 });
      fs.writeFileSync(path.join(containerDir, 'complete.json'), JSON.stringify({
        schema: 'totally-wrong-schema/v99', // wrong schema
        instanceId: 'a-completely-different-instance-id-than-this-container', // mismatched correlation
        repoId, runId: 'irrelevant', finalPath,
      }), { mode: 0o600 });

      const result = rbc.reapTombstonedRoot({ repoId, instanceId });
      assert.strictEqual(result.ok, false, 'reapTombstonedRoot must validate the complete.json record\'s own schema and correlation (instanceId/repoId) fields before acting on it, never trust an unvalidated record just because it was found at the expected container path: ' + JSON.stringify(result));
      assert.strictEqual(result.reason, 'CLEANUP_COMPLETE_SCHEMA_INVALID', 'schema is validated before correlation, so a record wrong on BOTH must be rejected for the schema reason specifically: ' + JSON.stringify(result));
    } finally {
      cleanupDir(tmp);
    }
  });

  test('CONFIRMATION (was ATTACK; discovered already passing during the Round 8 inventory reconciliation pass -- the underlying false-positive-drift fix this test used to document has since landed): withValidatedRoot correctly tolerates a LEGITIMATE write inside a child-writable topology layer (xdgState) -- a completely normal, expected write by the running child during its own lifetime never causes the next root access to be wrongly rejected as VALIDATED_ROOT_DRIFT_FROM_SEAL', () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-nogo3-c-writable-drift-'));
    const fixture = makeSealedIsolationFixture(tmp);
    try {
      // withValidatedRoot returns the callback's OWN return value directly
      // on success (no {ok:true,...} envelope) -- only the failure paths
      // return {ok:false, reason}. A sentinel-shaped callback return value
      // lets success/failure be told apart unambiguously via `.reason`.
      const probe = (reader) => ({ probeMarker: true, hasConfigPath: !!(reader && typeof reader.configPath === 'string') });
      const baseline = fixture.isolationProvider.withValidatedRoot(fixture.sealHandle, { runId: fixture.runId, role: fixture.role }, probe);
      assert.strictEqual(baseline.reason, undefined, 'test precondition: the FIRST access, before any child activity, must succeed: ' + JSON.stringify(baseline));
      assert.strictEqual(baseline.probeMarker, true, 'test precondition: ' + JSON.stringify(baseline));

      fs.writeFileSync(path.join(fixture.sealHandle.topologyPaths.xdgState, 'session-state.json'), JSON.stringify({ ok: true }));

      const afterLegitimateWrite = fixture.isolationProvider.withValidatedRoot(fixture.sealHandle, { runId: fixture.runId, role: fixture.role }, probe);
      assert.strictEqual(afterLegitimateWrite.reason, undefined, 'a legitimate write by the child into its own writable topology layer (xdgState) must never invalidate the seal -- currently EVERY topology layer, including the child-writable ones, is compared with a full identity tuple (dev/ino/mode/uid/gid/nlink/ctimeNs/mtimeNs), and mtimeNs/ctimeNs/nlink all change on a normal file write inside a directory, so this legitimate write is wrongly reported as drift: ' + JSON.stringify(afterLegitimateWrite));
    } finally {
      cleanupDir(tmp);
    }
  });

  test('CONFIRMATION (regression guard for whatever fixes the test above): a genuine REBIND of a child-writable topology layer (the directory itself replaced with a different inode, not merely written into) IS still caught as drift -- already correct today since dev/ino are part of the identity tuple; kept explicit so a future fix that narrows the writable-layer comparison (e.g. dropping mtime/ctime/nlink) does not accidentally also drop dev/ino', () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-nogo3-c-writable-rebind-'));
    const fixture = makeSealedIsolationFixture(tmp);
    try {
      const probe = (reader) => ({ probeMarker: true, hasConfigPath: !!(reader && typeof reader.configPath === 'string') });
      const baseline = fixture.isolationProvider.withValidatedRoot(fixture.sealHandle, { runId: fixture.runId, role: fixture.role }, probe);
      assert.strictEqual(baseline.reason, undefined, 'test precondition: ' + JSON.stringify(baseline));
      assert.strictEqual(baseline.probeMarker, true, 'test precondition: ' + JSON.stringify(baseline));

      fs.rmSync(fixture.sealHandle.topologyPaths.xdgState, { recursive: true, force: true });
      fs.mkdirSync(fixture.sealHandle.topologyPaths.xdgState, { recursive: true, mode: 0o700 });

      const afterRebind = fixture.isolationProvider.withValidatedRoot(fixture.sealHandle, { runId: fixture.runId, role: fixture.role }, probe);
      assert.strictEqual(afterRebind.reason, 'VALIDATED_ROOT_DRIFT_FROM_SEAL', 'a genuine rebind (directory replaced with a different inode) of even a child-writable topology layer must still be caught as drift: ' + JSON.stringify(afterRebind));
    } finally {
      cleanupDir(tmp);
    }
  });
});

// ══════════════════════════════════════════════════════════════════════════
// FOURTH HARD NO-GO RESPONSE -- Block C: isolation and owned-child authority.
// ══════════════════════════════════════════════════════════════════════════

describe('FOURTH HARD NO-GO RESPONSE -- Block C: isolation and owned-child authority', () => {
  test('ATTACK: CODEX_HOME is wrongly treated as a host-owned-immutable topology layer -- PLAN.md ~L1100 explicitly lists it among the child\'s writable roots ("HOME, CODEX_HOME (where relevant), TMPDIR, and all XDG roots... these are its only writable roots"), but CHILD_WRITABLE_TOPOLOGY_LAYERS omits it, so a completely legitimate write into codexHome after sealing is wrongly reported as VALIDATED_ROOT_DRIFT_FROM_SEAL', () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-nogo4-c-codexhome-writable-'));
    const fixture = makeSealedIsolationFixture(tmp);
    try {
      const probe = (reader) => ({ probeMarker: true });
      const baseline = fixture.isolationProvider.withValidatedRoot(fixture.sealHandle, { runId: fixture.runId, role: fixture.role }, probe);
      assert.strictEqual(baseline.reason, undefined, 'test precondition: ' + JSON.stringify(baseline));

      fs.writeFileSync(path.join(fixture.sealHandle.topologyPaths.codexHome, 'legitimate-codex-runtime-file.json'), '{}');

      const afterLegitimateWrite = fixture.isolationProvider.withValidatedRoot(fixture.sealHandle, { runId: fixture.runId, role: fixture.role }, probe);
      assert.strictEqual(afterLegitimateWrite.reason, undefined, 'a legitimate write into codexHome (PLAN.md ~L1100\'s own explicit list of the child\'s writable roots) must never invalidate the seal -- currently CHILD_WRITABLE_TOPOLOGY_LAYERS excludes codexHome (its own comment misciting PLAN.md as naming "only HOME/TMPDIR/XDG"), so this legitimate write is wrongly reported as drift: ' + JSON.stringify(afterLegitimateWrite));
    } finally {
      cleanupDir(tmp);
    }
  });

  test('ATTACK: once a root is marked live at BORN, cleanupRoot refuses it PERMANENTLY -- even long after the child has genuinely, verifiably stopped -- because nothing ever removes the identity key from liveChildRootIdentityKeys (the code\'s own comment already admits this: "nothing in THIS round releases it again")', async () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-nogo4-c-liveness-never-retired-'));
    const fixture = makeSpawnFixture(tmp);
    try {
      const registry = rbc.createSupervisorOwnedChildRegistry();
      const child = makeFakeChildProcess();
      let killed = false;
      const spawnFn = () => {
        setImmediate(() => child.emit('spawn'));
        return child;
      };
      const spawnResult = await withFakeProcessIdentity(VALID_FAKE_IDENTITY, () =>
        rbc.spawnWithIntent({ instanceId: fixture.instanceId, repoId: fixture.repoId, runId: fixture.runId, rootIdentity: fixture.rootIdentity }, spawnFn, { registry, stopOwnedChild: (c) => { killed = true; c.kill('SIGTERM'); } }));
      assert.strictEqual(spawnResult.state, 'BORN', 'test precondition: ' + JSON.stringify(spawnResult));

      // The child GENUINELY, verifiably stops -- a real 'exit' event, the
      // same signal a real OS process emits on termination.
      child.kill = function () { killed = true; setImmediate(() => child.emit('exit')); };
      child.kill('SIGTERM');
      await new Promise((resolve) => setImmediate(resolve));
      await new Promise((resolve) => setImmediate(resolve));

      // CORRECTION PASS ROUND 8 (Finding 2 cascade fix): reaching BORN
      // publishes a genuine spawn-intent/v1 record -- NEVER_SPAWNED (this
      // test's old default authorization) is no longer valid once one exists
      // with no corresponding instance record (classifyGenuineNeverSpawnedAbsence).
      // Without this fix the call is rejected earlier (CLEANUP_AUTHORIZATION_INVALID),
      // which the original loose notStrictEqual assertion below would have
      // silently accepted as if it still proved the exit-releases-the-key
      // property -- a masked green discovered while fixing this cascade.
      // PID_ABSENT is the semantically-correct outcome here, BUT the
      // authorization's own pid must NOT be child.pid (=== process.pid,
      // this test process's own, always-alive pid) -- cleanupRoot's own
      // cross-process livenessProbe re-check (Round 7 Finding 1 item 1)
      // would then ALWAYS see it alive regardless of the fake 'exit' event
      // above, masking the SAME-PROCESS liveChildRootIdentityKeys property
      // this test exists to isolate (caught empirically: an earlier draft
      // using child.pid here made this test genuinely, correctly fail for
      // the wrong reason). A real, separately-spawned, genuinely-exited
      // child's pid is used instead -- decoupled from child.pid, guaranteed
      // dead by the time cleanupRoot runs.
      const deadPidChild = require('node:child_process').spawn(process.execPath, ['-e', 'process.exit(0)'], { stdio: 'ignore' });
      const deadPid = await new Promise((resolve, reject) => {
        deadPidChild.once('spawn', () => resolve(deadPidChild.pid));
        deadPidChild.once('error', reject);
      });
      await new Promise((resolve) => deadPidChild.once('exit', resolve));
      const birthToken = 'synthetic-r8-f2-birth-token';
      const executablePath = process.execPath;
      const instancePath = instanceRecordPathFor(fixture.repoId, fixture.instanceId);
      fs.mkdirSync(path.dirname(instancePath), { recursive: true, mode: 0o700 });
      fs.writeFileSync(instancePath, JSON.stringify(Object.assign(makeInstanceRecordFixture(), {
        instance_id: fixture.instanceId, pid: deadPid, os_birth_token: birthToken, executable_path: executablePath,
      })), { mode: 0o600 });
      const instanceRecordStat = fs.statSync(instancePath, { bigint: true });
      const instanceRecordIdentity = {
        dev: instanceRecordStat.dev.toString(), ino: instanceRecordStat.ino.toString(),
        mode: instanceRecordStat.mode.toString(), uid: instanceRecordStat.uid.toString(),
      };

      const cleanupResult = fixture.isolationProvider.cleanupRoot(fixture.sealHandle, minimalValidCleanupAuthorization(fixture.sealHandle, fixture.ownerToken, {
        outcome: 'PID_ABSENT', pid: deadPid, birthToken, executableIdentity: executablePath, instanceRecordIdentity,
      }));
      assert.notStrictEqual(cleanupResult.reason, 'CLEANUP_LIVE_CHILD_PRESENT', 'cleanupRoot must not refuse a root whose ONLY previously-live child has since genuinely, verifiably exited -- currently the liveness marker set at BORN is never retired by anything, so this refusal is permanent regardless of the child\'s real, current state: ' + JSON.stringify(cleanupResult));
    } finally {
      cleanupDir(tmp);
    }
  });

  test('ATTACK: cleanupRoot\'s liveness check trusts the CALLER-SUPPLIED rootIdentity given to spawnWithIntent at BORN time, never independently re-deriving it from the root\'s own actual, current filesystem identity -- a caller that supplies a MISMATCHED rootIdentity (legitimately or by bug) causes cleanupRoot to fail to recognize a genuinely live child, silently proceeding to move the root anyway', async () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-nogo4-c-rootidentity-mismatch-'));
    const fixture = makeSpawnFixture(tmp);
    try {
      const registry = rbc.createSupervisorOwnedChildRegistry();
      const child = makeFakeChildProcess();
      const spawnFn = () => {
        setImmediate(() => child.emit('spawn'));
        return child;
      };
      // A rootIdentity that does NOT match fixture.rootIdentity (the root's
      // own REAL, actual dev/ino) -- e.g. a caller bug, or a stale value
      // computed before the root's final identity was known.
      const mismatchedRootIdentity = { dev: fixture.rootIdentity.dev, ino: fixture.rootIdentity.ino + 999999 };
      const spawnResult = await withFakeProcessIdentity(VALID_FAKE_IDENTITY, () =>
        rbc.spawnWithIntent({ instanceId: fixture.instanceId, repoId: fixture.repoId, runId: fixture.runId, rootIdentity: mismatchedRootIdentity }, spawnFn, { registry, stopOwnedChild: (c) => c.kill('SIGTERM') }));
      assert.strictEqual(spawnResult.state, 'BORN', 'test precondition: ' + JSON.stringify(spawnResult));
      // The child is still genuinely alive and unstopped at this point.

      // CORRECTION PASS ROUND 8 (Finding 2 cascade fix): reaching BORN
      // publishes a genuine spawn-intent/v1 record -- NEVER_SPAWNED (this
      // test's old default authorization) is no longer valid once one exists
      // with no corresponding instance record (classifyGenuineNeverSpawnedAbsence,
      // shared with reapTombstonedRoot's own Round 6 Finding D2 reasoning).
      // PID_ABSENT is the semantically-correct outcome here anyway, fully
      // accredited against a real, matching instance record using the fake
      // child's own real pid (this test process's own, always-alive).
      const birthToken = 'synthetic-r8-f2-birth-token';
      const executablePath = process.execPath;
      const instancePath = instanceRecordPathFor(fixture.repoId, fixture.instanceId);
      fs.mkdirSync(path.dirname(instancePath), { recursive: true, mode: 0o700 });
      fs.writeFileSync(instancePath, JSON.stringify(Object.assign(makeInstanceRecordFixture(), {
        instance_id: fixture.instanceId, pid: child.pid, os_birth_token: birthToken, executable_path: executablePath,
      })), { mode: 0o600 });
      const instanceRecordStat = fs.statSync(instancePath, { bigint: true });
      const instanceRecordIdentity = {
        dev: instanceRecordStat.dev.toString(), ino: instanceRecordStat.ino.toString(),
        mode: instanceRecordStat.mode.toString(), uid: instanceRecordStat.uid.toString(),
      };

      const cleanupResult = fixture.isolationProvider.cleanupRoot(fixture.sealHandle, minimalValidCleanupAuthorization(fixture.sealHandle, fixture.ownerToken, {
        outcome: 'PID_ABSENT', pid: child.pid, birthToken, executableIdentity: executablePath, instanceRecordIdentity,
      }));
      assert.strictEqual(cleanupResult.reason, 'CLEANUP_LIVE_CHILD_PRESENT', 'cleanupRoot must recognize a genuinely live child using the root\'s own REAL, independently-derived identity, never trusting whatever rootIdentity the caller happened to supply to spawnWithIntent at BORN time -- currently a mismatched caller-supplied rootIdentity causes the liveness key lookup to miss entirely, so cleanupRoot proceeds as if no live child exists: ' + JSON.stringify(cleanupResult));
    } finally {
      cleanupDir(tmp);
    }
  });

  test('CONFIRMATION (flipped this round -- toolkit-specialist\'s real OS-level identity check landed, requireProvenChildIdentity now calls process.kill(pid,0) and fs.existsSync(spawnfile)): a fake child with a PID and executable path that correspond to NOTHING real is correctly rejected, never reaches BORN', async () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-nogo4-c-fake-identity-accepted-'));
    const fixture = makeSpawnFixture(tmp);
    try {
      const registry = rbc.createSupervisorOwnedChildRegistry();
      const bogusChild = makeFakeChildProcess(999999999); // an astronomically unlikely-to-be-real PID.
      bogusChild.spawnfile = '/definitely/does/not/exist/anywhere-' + crypto.randomBytes(8).toString('hex');
      const spawnFn = () => {
        setImmediate(() => bogusChild.emit('spawn'));
        return bogusChild;
      };
      const spawnResult = await withFakeProcessIdentity(VALID_FAKE_IDENTITY, () =>
        rbc.spawnWithIntent({ instanceId: fixture.instanceId, repoId: fixture.repoId, runId: fixture.runId, rootIdentity: fixture.rootIdentity }, spawnFn, { registry, stopOwnedChild: (c) => c.kill('SIGTERM') }));
      assert.notStrictEqual(spawnResult.state, 'BORN', 'a child whose pid and executable path correspond to nothing real on the host must never be accepted as genuinely BORN: ' + JSON.stringify(spawnResult));
      // UNKNOWN_OWNED specifically: process.kill(999999999,0) throws ESRCH ->
      // identity verification fails -> STOPPING -> the fake child's default
      // kill() is a no-op (never emits 'exit'), so the stop can never be
      // confirmed within its own bound -> UNKNOWN_OWNED (PLAN.md ~L1169-1171).
      assert.strictEqual(spawnResult.state, 'UNKNOWN_OWNED', JSON.stringify(spawnResult));
    } finally {
      cleanupDir(tmp);
    }
  });

  test('CONFIRMATION (was ATTACK; discovered already fixed as ROUND 9 P0-2c): reapTombstonedRoot now fails closed (CLEANUP_COMPLETE_FINAL_PATH_MISSING) rather than reporting {ok:true, reaped:true} when NO removal was ever attempted -- a schema-valid, correctly-correlated complete.json record whose own finalPath is absent/non-string', () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-nogo4-c-fake-reaped-'));
    try {
      const repoId = crypto.randomBytes(16).toString('hex');
      const instanceId = crypto.randomBytes(16).toString('hex');
      const containerDir = path.join(rll.registryRepoDir({ repoId }), '.tombstone', instanceId);
      fs.mkdirSync(containerDir, { recursive: true, mode: 0o700 });
      // ROUND 9 (P0-2a cascade fix): brought up to the full valid shape so
      // this test reaches the finalPath-missing check it targets, rather
      // than being masked by an earlier, unrelated rejection at
      // validateCleanupIntentRecord (caught via a full-suite-shape audit
      // this round).
      const finalPathMissingTestRunId = crypto.randomBytes(16).toString('hex');
      fs.writeFileSync(path.join(containerDir, 'intent.json'), JSON.stringify({
        schema: 'coordination/cleanup-intent/v1', instanceId, repoId, runId: finalPathMissingTestRunId,
        intendedPath: path.join(rll.registryRepoDir({ repoId }), 'isolation-roots', instanceId), rootInode: { dev: '111', ino: '222' }, outcome: 'NEVER_SPAWNED',
        intentAt: new Date().toISOString(),
      }), { mode: 0o600 });
      // A schema-valid, correctly-correlated complete.json -- but finalPath
      // is simply ABSENT (never a string at all), matching a plausible
      // real-world shape (e.g. a partially-written or schema-drifted record).
      fs.writeFileSync(path.join(containerDir, 'complete.json'), JSON.stringify({
        schema: 'coordination/cleanup-complete/v1', instanceId, repoId, runId: finalPathMissingTestRunId,
        rootInodeAfter: { dev: '333', ino: '444' }, completedAt: new Date().toISOString(),
      }), { mode: 0o600 });

      const result = rbc.reapTombstonedRoot({ repoId, instanceId });
      assert.strictEqual(result.ok, false, 'reapTombstonedRoot must never report reaped:true when no removal was ever attempted at all (finalPath absent/non-string skips the entire removal block entirely): ' + JSON.stringify(result));
      assert.strictEqual(result.reason, 'CLEANUP_COMPLETE_FINAL_PATH_MISSING', JSON.stringify(result));
    } finally {
      cleanupDir(tmp);
    }
  });
});

// Block C item 6 (this round, toolkit-specialist proposal, relayed by
// team-lead -- no existing PLAN.md text specifies this; designed live this
// round, same pattern as every other ambiguous requirement this session:
// this test defines the contract, toolkit-specialist implements against it).
//
// CONTRACT:
//   createIsolationProvider({readViewAuthority, strictConfigValidator, sensitiveRoots})
//   -- sensitiveRoots: array of absolute path strings. OPTIONAL (falls back
//   to a safe production default when omitted) -- unlike readViewAuthority/
//   strictConfigValidator, omitting it must NOT throw.
//
//   createRunRoot rejects, before any durable side effect (same
//   before-intent-publish principle as the existing ancestor-chain-symlink
//   check), whenever ANY entry in sensitiveRoots matches intendedPath in
//   EITHER direction:
//     (a) resolved(intendedPath) === resolved(sensitiveRoot), OR
//         resolved(intendedPath) is a proper path-segment descendant of
//         resolved(sensitiveRoot)
//       -> {ok:false, reason:'ROOT_INTENDED_PATH_WITHIN_SENSITIVE_ROOT'}
//     (b) resolved(sensitiveRoot) is a proper path-segment descendant of
//         resolved(intendedPath)
//       -> {ok:false, reason:'ROOT_SENSITIVE_ROOT_WITHIN_INTENDED_PATH'}
//   "proper path-segment descendant" = resolved(child).startsWith(resolved(parent)+path.sep)
//   -- a genuine directory-boundary match, NEVER a raw string-prefix match
//   (see the PRECISION test below).
//
// Every sensitive root here is entirely synthetic, scoped inside each test's
// OWN tmpdir, and deliberately NEVER created on disk -- the confinement
// check must be a pure path-string comparison, never gated on filesystem
// existence (an existence-gated check would let an attacker dodge it simply
// by choosing a not-yet-existing nested path). This suite never touches
// anything real ($HOME, ~/.ssh, the real repo root, etc.), matching this
// file's own established blast-radius discipline throughout.
describe('Block C item 6: injectable sensitive-roots confinement on createIsolationProvider (bidirectional) -- Group C redesign: sensitiveRoots is now ADDITIVE-ONLY (mandatorySensitiveRootsFor(projectRoot).concat(callerSensitiveRoots), cjs:4043), never a full replacement of the prior single default. intendedPath is no longer caller-chosen either -- host-derived as registryRepoDir({repoId})/isolation-roots/instanceId (cjs:4078), but both repoId/instanceId are minted fresh by each test, so the exact future leaf path is predictable in advance, same technique as #12/#14/#15', () => {
  function providerWithSensitiveRoots(sensitiveRoots) {
    const issuer = createFakeReadViewIssuer();
    return rbc.createIsolationProvider({
      readViewAuthority: issuer.asReadViewAuthority(),
      strictConfigValidator: () => ({ ok: true }),
      projectRoot: process.cwd(),
      sensitiveRoots,
    });
  }
  // CORRECTION PASS ROUND 6 (Finding F cascade): repoId/instanceId must be
  // pure lowercase-hex (isCoreGeneratedIdentifier) -- label now only
  // decorates runId, which stays under the broader allowlist.
  function freshIds(label) {
    return {
      instanceId: crypto.randomBytes(16).toString('hex'),
      repoId: crypto.randomBytes(16).toString('hex'),
      // CORRECTION PASS ROUND 8 (Finding 5 cascade fix): createRunRoot now
      // requires runId to be pure hex too -- label no longer decorates it.
      runId: crypto.randomBytes(16).toString('hex'),
    };
  }
  function predictedLeafFor(repoId, instanceId) {
    return path.join(rll.registryRepoDir({ repoId }), 'isolation-roots', instanceId);
  }
  /** Synchronous set -> run -> restore, zero await in between (this session's own established-safe pattern for env-var test seams -- see the TEARDOWN-fault concurrency investigation earlier this round for why a WIDE, awaited window around a process-global is the one thing to avoid). CODEX_HOME is read fresh from process.env on every mandatorySensitiveRootsFor call, never memoized (unlike the two git-derived values), so this reliably takes effect for a createIsolationProvider construction that happens synchronously inside fn. */
  function withOverriddenCodexHome(overrideValue, fn) {
    const hadOwn = Object.prototype.hasOwnProperty.call(process.env, 'CODEX_HOME');
    const original = process.env.CODEX_HOME;
    process.env.CODEX_HOME = overrideValue;
    try {
      return fn();
    } finally {
      if (hadOwn) process.env.CODEX_HOME = original;
      else delete process.env.CODEX_HOME;
    }
  }

  test('ATTACK: the predicted isolation root nested inside an ADDITIVE designated-sensitive root -- createRunRoot must reject with ROOT_INTENDED_PATH_WITHIN_SENSITIVE_ROOT before any durable side effect', () => {
    const ids = freshIds('nested');
    try {
      const predictedLeaf = predictedLeafFor(ids.repoId, ids.instanceId);
      const additiveSensitiveRoot = rll.registryRepoDir({ repoId: ids.repoId }); // one level ABOVE the predicted leaf -- predictedLeaf is a proper descendant of this.
      const isolationProvider = providerWithSensitiveRoots([additiveSensitiveRoot]);
      const result = isolationProvider.createRunRoot({ instanceId: ids.instanceId, repoId: ids.repoId, runId: ids.runId, ownerIdentity: fakeOwnerIdentityBlock2() });
      assert.strictEqual(result.ok, false, 'an isolation root nested inside a designated-sensitive path must never be created: ' + JSON.stringify(result));
      assert.strictEqual(result.reason, 'ROOT_INTENDED_PATH_WITHIN_SENSITIVE_ROOT', JSON.stringify(result));
      assert.ok(!fs.existsSync(predictedLeaf), 'a rejected createRunRoot must leave no trace on disk: ' + predictedLeaf);
    } finally {
      cleanupRegistryFor(ids.repoId);
    }
  });

  test('ATTACK: the predicted isolation root EXACTLY EQUALS an ADDITIVE designated-sensitive root -- must also reject (a naive path.sep-suffixed prefix check alone would miss exact equality)', () => {
    const ids = freshIds('exact');
    try {
      const predictedLeaf = predictedLeafFor(ids.repoId, ids.instanceId);
      const isolationProvider = providerWithSensitiveRoots([predictedLeaf]); // the additive root IS the predicted leaf itself.
      const result = isolationProvider.createRunRoot({ instanceId: ids.instanceId, repoId: ids.repoId, runId: ids.runId, ownerIdentity: fakeOwnerIdentityBlock2() });
      assert.strictEqual(result.ok, false, 'an isolation root pointed EXACTLY at a designated-sensitive path must never be created: ' + JSON.stringify(result));
      assert.strictEqual(result.reason, 'ROOT_INTENDED_PATH_WITHIN_SENSITIVE_ROOT', JSON.stringify(result));
    } finally {
      cleanupRegistryFor(ids.repoId);
    }
  });

  test('ATTACK: an ADDITIVE designated-sensitive root nested inside the predicted isolation root -- createRunRoot must reject with ROOT_SENSITIVE_ROOT_WITHIN_INTENDED_PATH (an isolation root cannot be wrapped AROUND something sensitive either)', () => {
    const ids = freshIds('wraps');
    try {
      const predictedLeaf = predictedLeafFor(ids.repoId, ids.instanceId);
      const additiveSensitiveRoot = path.join(predictedLeaf, 'nested-sensitive-thing'); // a CHILD of the predicted leaf.
      const isolationProvider = providerWithSensitiveRoots([additiveSensitiveRoot]);
      const result = isolationProvider.createRunRoot({ instanceId: ids.instanceId, repoId: ids.repoId, runId: ids.runId, ownerIdentity: fakeOwnerIdentityBlock2() });
      assert.strictEqual(result.ok, false, 'an isolation root that would structurally contain a designated-sensitive path must never be created: ' + JSON.stringify(result));
      assert.strictEqual(result.reason, 'ROOT_SENSITIVE_ROOT_WITHIN_INTENDED_PATH', JSON.stringify(result));
      assert.ok(!fs.existsSync(predictedLeaf), 'a rejected createRunRoot must leave no trace on disk: ' + predictedLeaf);
    } finally {
      cleanupRegistryFor(ids.repoId);
    }
  });

  test('PRECISION: the predicted isolation root sharing only a raw STRING PREFIX with an ADDITIVE sensitive root (not a genuine path-segment boundary) must NOT be rejected -- a sibling leaf under the SAME isolation-roots parent, e.g. instanceId vs instanceId-decoy, must never collide', () => {
    const ids = freshIds('decoy');
    try {
      const predictedLeaf = predictedLeafFor(ids.repoId, ids.instanceId);
      const additiveSensitiveRoot = predictedLeaf + '-decoy'; // shares instanceId as a raw string prefix, but is a SIBLING under isolation-roots, not a subdirectory of predictedLeaf.
      const isolationProvider = providerWithSensitiveRoots([additiveSensitiveRoot]);
      const result = isolationProvider.createRunRoot({ instanceId: ids.instanceId, repoId: ids.repoId, runId: ids.runId, ownerIdentity: fakeOwnerIdentityBlock2() });
      assert.strictEqual(result.ok, true, 'a raw string-prefix match without a genuine path-segment boundary must never be treated as nesting -- a naive startsWith(sensitiveRoot) check (without the trailing path.sep) would wrongly reject this sibling path: ' + JSON.stringify(result));
    } finally {
      cleanupRegistryFor(ids.repoId);
    }
  });

  test('CONFIRMATION: no additive sensitiveRoots supplied at all -- a genuinely ordinary run succeeds end-to-end (the predicted leaf, always under os.tmpdir(), is structurally disjoint from all 5 mandatory roots too -- the check must not over-trigger on ordinary usage)', () => {
    const ids = freshIds('unrelated');
    try {
      const isolationProvider = providerWithSensitiveRoots([]);
      const result = isolationProvider.createRunRoot({ instanceId: ids.instanceId, repoId: ids.repoId, runId: ids.runId, ownerIdentity: fakeOwnerIdentityBlock2() });
      assert.strictEqual(result.ok, true, 'an ordinary, unrelated run must succeed normally: ' + JSON.stringify(result));
    } finally {
      cleanupRegistryFor(ids.repoId);
    }
  });

  test('createIsolationProvider: sensitiveRoots is OPTIONAL -- omitting it ENTIRELY must not throw (unlike the required readViewAuthority/strictConfigValidator/projectRoot deps), and the mandatory 5 must still be the whole story when it is never supplied at all (the common, default caller shape) -- never an all-or-nothing "no sensitiveRoots key present = no protection whatsoever" fallback', () => {
    const repoId = crypto.randomBytes(16).toString('hex');
    const instanceId = crypto.randomBytes(16).toString('hex');
    const runId = crypto.randomBytes(16).toString('hex');
    try {
      // Override CODEX_HOME to be an ancestor of THIS run's own predicted
      // leaf (same registryRepoDir({repoId}) formula as every other test in
      // this block), so the mandatory CODEX_HOME root and the predicted
      // leaf share a genuine nesting relationship.
      withOverriddenCodexHome(rll.registryRepoDir({ repoId }), () => {
        const issuer = createFakeReadViewIssuer();
        let isolationProvider;
        assert.doesNotThrow(() => {
          isolationProvider = rbc.createIsolationProvider({
            readViewAuthority: issuer.asReadViewAuthority(),
            strictConfigValidator: () => ({ ok: true }),
            projectRoot: process.cwd(),
            // sensitiveRoots key never present at all -- the common, default caller shape.
          });
        }, 'sensitiveRoots must be optional, not a throw-if-missing required dependency like readViewAuthority/strictConfigValidator/projectRoot');
        const result = isolationProvider.createRunRoot({ instanceId, repoId, runId, ownerIdentity: fakeOwnerIdentityBlock2() });
        assert.strictEqual(result.ok, false, 'even with sensitiveRoots never supplied at all, the mandatory CODEX_HOME root must still be enforced -- "optional" describes only whether a caller may supply an ADDITIVE parameter, never "protection is opt-in": ' + JSON.stringify(result));
        assert.strictEqual(result.reason, 'ROOT_INTENDED_PATH_WITHIN_SENSITIVE_ROOT', JSON.stringify(result));
      });
    } finally {
      cleanupRegistryFor(repoId);
    }
  });

  test('ATTACK: an explicit sensitiveRoots:[] (an OVERT attempt to wipe protection entirely, as opposed to simply never supplying the key) must NOT remove the mandatory 5 either -- a run whose predicted leaf collides with the mandatory CODEX_HOME root must still be rejected', () => {
    const repoId = crypto.randomBytes(16).toString('hex');
    const instanceId = crypto.randomBytes(16).toString('hex');
    const runId = crypto.randomBytes(16).toString('hex');
    try {
      withOverriddenCodexHome(rll.registryRepoDir({ repoId }), () => {
        const isolationProvider = providerWithSensitiveRoots([]); // explicit, overt wipe attempt.
        const result = isolationProvider.createRunRoot({ instanceId, repoId, runId, ownerIdentity: fakeOwnerIdentityBlock2() });
        assert.strictEqual(result.ok, false, 'an explicit sensitiveRoots:[] must never be able to erase the mandatory CODEX_HOME root -- it can only ever ADD to the mandatory 5, never subtract from them: ' + JSON.stringify(result));
        assert.strictEqual(result.reason, 'ROOT_INTENDED_PATH_WITHIN_SENSITIVE_ROOT', JSON.stringify(result));
      });
    } finally {
      cleanupRegistryFor(repoId);
    }
  });
});

describe('THIRD HARD NO-GO RESPONSE -- Block D: spawn identity, late-spawn authority, credential-source hardening', () => {
  test('STRUCTURAL: requireProvenChildIdentity validates ONLY the child\'s pid -- no birth identity (e.g. an observed birth time/token) and no executable identity (e.g. the child\'s own executable path) are captured or verified at all', () => {
    const sourceText = fs.readFileSync(path.resolve(__dirname, '../lib/runtime-bridge-codex.cjs'), 'utf8');
    const fnStart = sourceText.indexOf('function requireProvenChildIdentity');
    assert.ok(fnStart >= 0, 'test precondition: requireProvenChildIdentity must exist');
    const fnBody = sourceText.slice(fnStart, sourceText.indexOf('\n}', fnStart) + 2);
    assert.ok(/executable/i.test(fnBody) && /birth/i.test(fnBody), 'requireProvenChildIdentity must validate the child\'s own executable identity and a birth identity, not just its pid -- currently its entire body is: ' + fnBody);
  });

  test('ATTACK: the BORN result carries no validated identity data at all beyond the raw child handle -- a childIdentity value is computed and checked (requireProvenChildIdentity) but then discarded, never attached to what the caller actually receives', async () => {
    const registry = rbc.createSupervisorOwnedChildRegistry();
    const child = makeFakeChildProcess();
    const spawnFn = () => {
      setImmediate(() => child.emit('spawn'));
      return child;
    };
    const result = await withFakeProcessIdentity(VALID_FAKE_IDENTITY, () =>
      rbc.spawnWithIntent(
        { instanceId: crypto.randomBytes(16).toString('hex'), repoId: crypto.randomBytes(16).toString('hex'), runId: crypto.randomBytes(16).toString('hex'), rootIdentity: { dev: 0, ino: 0 } },
        spawnFn,
        { registry, stopOwnedChild: (c) => c.kill('SIGTERM') }));
    assert.strictEqual(result.state, 'BORN', 'test precondition: ' + JSON.stringify(Object.keys(result)));
    assert.ok(Object.prototype.hasOwnProperty.call(result, 'childIdentity'), 'the BORN result must carry the validated child identity (pid + birth identity + executable identity), not just the raw child handle -- currently BORN is exactly {state, child}, discarding the already-computed, already-validated identity result entirely: ' + JSON.stringify(Object.keys(result)));
  });

  test('ATTACK: an "error" event before any "spawn" (settling FAILED_BEFORE_PROCESS) followed by a LATE "spawn" event on the SAME child leaves that child completely untracked -- never stopped, registry entry already removed, no way for the caller to ever learn a live process actually exists', async () => {
    const registry = rbc.createSupervisorOwnedChildRegistry();
    const child = makeFakeChildProcess();
    let stopOwnedChildCalls = 0;
    const spawnFn = () => {
      setImmediate(() => child.emit('error', new Error('synthetic pre-spawn error')));
      return child;
    };
    const result = await withFakeProcessIdentity(VALID_FAKE_IDENTITY, () =>
      rbc.spawnWithIntent(
        { instanceId: crypto.randomBytes(16).toString('hex'), repoId: crypto.randomBytes(16).toString('hex'), runId: crypto.randomBytes(16).toString('hex'), rootIdentity: { dev: 0, ino: 0 } },
        spawnFn,
        { registry, stopOwnedChild: (c) => { stopOwnedChildCalls += 1; c.kill('SIGTERM'); } }));
    assert.strictEqual(result.state, 'FAILED_BEFORE_PROCESS', 'test precondition: ' + JSON.stringify(result));

    // The child ACTUALLY spawns successfully, arriving LATE -- after the
    // caller already believes no process was ever created at all.
    child.emit('spawn');
    await new Promise((resolve) => setImmediate(resolve));

    assert.ok(stopOwnedChildCalls > 0, 'a late "spawn" event arriving after FAILED_BEFORE_PROCESS was already settled must force the now-known-live child to be stopped (or otherwise durably quarantined) -- currently the late "spawn" handler is gated on `settled`, which is already true by this point, so it silently no-ops: stopOwnedChild was never called for this now-orphaned, unregistered, genuinely-live child (stopOwnedChildCalls=' + stopOwnedChildCalls + ')');
  });

  test('STRUCTURAL: readCredentialSourceFd never calls fs.lstatSync at all, and calls fs.fstatSync exactly ONCE (before the read only) -- no re-fstat/re-lstat after the read to confirm the file\'s identity/metadata stayed stable throughout the whole operation, and no BigInt-precision identity tuple (dev/ino) is ever captured for that comparison', () => {
    const sourceText = fs.readFileSync(path.resolve(__dirname, '../lib/runtime-bridge-codex.cjs'), 'utf8');
    const fnStart = sourceText.indexOf('function readCredentialSourceFd');
    assert.ok(fnStart >= 0, 'test precondition: readCredentialSourceFd must exist');
    const nextFnIdx = sourceText.indexOf('\nfunction ', fnStart + 10);
    assert.ok(nextFnIdx > fnStart, 'test precondition: could not locate the next top-level function boundary');
    const fnBody = sourceText.slice(fnStart, nextFnIdx);
    const fstatCount = (fnBody.match(/fs\.fstatSync\(/g) || []).length;
    const lstatCount = (fnBody.match(/fs\.lstatSync\(/g) || []).length;
    const bigintFstatCount = (fnBody.match(/fs\.fstatSync\([^)]*bigint:\s*true/g) || []).length;
    assert.ok(lstatCount >= 1, 'readCredentialSourceFd must lstat the path (in addition to the fd-bound fstat) as part of its own hardening sequence -- currently zero lstat calls exist in its body');
    assert.ok(fstatCount >= 2, 'readCredentialSourceFd must re-fstat the fd AFTER the read completes, comparing against the initial fstat, to confirm the file\'s identity/metadata were stable throughout the entire read -- currently fstat is called exactly ' + fstatCount + ' time(s) (only before the read)');
    assert.ok(bigintFstatCount >= 1, 'the identity comparison (dev/ino) must use BigInt-precision stats ({bigint:true}), matching this file\'s own established identityTupleFor precedent -- currently fstat is never called with {bigint:true} anywhere in this function');
  });

  test('ATTACK: an invalid UTF-8 byte sequence inside a credential value is silently replaced with the Unicode replacement character rather than causing a fatal rejection -- the corrupted (not the actual on-disk) value is parsed, trusted, and returned as if it were the genuine credential', () => {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-nogo3-d-utf8-'));
    try {
      const credPath = path.join(dir, 'creds.json');
      const prefix = Buffer.from('{"credentials":{"accessToken":"', 'utf8');
      const invalidUtf8 = Buffer.from([0xff, 0xfe]); // never a valid UTF-8 byte sequence in any position.
      const suffix = Buffer.from('"},"otherCredentialFields":{},"expiresAt":"2030-01-01T00:00:00.000Z","sourceIdentity":"synthetic"}', 'utf8');
      fs.writeFileSync(credPath, Buffer.concat([prefix, invalidUtf8, suffix]), { mode: 0o600 });

      const provider = rbc.createCredentialSourceProviderForFdTests({ credentialPath: credPath });
      const result = provider.read();
      assert.strictEqual(result.ok, false, 'a credential file containing invalid UTF-8 bytes must be fatally rejected (e.g. CREDENTIAL_SOURCE_INVALID_UTF8), never silently decoded with replacement characters and then trusted as the genuine value -- currently: ' + JSON.stringify(result));
    } finally {
      cleanupDir(dir);
    }
  });

  test('ATTACK: a NESTED duplicate key (inside the credentials sub-object) is never detected -- only TOP-LEVEL duplicate keys are checked, so a nested duplicate silently resolves to whichever value appears LAST in the source text, unlike a top-level duplicate which is correctly rejected', () => {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-nogo3-d-nested-dup-'));
    try {
      const credPath = path.join(dir, 'creds.json');
      const firstToken = 'nested-dup-first-' + crypto.randomBytes(6).toString('hex');
      const secondToken = 'nested-dup-second-' + crypto.randomBytes(6).toString('hex');
      const rawText = '{"credentials":{"accessToken":"' + firstToken + '","accessToken":"' + secondToken + '"},"otherCredentialFields":{},"expiresAt":"2030-01-01T00:00:00.000Z","sourceIdentity":"synthetic"}';
      fs.writeFileSync(credPath, rawText, { mode: 0o600 });

      const provider = rbc.createCredentialSourceProviderForFdTests({ credentialPath: credPath });
      const result = provider.read();
      assert.strictEqual(result.ok, false, 'a NESTED duplicate key (inside credentials, not just at the top level) must be rejected exactly like a top-level duplicate is -- currently extractTopLevelJsonKeys only walks depth-1 keys, so this nested duplicate is silently accepted and JSON.parse keeps only the LAST value: ' + JSON.stringify(result));
    } finally {
      cleanupDir(dir);
    }
  });

  test('FIX (property 6, confirmed correct + mutation-revert proven): a credential file whose `credentials` field is a JSON STRING (not an object at all) is rejected (CREDENTIAL_SOURCE_NESTED_VALUE_INVALID) -- previously hasExactKeys only validated the TOP-LEVEL key SET, never that credentials/otherCredentialFields are themselves objects, so any primitive (string/number/array/null) in their place was silently accepted', () => {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-blockd-property6-nested-type-'));
    try {
      const credPath = path.join(dir, 'creds.json');
      const rawText = JSON.stringify({
        credentials: 'not-an-object-at-all',
        expiresAt: '2030-01-01T00:00:00.000Z',
        otherCredentialFields: {},
        sourceIdentity: 'synthetic',
      });
      fs.writeFileSync(credPath, rawText, { mode: 0o600 });

      const provider = rbc.createCredentialSourceProviderForFdTests({ credentialPath: credPath });
      const result = provider.read();
      assert.strictEqual(result.ok, false, 'a credentials field that is a bare JSON string (or any other non-object primitive) rather than a genuine object must be rejected -- currently hasExactKeys only checks the top-level key SET is exactly right, never that credentials/otherCredentialFields are themselves objects, so this passes every check and returns ok:true with credentials as a raw string: ' + JSON.stringify(result));
      assert.strictEqual(result.reason, 'CREDENTIAL_SOURCE_NESTED_VALUE_INVALID', JSON.stringify(result));
    } finally {
      cleanupDir(dir);
    }
  });

  test('FIX (property 6, symmetric coverage, confirmed correct + mutation-revert proven): the SAME nested-value-type rejection applies to `otherCredentialFields` -- a JSON STRING (not an object) in its place is rejected (CREDENTIAL_SOURCE_NESTED_VALUE_INVALID), not just credentials', () => {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-blockd-property6-othercredfields-nested-type-'));
    try {
      const credPath = path.join(dir, 'creds.json');
      const rawText = JSON.stringify({
        credentials: { accessToken: 'synthetic-token' },
        expiresAt: '2030-01-01T00:00:00.000Z',
        otherCredentialFields: 'not-an-object-at-all',
        sourceIdentity: 'synthetic',
      });
      fs.writeFileSync(credPath, rawText, { mode: 0o600 });

      const provider = rbc.createCredentialSourceProviderForFdTests({ credentialPath: credPath });
      const result = provider.read();
      assert.strictEqual(result.ok, false, 'an otherCredentialFields value that is a bare JSON string (or any other non-object primitive) rather than a genuine object must be rejected exactly like a malformed credentials field is: ' + JSON.stringify(result));
      assert.strictEqual(result.reason, 'CREDENTIAL_SOURCE_NESTED_VALUE_INVALID', JSON.stringify(result));
    } finally {
      cleanupDir(dir);
    }
  });

  test('FIX (Block D Group A, confirmed correct + mutation-revert proven): requireProvenChildIdentity\'s birthObservedAt is the child\'s REAL, host-observed process birth time (the SAME `ps -o lstart=` mechanism already used for the supervisor\'s own identity via defaultProcessIdentityProvider), never a bare `new Date().toISOString()` JS-side timestamp -- previously it proved nothing an external reader could not fabricate identically', async () => {
    const registry = rbc.createSupervisorOwnedChildRegistry();
    const child = makeFakeChildProcess(); // defaults to process.pid -- THIS test process's own real, always-alive pid (see makeFakeChildProcess's own comment).
    const spawnFn = () => {
      setImmediate(() => child.emit('spawn'));
      return child;
    };
    const result = await withFakeProcessIdentity(VALID_FAKE_IDENTITY, () =>
      rbc.spawnWithIntent(
        { instanceId: crypto.randomBytes(16).toString('hex'), repoId: crypto.randomBytes(16).toString('hex'), runId: crypto.randomBytes(16).toString('hex'), rootIdentity: { dev: 0, ino: 0 } },
        spawnFn,
        { registry, stopOwnedChild: (c) => c.kill('SIGTERM') }));
    assert.strictEqual(result.state, 'BORN', 'test precondition: ' + JSON.stringify(result));

    // Independently observe the SAME real pid's REAL, host-reported birth
    // time via the identical `ps -o lstart=` mechanism
    // defaultProcessIdentityProvider already uses for the supervisor's own
    // identity (cjs:188-206). lstart= reports a process's fixed start time,
    // so calling it a second time here, moments after BORN, for the SAME
    // still-alive pid, yields the identical string deterministically --
    // never flaky, never a race against real time.
    const independentlyObservedBirth = execFileSync('ps', ['-o', 'lstart=', '-p', String(process.pid)], { encoding: 'utf8' }).trim();
    assert.ok(independentlyObservedBirth.length > 0, 'test precondition: ps must be able to observe this test process\'s own real birth time');

    assert.strictEqual(result.childIdentity.birthObservedAt, independentlyObservedBirth, 'birthObservedAt must be the child\'s REAL, host-observed process birth time (the same ps -o lstart= mechanism already used for the supervisor\'s own identity), never a bare JS-side new Date().toISOString() -- currently it is always a fresh ISO-8601 timestamp regardless of the pid\'s actual OS-reported birth: ' + JSON.stringify(result.childIdentity));
  });

  test('FIX (Block D Group A, confirmed correct + mutation-revert proven): requireProvenChildIdentity correlates a child\'s spawnfile against the run\'s own actual expected/canonical executable (via expectedExecutable) -- previously ANY real, existing file was accepted, so a child that (via bug or attack) launched a DIFFERENT real executable was accepted identically to the correct one', async () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-blockd-groupa-execmismatch-'));
    try {
      // Two distinct, real, existing, hermetic tmp files -- neither is a
      // symlink or anything exotic, just two genuinely different regular
      // files, so this exercises the CORRELATION check itself, never the
      // pre-existing existence-only check (which both of these already pass).
      const actualSpawnfile = path.join(tmp, 'actual-executable-used');
      const expectedExecutable = path.join(tmp, 'expected-canonical-executable');
      fs.writeFileSync(actualSpawnfile, 'not the executable this run actually expected\n');
      fs.writeFileSync(expectedExecutable, 'the run\'s own actual expected/canonical executable\n');

      const registry = rbc.createSupervisorOwnedChildRegistry();
      const child = makeFakeChildProcess(); // defaults to process.pid -- clears the liveness check.
      child.spawnfile = actualSpawnfile;
      const spawnFn = () => {
        setImmediate(() => child.emit('spawn'));
        return child;
      };
      const result = await withFakeProcessIdentity(VALID_FAKE_IDENTITY, () =>
        rbc.spawnWithIntent(
          { instanceId: crypto.randomBytes(16).toString('hex'), repoId: crypto.randomBytes(16).toString('hex'), runId: crypto.randomBytes(16).toString('hex'), rootIdentity: { dev: 0, ino: 0 } },
          spawnFn,
          // identityTimeoutMs/stopConfirmTimeoutMs kept small -- this file's
          // own established convention for fast rejection-path tests (see
          // e.g. lines 2389/2419/3285) -- the default 5000ms stopConfirmTimeoutMs
          // would otherwise make this specific test needlessly slow.
          { registry, identityTimeoutMs: 200, stopConfirmTimeoutMs: 200, stopOwnedChild: (c) => c.kill('SIGTERM'), expectedExecutable }));
      // spawnWithIntent's outer result never surfaces requireProvenChildIdentity's
      // OWN specific rejection reason (identity failures route through
      // startStopping(), which only ever settles as STOPPED/UNKNOWN_OWNED --
      // see the existing analogous PID-rejection CONFIRMATION test above,
      // which asserts state only, never a reason) -- state is therefore the
      // only assertable, honest signal at this level.
      assert.notStrictEqual(result.state, 'BORN', 'a child whose real, existing spawnfile does not match the run\'s own actual expected/canonical executable must never be accepted as genuinely BORN -- currently requireProvenChildIdentity only checks that SOME real file exists at spawnfile, never that it is the EXPECTED one, so a different-but-real executable is accepted identically to the correct one: ' + JSON.stringify(result));
    } finally {
      cleanupDir(tmp);
    }
  });
});

