      assert.strictEqual(result.reason, 'ROOT_NOT_PROFILE_PENDING', 'a second finalizeRunRoot call on a handle already in READY state must be rejected ROOT_NOT_PROFILE_PENDING (checked before the capability is ever touched) -- currently: ' + JSON.stringify(result));
