      const afterMutation = fixture.isolationProvider.withValidatedRoot(fixture.sealHandle, { runId: fixture.runId, role: fixture.role }, probe);
      assert.strictEqual(afterMutation.reason, 'VALIDATED_ROOT_DRIFT_FROM_SEAL', 'a mutation to a host-owned, non-config topology directory (cwd) must be caught as drift just as a config.toml mutation would be -- finalIdentitySnapshot covers all 8 topology layers, so this must fire: ' + JSON.stringify(afterMutation));
