describe('CORRECTION ROUND (post-FOURTH HARD NO-GO RESPONSE) -- Block A: CredentialBroker/refresh settlement via REAL C2 wiring', () => {
  async function waitUntil(predicate, maxIterations) {
    for (let i = 0; i < (maxIterations || 50); i++) {
      if (predicate()) return true;
      await new Promise((resolve) => setImmediate(resolve));
    }
    return predicate();
  }

  // Local helper -- deliberately NOT reusing the sibling "FOURTH HARD NO-GO
  // RESPONSE -- Block D item 4" describe block's own
  // createAuthenticatedMidTurnConnection (out of scope from this sibling
  // block, and goes further than this test needs -- threadStart/turnStart
  // are irrelevant to a refresh-settlement test). Drives ONLY
  // initialize -> login, wiring the SAME real `binding` object (the exact
  // object bindConnection() returns) as both `refreshProvider` and
  // `credentialBinding`.
  async function createAuthenticatedConnection(binding, accountId) {
    const stdin = new PassThrough();
    const stdout = new PassThrough();
    const connection = rbc.createAppServerConnection({ stdin, stdout, refreshProvider: binding.refreshProvider, credentialBinding: binding });
    const capturedIds = {};
    stdin.on('data', (chunk) => {
      for (const line of chunk.toString('utf8').split('\n')) {
        if (!line.trim()) continue;
        try { const frame = JSON.parse(line); if (frame.method) capturedIds[frame.method] = frame.id; } catch (err) { /* partial chunk fragment */ }
      }
    });

    const initPromise = connection.initialize();
    await new Promise((resolve) => setImmediate(resolve));
    await new Promise((resolve) => rbc.writeJsonlFrame(stdout, { id: capturedIds['initialize'], result: { codexHome: '/fake', platformFamily: 'unix', platformOs: 'macos', userAgent: 'fake' } }, resolve));
    const initResult = await initPromise;
    if (!initResult.ok) throw new Error('createAuthenticatedConnection precondition (initialize) failed: ' + JSON.stringify(initResult));

    const loginPromise = connection.login({ accessToken: 'fake-login-token-' + accountId, chatgptAccountId: accountId, chatgptPlanType: 'plus' });
    await new Promise((resolve) => setImmediate(resolve));
    await new Promise((resolve) => rbc.writeJsonlFrame(stdout, { id: capturedIds['account/login/start'], result: { type: 'chatgptAuthTokens', accessToken: 'fake-login-token-' + accountId, chatgptAccountId: accountId, chatgptPlanType: 'plus' } }, resolve));
    await new Promise((resolve) => rbc.writeJsonlFrame(stdout, { method: 'account/updated', params: { authMode: 'chatgptAuthTokens', planType: 'plus' } }, resolve));
    const loginResult = await loginPromise;
    if (!loginResult.ok) throw new Error('createAuthenticatedConnection precondition (login) failed: ' + JSON.stringify(loginResult));

    return { connection, stdin, stdout };
  }

  test('FIX (confirmed correct once toolkit-specialist\'s real-settlement-channel fix landed): a REAL createAppServerConnection wired with the REAL bindConnection() result as credentialBinding correctly WITHHOLDS the broker-side host-wide account commit when C2\'s own identity check (finishRefreshResult) genuinely rejects the refreshed credential and the connection never reaches a confirmed flush for it', async () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-block-a-real-wiring-'));
    const fixture = makeSealedIsolationFixture(tmp);
    const LOGIN_ACCOUNT = 'acct-block-a-login-genuine';
    const MISMATCHED_REFRESH_ACCOUNT = 'acct-block-a-mismatched-from-source';
    const DIFFERENT_LEGITIMATE_ACCOUNT = 'acct-block-a-unrelated-legitimate';
    try {
      let sourceReadCallCount = 0;
      const deps = validAuthoritiesDeps(fixture, {
        expectedRoster: [{ role: 'verifier', ordinal: 0 }, { role: 'verifier', ordinal: 1 }],
        sourceProvider: {
          read: () => {
            sourceReadCallCount += 1;
            // Call #1 (connection A's real SR-01 refresh) deliberately
            // returns an account DIFFERENT from the one login() authenticated
            // -- C2's own identity check must genuinely reject it. Call #2
            // (connection B's direct refreshProvider() probe) returns a
            // THIRD, wholly unrelated account, so any rejection it receives
            // can only be explained by the broker's own corrupted
            // hostWideBoundAccountId, never a coincidental match.
            const accountId = sourceReadCallCount === 1 ? MISMATCHED_REFRESH_ACCOUNT : DIFFERENT_LEGITIMATE_ACCOUNT;
            return {
              ok: true,
              credentials: { accessToken: syntheticSecret('block-a-real-wiring-' + sourceReadCallCount), chatgptAccountId: accountId, chatgptPlanType: 'plus' },
              otherCredentialFields: {},
              expiresAt: futureIso(400 * 1000),
              sourceIdentity: 'block-a-real-wiring-fixture',
            };
          },
        },
      });
      const authorities = rbc.createRunAuthorities(deps);
      const bindingA = authorities.bindConnection({ role: 'verifier', ordinal: 0 });
      const bindingB = authorities.bindConnection({ role: 'verifier', ordinal: 1 });
      assert.strictEqual(typeof bindingA.reason, 'undefined', JSON.stringify(bindingA));
      assert.strictEqual(typeof bindingB.reason, 'undefined', JSON.stringify(bindingB));

      // THE central wiring this test exists to exercise: the SAME real
      // bindingA object threaded as BOTH refreshProvider AND credentialBinding
      // -- exactly the pattern createAppServerConnection's own constructor
      // implies (runtime-bridge-codex.cjs:1585), never a hand-rolled fake
      // listener standing in for it.
      const { connection: connectionA, stdout: stdoutA } = await createAuthenticatedConnection(bindingA, LOGIN_ACCOUNT);
      assert.strictEqual(connectionA.isStopped(), false, 'test precondition: connection A must be live and authenticated before the refresh attempt');

      // C2 (the app-server) sends a REAL account/chatgptAuthTokens/refresh
      // server-request over the wire -- the ONLY real call site that ever
      // invokes refreshProvider in production (handleServerRequest SR-01,
      // runtime-bridge-codex.cjs:1941). params shape confirmed empirically
      // against the real generated validator (base::ChatgptAuthTokensRefreshParams):
      // {reason:'unauthorized'} is the minimal valid shape.
      await new Promise((resolve) => rbc.writeJsonlFrame(stdoutA, { id: 'block-a-refresh-req-1', method: 'account/chatgptAuthTokens/refresh', params: { reason: 'unauthorized' } }, resolve));

      const stopped = await waitUntil(() => connectionA.isStopped());
      assert.strictEqual(stopped, true, 'test precondition: C2\'s own identity check (finishRefreshResult) must genuinely reject the mismatched-account refresh and stop the connection -- if this fails, the fixture itself is wrong, not the bug under test: ' + JSON.stringify({ phase: connectionA.connectionPhase(), reason: connectionA.stopReason() }));

      // THE PROPERTY THIS PROVES: since C2 never confirmed/flushed this
      // credential (the connection stopped rather than ever emitting a
      // success reply), the broker must NEVER have committed
      // hostWideBoundAccountId to the mismatched account -- proven
      // observably via connection B, a DIFFERENT connection on the SAME
      // composition root, whose own legitimate refresh (a genuinely
      // different, unrelated account) must succeed cleanly as a genuine
      // first bind, never wrongly rejected ACCOUNT_MISMATCH against an
      // account C2 itself never accepted or flushed.
      const bindingBOutcome = bindingB.refreshProvider({});
      // A precise, POSITIVE assertion -- not merely "not ACCOUNT_MISMATCH"
      // (which would also, wrongly, pass if B failed for some OTHER,
      // unrelated reason, proving nothing about the abort-vs-commit property
      // this test actually exists to check).
      assert.strictEqual(bindingBOutcome.ok, true, 'the broker must never commit hostWideBoundAccountId to a credential C2 itself rejected and never confirmed via flush -- commit/release must happen ONLY after confirmed C2 flush success, not the instant the source read resolves inside refreshProvider(); connection B\'s own legitimate, unrelated refresh must succeed cleanly as a genuine first bind: ' + JSON.stringify(bindingBOutcome) + ' connectionA stopReason=' + connectionA.stopReason());
      assert.strictEqual(bindingBOutcome.chatgptAccountId, DIFFERENT_LEGITIMATE_ACCOUNT, 'connection B must bind its OWN account, never be silently coerced to A\'s prematurely-committed one: ' + JSON.stringify(bindingBOutcome));
    } finally {
      cleanupDir(tmp);
    }
  });

  // Tests below exercise settleAndReturn's own resolve/reject/throw branching
  // directly via bindConnection()'s real onRefreshOutcome (real broker code,
  // not a mock of it) -- a companion to the integration test above, isolating
  // the specific commit-vs-abort branch logic in a way independent of
  // createAppServerConnection's own internal settlement wiring. Per the
  // dispatch's own "not merely Promise consumption" bar, these stay
  // companions to the real-wiring test above, never a replacement for it.

  test('FIX (confirmed correct once toolkit-specialist\'s fix landed): onRefreshOutcome listener REJECTS (representing a genuine C2 settlement failure) -- settleAndReturn correctly ABORTS (releases the lock without committing), since confirmation.then(commitNow, abortOnly) no longer treats resolve and reject identically', async () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-block-a-reject-'));
    const fixture = makeSealedIsolationFixture(tmp);
    try {
      // Call-counter-based, same discriminating shape as the real-wiring
      // test above: A's call gets one account, B's call gets a wholly
      // UNRELATED one -- if B is later rejected ACCOUNT_MISMATCH, that can
      // only be explained by A's (buggy) premature commit, never a
      // coincidental match (a single shared fixed account for both, as an
      // earlier draft of this test used, would pass regardless of whether
      // the abort-on-reject logic is correct or not -- a false green).
      let sourceReadCallCount = 0;
      const authorities = rbc.createRunAuthorities(validAuthoritiesDeps(fixture, {
        expectedRoster: [{ role: 'verifier', ordinal: 0 }, { role: 'verifier', ordinal: 1 }],
        sourceProvider: {
          read: () => {
            sourceReadCallCount += 1;
            const accountId = sourceReadCallCount === 1 ? 'acct-block-a-reject-committed' : 'acct-block-a-reject-unrelated';
            return { ok: true, credentials: { accessToken: syntheticSecret('block-a-reject-' + sourceReadCallCount), chatgptAccountId: accountId, chatgptPlanType: 'plus' }, otherCredentialFields: {}, expiresAt: futureIso(400 * 1000), sourceIdentity: 'block-a-reject-fixture' };
          },
        },
      }));
      const bindingA = authorities.bindConnection({ role: 'verifier', ordinal: 0 });
      const bindingB = authorities.bindConnection({ role: 'verifier', ordinal: 1 });
      assert.strictEqual(typeof bindingA.reason, 'undefined', JSON.stringify(bindingA));
      assert.strictEqual(typeof bindingB.reason, 'undefined', JSON.stringify(bindingB));

      let listenerConfirmationPromise = null;
      bindingA.onRefreshOutcome(() => {
        listenerConfirmationPromise = Promise.reject(new Error('simulated-c2-flush-failure'));
        return listenerConfirmationPromise;
      });
      const outcomeA = bindingA.refreshProvider({});
      assert.strictEqual(outcomeA.ok, true, 'test precondition: the source read itself must succeed -- this test is about what happens AFTER, during settlement: ' + JSON.stringify(outcomeA));
      assert.ok(listenerConfirmationPromise, 'test precondition: the registered onRefreshOutcome listener must have been invoked');

      // Deterministically wait for OUR OWN reference to the exact same
      // promise settleAndReturn awaits, rather than a blind tick count --
      // microtask handlers registered on one promise fire in registration
      // order, and settleAndReturn's own confirmation.then(commitNow,
      // abortOnly) is registered BEFORE this .catch(), so by the time this
      // settles, whichever branch fires has already run. Two extra
      // setImmediate ticks add margin against unrelated event-loop pressure
      // from sibling tests when this file runs as part of the full suite.
      await listenerConfirmationPromise.catch(() => {});
      await new Promise((resolve) => setImmediate(resolve));
      await new Promise((resolve) => setImmediate(resolve));

      const outcomeB = bindingB.refreshProvider({});
      assert.strictEqual(outcomeB.ok, true, 'the broker must never commit an account whose settlement listener explicitly REJECTED -- a rejection must abort (release the lock without committing), never commit anyway; connection B\'s own unrelated refresh must succeed cleanly: ' + JSON.stringify(outcomeB));
    } finally {
      cleanupDir(tmp);
    }
  });

  test('FIX (confirmed correct once toolkit-specialist\'s fix landed): onRefreshOutcome listener THROWS synchronously (representing a genuine settlement failure) -- the throw is correctly routed to abortOnly() (never silently swallowed into a synchronous commit)', () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-block-a-throw-'));
    const fixture = makeSealedIsolationFixture(tmp);
    try {
      // Call-counter-based -- same reasoning as the reject test above: A and
      // B must get DIFFERENT accounts so a later ACCOUNT_MISMATCH on B can
      // only be explained by A's premature commit, never a coincidental
      // match.
      let sourceReadCallCount = 0;
      const authorities = rbc.createRunAuthorities(validAuthoritiesDeps(fixture, {
        expectedRoster: [{ role: 'verifier', ordinal: 0 }, { role: 'verifier', ordinal: 1 }],
        sourceProvider: {
          read: () => {
            sourceReadCallCount += 1;
            const accountId = sourceReadCallCount === 1 ? 'acct-block-a-throw-committed' : 'acct-block-a-throw-unrelated';
            return { ok: true, credentials: { accessToken: syntheticSecret('block-a-throw-' + sourceReadCallCount), chatgptAccountId: accountId, chatgptPlanType: 'plus' }, otherCredentialFields: {}, expiresAt: futureIso(400 * 1000), sourceIdentity: 'block-a-throw-fixture' };
          },
        },
      }));
      const bindingA = authorities.bindConnection({ role: 'verifier', ordinal: 0 });
      const bindingB = authorities.bindConnection({ role: 'verifier', ordinal: 1 });
      assert.strictEqual(typeof bindingA.reason, 'undefined', JSON.stringify(bindingA));
      assert.strictEqual(typeof bindingB.reason, 'undefined', JSON.stringify(bindingB));

      bindingA.onRefreshOutcome(() => { throw new Error('simulated-listener-crash-during-settlement'); });
      const outcomeA = bindingA.refreshProvider({});
      assert.strictEqual(outcomeA.ok, true, 'test precondition: the source read itself must succeed -- this test is about what happens AFTER, during settlement: ' + JSON.stringify(outcomeA));

      const outcomeB = bindingB.refreshProvider({});
      assert.strictEqual(outcomeB.ok, true, 'a throwing settlement listener must never be silently swallowed into a synchronous commit -- a throw must abort (release the lock without committing), exactly like a rejection; connection B\'s own unrelated refresh must succeed cleanly: ' + JSON.stringify(outcomeB));
    } finally {
      cleanupDir(tmp);
    }
  });

  test('FIX (confirmed correct once toolkit-specialist\'s fix landed): close() correctly aborts an in-flight attempt suspended on a never-resolving sourceProvider.read() -- the host-wide refresh lock is force-released (via inFlightAttemptId), never blocking every OTHER connection on this run forever, per PLAN.md\'s requirement that a never-resolving async source be abortable by close() and release only its own lock', async () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-block-a-hung-close-'));
    const fixture = makeSealedIsolationFixture(tmp);
    try {
      const LEGITIMATE_ACCOUNT = 'acct-block-a-hung-close-legitimate';
      let sourceReadCallCount = 0;
      const deps = validAuthoritiesDeps(fixture, {
        expectedRoster: [{ role: 'verifier', ordinal: 0 }, { role: 'verifier', ordinal: 1 }],
        sourceProvider: {
          read: () => {
            sourceReadCallCount += 1;
            // Call #1 (A's attempt) deliberately never resolves or rejects --
            // models a genuinely hung credential source (e.g. a network call
            // that never returns). Call #2 (B's attempt) resolves normally --
            // if B's own read ALSO hung, B's own refreshProvider() would
            // return an eternally-pending promise too, making any .ok check
            // on it meaningless (checking a Promise object, not a resolved
            // value) regardless of whether close() correctly released A's
            // lock or not.
            if (sourceReadCallCount === 1) return new Promise(() => { /* never settles */ });
            return { ok: true, credentials: { accessToken: syntheticSecret('block-a-hung-close-' + sourceReadCallCount), chatgptAccountId: LEGITIMATE_ACCOUNT, chatgptPlanType: 'plus' }, otherCredentialFields: {}, expiresAt: futureIso(400 * 1000), sourceIdentity: 'block-a-hung-close-fixture' };
          },
        },
      });
      const authorities = rbc.createRunAuthorities(deps);
      const bindingA = authorities.bindConnection({ role: 'verifier', ordinal: 0 });
      const bindingB = authorities.bindConnection({ role: 'verifier', ordinal: 1 });
      assert.strictEqual(typeof bindingA.reason, 'undefined', JSON.stringify(bindingA));
      assert.strictEqual(typeof bindingB.reason, 'undefined', JSON.stringify(bindingB));

      // Start A's refresh -- the lock is acquired, then suspended forever on
      // the hung source read. Deliberately never awaited (it never settles).
      const hangingRefreshPromise = bindingA.refreshProvider({});
      void hangingRefreshPromise;
      await new Promise((resolve) => setImmediate(resolve));

      const closeResult = bindingA.close();
      assert.strictEqual(closeResult.ok, true, 'test precondition: close() itself must report success: ' + JSON.stringify(closeResult));

      const outcomeB = bindingB.refreshProvider({});
      assert.strictEqual(outcomeB.ok, true, 'close() must force-release a lock held by an attempt suspended on a never-resolving sourceProvider.read() -- currently the lock is only ever released naturally once the read resolves, which for a genuinely hung source never happens, permanently blocking every other connection on this composition root: ' + JSON.stringify(outcomeB));
    } finally {
      cleanupDir(tmp);
    }
  });

  // Team-lead-requested addition (design review of Fix A/B/C): the
  // single-slot `pendingCredentialSettlement` per connection relies
  // structurally on the host-wide refresh lock to guarantee a second attempt
  // can never reach `outcomeListener` again while a first attempt's
  // settlement is still open. True by construction today, but not
  // previously proven directly -- a future change that accidentally weakens
  // lock-serialization would silently corrupt settlement identity rather
  // than being caught here.
  test('PROOF: a second refresh attempt while the FIRST attempt\'s settlement is genuinely still pending (its listener\'s returned promise not yet resolved) is rejected LOCK_DENIED -- the host-wide lock stays held through the ENTIRE settlement window, not just the source read, so a second attempt can never reach (and corrupt) the single-slot pending settlement', async () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-block-a-lock-serialization-'));
    const fixture = makeSealedIsolationFixture(tmp);
    try {
      const authorities = rbc.createRunAuthorities(validAuthoritiesDeps(fixture, {
        expectedRoster: [{ role: 'verifier', ordinal: 0 }, { role: 'verifier', ordinal: 1 }],
        sourceProvider: { read: () => ({ ok: true, credentials: { accessToken: syntheticSecret('lock-serialization'), chatgptAccountId: 'acct-lock-serialization', chatgptPlanType: 'plus' }, otherCredentialFields: {}, expiresAt: futureIso(400 * 1000), sourceIdentity: 'lock-serialization-fixture' }) },
      }));
      const bindingA = authorities.bindConnection({ role: 'verifier', ordinal: 0 });
      const bindingB = authorities.bindConnection({ role: 'verifier', ordinal: 1 });
      assert.strictEqual(typeof bindingA.reason, 'undefined', JSON.stringify(bindingA));
      assert.strictEqual(typeof bindingB.reason, 'undefined', JSON.stringify(bindingB));

      // The listener's returned promise NEVER settles -- models C2's own
      // settlement confirmation genuinely still being in flight (e.g. the
      // wire write has not yet flushed, or shape/identity checks are still
      // pending).
      bindingA.onRefreshOutcome(() => new Promise(() => { /* never settles */ }));
      const outcomeA = bindingA.refreshProvider({});
      assert.strictEqual(outcomeA.ok, true, 'test precondition: the source read itself must succeed -- this test is about the lock during the SETTLEMENT window, after the read already succeeded: ' + JSON.stringify(outcomeA));

      const outcomeB = bindingB.refreshProvider({});
      assert.strictEqual(outcomeB.ok, false, JSON.stringify(outcomeB));
      assert.strictEqual(outcomeB.reason, 'LOCK_DENIED', 'a second refresh attempt must be rejected LOCK_DENIED while the FIRST attempt\'s settlement is genuinely still pending -- the host-wide lock must stay held through the entire settlement window (not just the source read), never letting a second attempt reach the single-slot pending settlement: ' + JSON.stringify(outcomeB));
    } finally {
      cleanupDir(tmp);
    }
  });

  // Remaining exactly-once abort triggers named in Block A's own dispatch
  // ("Shape, identity, replay, write error, timeout, STOP... must each abort
  // exactly once") not yet individually proven: identity is covered by the
  // real-wiring test above; listener throw/rejection and connection close
  // are covered above. Shape, replay, write error, and STOP-mid-settlement
  // are proven below, each isolating its own distinct terminal call to
  // settlePendingCredentialOutcome inside createAppServerConnection
  // (confirmed by direct source read this round): shape/identity/replay
  // share one call site (finishRefreshResult's validation-failed branch,
  // runtime-bridge-codex.cjs:~2096) but are functionally independent
  // triggers (shapeOk/identityOk/tokenGenuinelyNew are three separate
  // booleans), write error has its own site (~2086), and an unrelated STOP
  // (malformed frame / transport EOF/error) has its own site inside
  // finalizeStop (~1775). Timeout (~2068, DEFAULT_RPC_TIMEOUT_MS=10s) is
  // deliberately left to a follow-up test using node:test's mock timers
  // rather than a real 10-second wait.

  test('PROOF: a SHAPE-invalid refresh result (empty accessToken, otherwise correctly-identified account) is rejected by C2\'s own finishRefreshResult and never commits the broker-side account -- isolates the shape check specifically from the identity check the real-wiring test above already covers', async () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-block-a-shape-'));
    const fixture = makeSealedIsolationFixture(tmp);
    const LOGIN_ACCOUNT = 'acct-block-a-shape-login';
    const DIFFERENT_LEGITIMATE_ACCOUNT = 'acct-block-a-shape-unrelated';
    try {
      let sourceReadCallCount = 0;
      const deps = validAuthoritiesDeps(fixture, {
        expectedRoster: [{ role: 'verifier', ordinal: 0 }, { role: 'verifier', ordinal: 1 }],
        sourceProvider: {
          read: () => {
            sourceReadCallCount += 1;
            // Call #1 (A): correctly-identified account, but a deliberately
            // EMPTY accessToken -- shape-invalid, identity would otherwise be
            // fine. Call #2 (B): a wholly unrelated, well-formed account.
            if (sourceReadCallCount === 1) {
              return { ok: true, credentials: { accessToken: '', chatgptAccountId: LOGIN_ACCOUNT, chatgptPlanType: 'plus' }, otherCredentialFields: {}, expiresAt: futureIso(400 * 1000), sourceIdentity: 'block-a-shape-fixture' };
            }
            return { ok: true, credentials: { accessToken: syntheticSecret('block-a-shape-' + sourceReadCallCount), chatgptAccountId: DIFFERENT_LEGITIMATE_ACCOUNT, chatgptPlanType: 'plus' }, otherCredentialFields: {}, expiresAt: futureIso(400 * 1000), sourceIdentity: 'block-a-shape-fixture' };
          },
        },
      });
      const authorities = rbc.createRunAuthorities(deps);
      const bindingA = authorities.bindConnection({ role: 'verifier', ordinal: 0 });
      const bindingB = authorities.bindConnection({ role: 'verifier', ordinal: 1 });
      assert.strictEqual(typeof bindingA.reason, 'undefined', JSON.stringify(bindingA));
      assert.strictEqual(typeof bindingB.reason, 'undefined', JSON.stringify(bindingB));

      const { connection: connectionA, stdout: stdoutA } = await createAuthenticatedConnection(bindingA, LOGIN_ACCOUNT);
      await new Promise((resolve) => rbc.writeJsonlFrame(stdoutA, { id: 'block-a-shape-refresh-1', method: 'account/chatgptAuthTokens/refresh', params: { reason: 'unauthorized' } }, resolve));
      const stopped = await waitUntil(() => connectionA.isStopped());
      assert.strictEqual(stopped, true, 'test precondition: an empty accessToken must genuinely fail C2\'s own shape check and stop the connection: ' + JSON.stringify({ phase: connectionA.connectionPhase(), reason: connectionA.stopReason() }));

      const outcomeB = bindingB.refreshProvider({});
      assert.strictEqual(outcomeB.ok, true, 'a shape-invalid refresh result must never commit the broker-side account, even when the account identity itself was correct -- connection B\'s own unrelated, well-formed refresh must succeed cleanly: ' + JSON.stringify(outcomeB));
      assert.strictEqual(outcomeB.chatgptAccountId, DIFFERENT_LEGITIMATE_ACCOUNT, JSON.stringify(outcomeB));
    } finally {
      cleanupDir(tmp);
    }
  });

  // STATUS (DOCUMENTATION -- structurally CANNOT discriminate premature-vs-
  // confirmed commit for this specific trigger, not a coverage gap this
  // file failed to close): a replay is, by definition, a stale-but-valid
  // credential for the account this connection ALREADY legitimately owns
  // (from its own prior, genuinely-confirmed refresh) -- so even under the
  // pre-fix premature-commit bug, the wrongly-early-committed value is
  // BYTE-IDENTICAL to what correct behavior would eventually commit anyway,
  // just earlier. The account-mismatch side channel every OTHER test in
  // this block uses to discriminate genuinely cannot see a timing-only
  // difference in an identical value (confirmed independently by team-lead:
  // lastCredentialRefreshOutcome is captured at listener-invocation time,
  // before settlement resolves, so it also reads identically pre/post-fix --
  // no black-box signal discriminates this case without abandoning the
  // real-wiring requirement). This test still proves something real and
  // worth keeping: C2's own replay/rollback detection (tokenGenuinelyNew)
  // correctly rejects a reused token and the connection stops cleanly, with
  // the broker-side lock verifiably NOT left stuck afterward. It does NOT
  // prove "replay avoids premature commit" the way the identity/shape/
  // write-error/timeout/STOP tests prove their own triggers -- a future
  // reader should not over-credit this test as covering that property.
  test('PROOF (see STATUS note above -- does not discriminate premature-vs-confirmed commit): a REPLAYED accessToken (identical to one already confirmed-flushed earlier on this SAME connection) is rejected by C2\'s own finishRefreshResult, and the broker-side lock is correctly released (never left stuck) afterward -- isolates the replay/rollback DETECTION specifically, not the commit-timing property', async () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-block-a-replay-'));
    const fixture = makeSealedIsolationFixture(tmp);
    const LOGIN_ACCOUNT = 'acct-block-a-replay-login';
    const REPLAYED_TOKEN = syntheticSecret('block-a-replay-reused');
    try {
      let sourceReadCallCount = 0;
      const deps = validAuthoritiesDeps(fixture, {
        expectedRoster: [{ role: 'verifier', ordinal: 0 }, { role: 'verifier', ordinal: 1 }],
        sourceProvider: {
          read: () => {
            sourceReadCallCount += 1;
            // Call #1 (A, first refresh): a genuinely fresh token -- must
            // succeed fully (real flush confirmed) so usedAccessTokens
            // actually contains it. Call #2 (A, second refresh): the EXACT
            // SAME token again -- a rollback/replay. Call #3 (B's probe):
            // a fresh token, SAME account (already legitimately committed
            // by call #1) -- isolates the LOCK_DENIED question from any
            // ACCOUNT_MISMATCH confound.
            if (sourceReadCallCount === 1 || sourceReadCallCount === 2) {
              return { ok: true, credentials: { accessToken: REPLAYED_TOKEN, chatgptAccountId: LOGIN_ACCOUNT, chatgptPlanType: 'plus' }, otherCredentialFields: {}, expiresAt: futureIso(400 * 1000), sourceIdentity: 'block-a-replay-fixture' };
            }
            return { ok: true, credentials: { accessToken: syntheticSecret('block-a-replay-fresh-' + sourceReadCallCount), chatgptAccountId: LOGIN_ACCOUNT, chatgptPlanType: 'plus' }, otherCredentialFields: {}, expiresAt: futureIso(400 * 1000), sourceIdentity: 'block-a-replay-fixture' };
          },
        },
      });
      const authorities = rbc.createRunAuthorities(deps);
      const bindingA = authorities.bindConnection({ role: 'verifier', ordinal: 0 });
      const bindingB = authorities.bindConnection({ role: 'verifier', ordinal: 1 });
      assert.strictEqual(typeof bindingA.reason, 'undefined', JSON.stringify(bindingA));
      assert.strictEqual(typeof bindingB.reason, 'undefined', JSON.stringify(bindingB));

      const { connection: connectionA, stdout: stdoutA } = await createAuthenticatedConnection(bindingA, LOGIN_ACCOUNT);

      // First refresh: genuinely fresh token, must succeed fully (the
      // connection stays alive -- only a REJECTED refresh stops it).
      await new Promise((resolve) => rbc.writeJsonlFrame(stdoutA, { id: 'block-a-replay-refresh-1', method: 'account/chatgptAuthTokens/refresh', params: { reason: 'unauthorized' } }, resolve));
      await new Promise((resolve) => setImmediate(resolve));
      await new Promise((resolve) => setImmediate(resolve));
      assert.strictEqual(connectionA.isStopped(), false, 'test precondition: the FIRST, genuinely-fresh-token refresh must succeed and keep the connection alive: ' + JSON.stringify({ phase: connectionA.connectionPhase(), reason: connectionA.stopReason() }));

      // Second refresh: the EXACT SAME token again -- a rollback/replay.
      await new Promise((resolve) => rbc.writeJsonlFrame(stdoutA, { id: 'block-a-replay-refresh-2', method: 'account/chatgptAuthTokens/refresh', params: { reason: 'unauthorized' } }, resolve));
      const stopped = await waitUntil(() => connectionA.isStopped());
      assert.strictEqual(stopped, true, 'test precondition: a REPLAYED (already-used) accessToken must genuinely fail C2\'s own replay check and stop the connection: ' + JSON.stringify({ phase: connectionA.connectionPhase(), reason: connectionA.stopReason() }));

      const outcomeB = bindingB.refreshProvider({});
      assert.strictEqual(outcomeB.ok, true, 'a replay-rejected settlement must correctly release the broker-side lock (abort, never stuck) -- connection B\'s own refresh (same, already-legitimately-committed account, so ACCOUNT_MISMATCH cannot be the cause of any failure here) must succeed cleanly, proving the lock is free: ' + JSON.stringify(outcomeB));
    } finally {
      cleanupDir(tmp);
    }
  });

  test('PROOF: a failed wire flush (the refresh reply\'s own stdin write fails) is treated as an abort, never a commit -- the broker-side account is never committed for a credential that was never actually confirmed delivered to C2', async () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-block-a-writeerror-'));
    const fixture = makeSealedIsolationFixture(tmp);
    const LOGIN_ACCOUNT = 'acct-block-a-writeerror-login';
    const DIFFERENT_LEGITIMATE_ACCOUNT = 'acct-block-a-writeerror-unrelated';
    try {
      let sourceReadCallCount = 0;
      const deps = validAuthoritiesDeps(fixture, {
        expectedRoster: [{ role: 'verifier', ordinal: 0 }, { role: 'verifier', ordinal: 1 }],
        sourceProvider: {
          read: () => {
            sourceReadCallCount += 1;
            const accountId = sourceReadCallCount === 1 ? LOGIN_ACCOUNT : DIFFERENT_LEGITIMATE_ACCOUNT;
            return { ok: true, credentials: { accessToken: syntheticSecret('block-a-writeerror-' + sourceReadCallCount), chatgptAccountId: accountId, chatgptPlanType: 'plus' }, otherCredentialFields: {}, expiresAt: futureIso(400 * 1000), sourceIdentity: 'block-a-writeerror-fixture' };
          },
        },
      });
      const authorities = rbc.createRunAuthorities(deps);
      const bindingA = authorities.bindConnection({ role: 'verifier', ordinal: 0 });
      const bindingB = authorities.bindConnection({ role: 'verifier', ordinal: 1 });
      assert.strictEqual(typeof bindingA.reason, 'undefined', JSON.stringify(bindingA));
      assert.strictEqual(typeof bindingB.reason, 'undefined', JSON.stringify(bindingB));

      const { connection: connectionA, stdin: stdinA, stdout: stdoutA } = await createAuthenticatedConnection(bindingA, LOGIN_ACCOUNT);

      // Intercept ONLY writes made AFTER this point -- initialize()/login()'s
      // own writes have already completed by the time this test sends the
      // refresh request, so this targets exactly (and only) the refresh
      // reply's own flush, simulating e.g. a broken pipe (EPIPE) at the
      // precise moment C2 would otherwise have received the credential.
      const originalWrite = stdinA.write.bind(stdinA);
      let interceptWrites = false;
      stdinA.write = function interceptedWrite(chunk, encoding, callback) {
        if (interceptWrites) {
          if (typeof callback === 'function') callback(new Error('simulated-write-failure'));
          return true;
        }
        return originalWrite(chunk, encoding, callback);
      };

      interceptWrites = true;
      await new Promise((resolve) => rbc.writeJsonlFrame(stdoutA, { id: 'block-a-writeerror-refresh-1', method: 'account/chatgptAuthTokens/refresh', params: { reason: 'unauthorized' } }, resolve));

      const stopped = await waitUntil(() => connectionA.isStopped());
      assert.strictEqual(stopped, true, 'test precondition: a failed wire flush must genuinely stop the connection: ' + JSON.stringify({ phase: connectionA.connectionPhase(), reason: connectionA.stopReason() }));
      assert.ok(String(connectionA.stopReason()).includes('refresh-reply-write-failed'), 'test precondition: the stop must be attributed to the simulated write failure specifically, not some other cause: ' + connectionA.stopReason());

      const outcomeB = bindingB.refreshProvider({});
      assert.strictEqual(outcomeB.ok, true, 'a credential that was never actually confirmed flushed to C2 (the wire write itself failed) must never be committed broker-side -- connection B\'s own unrelated, legitimate refresh must succeed cleanly: ' + JSON.stringify(outcomeB));
      assert.strictEqual(outcomeB.chatgptAccountId, DIFFERENT_LEGITIMATE_ACCOUNT, JSON.stringify(outcomeB));
    } finally {
      cleanupDir(tmp);
    }
  });

  test('PROOF: an unrelated STOP (a malformed frame arriving on the SAME connection) while the credential SETTLEMENT itself is genuinely still pending (the listener has already been invoked; its returned promise has not yet resolved) aborts that settlement exactly once -- the broker-side lock/account are never left stuck pending forever just because the connection that would have confirmed them is now gone', async (t) => {
    // Mocks setTimeout so the refresh reply's own flushTimer (10s,
    // DEFAULT_RPC_TIMEOUT_MS) never becomes a REAL, lingering OS timer --
    // the intercepted write below never invokes its own callback, so
    // clearTimeout(flushTimer) is never reached; without mocking, this timer
    // would still fire naturally ~10 real seconds later (harmlessly, per its
    // own activeRefreshEpoch guard) but would keep the test PROCESS alive
    // that whole time before it could fully exit.
    t.mock.timers.enable({ apis: ['setTimeout'] });
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-block-a-stop-mid-settlement-'));
    const fixture = makeSealedIsolationFixture(tmp);
    const LOGIN_ACCOUNT = 'acct-block-a-stopmid-login';
    const DIFFERENT_LEGITIMATE_ACCOUNT = 'acct-block-a-stopmid-unrelated';
    try {
      let sourceReadCallCount = 0;
      const deps = validAuthoritiesDeps(fixture, {
        expectedRoster: [{ role: 'verifier', ordinal: 0 }, { role: 'verifier', ordinal: 1 }],
        sourceProvider: {
          read: () => {
            sourceReadCallCount += 1;
            // Call #1 (A): resolves IMMEDIATELY (synchronously) with a
            // genuinely valid, matching-login credential -- shape/identity/
            // replay all pass, so finishRefreshResult reaches the flush-write
            // stage and the broker's own listener has ALREADY been invoked
            // (pendingCredentialSettlement genuinely exists) by the time this
            // test sends the unrelated malformed frame below. This is
            // deliberately DIFFERENT from a hung/never-resolving source read
            // (covered by the close()/hung-source test above) -- here the
            // READ itself is not the problem; the WIRE FLUSH is what never
            // confirms, because the connection dies for an unrelated reason
            // before it can.
            return { ok: true, credentials: { accessToken: syntheticSecret('block-a-stopmid-' + sourceReadCallCount), chatgptAccountId: sourceReadCallCount === 1 ? LOGIN_ACCOUNT : DIFFERENT_LEGITIMATE_ACCOUNT, chatgptPlanType: 'plus' }, otherCredentialFields: {}, expiresAt: futureIso(400 * 1000), sourceIdentity: 'block-a-stopmid-fixture' };
          },
        },
      });
      const authorities = rbc.createRunAuthorities(deps);
      const bindingA = authorities.bindConnection({ role: 'verifier', ordinal: 0 });
      const bindingB = authorities.bindConnection({ role: 'verifier', ordinal: 1 });
      assert.strictEqual(typeof bindingA.reason, 'undefined', JSON.stringify(bindingA));
      assert.strictEqual(typeof bindingB.reason, 'undefined', JSON.stringify(bindingB));

      const { connection: connectionA, stdin: stdinA, stdout: stdoutA } = await createAuthenticatedConnection(bindingA, LOGIN_ACCOUNT);

      // Intercept writes AFTER login: silently swallow the refresh reply
      // write (never invoke its own flush callback) -- the settlement stays
      // genuinely pending (neither confirmed nor failed) until something
      // else resolves it. Here, that "something else" is the unrelated STOP
      // below, not the flush timeout (covered by its own dedicated test).
      const originalWrite = stdinA.write.bind(stdinA);
      let interceptWrites = false;
      stdinA.write = function interceptedWrite(chunk, encoding, callback) {
        if (interceptWrites) {
          void callback; // deliberately never invoked.
          return true;
        }
        return originalWrite(chunk, encoding, callback);
      };

      interceptWrites = true;
      await new Promise((resolve) => rbc.writeJsonlFrame(stdoutA, { id: 'block-a-stopmid-refresh-1', method: 'account/chatgptAuthTokens/refresh', params: { reason: 'unauthorized' } }, resolve));
      await new Promise((resolve) => setImmediate(resolve));
      assert.strictEqual(connectionA.isStopped(), false, 'test precondition: the connection must still be live -- the settlement is genuinely still pending (write intercepted, flush never confirmed, timeout not yet elapsed)');

      // An UNRELATED STOP trigger -- a malformed frame -- arrives on this
      // SAME connection while the refresh's own settlement is still pending.
      await new Promise((resolve) => stdoutA.write('not valid json {{{\n', 'utf8', resolve));
      const stopped = await waitUntil(() => connectionA.isStopped());
      assert.strictEqual(stopped, true, 'test precondition: the malformed frame must genuinely stop the connection: ' + JSON.stringify({ phase: connectionA.connectionPhase(), reason: connectionA.stopReason() }));

      const outcomeB = bindingB.refreshProvider({});
      assert.strictEqual(outcomeB.ok, true, 'a settlement whose OWN connection stopped for an unrelated reason while genuinely still pending must be aborted (never left stuck, never committed) -- connection B\'s own unrelated refresh must succeed cleanly: ' + JSON.stringify(outcomeB));
      assert.strictEqual(outcomeB.chatgptAccountId, DIFFERENT_LEGITIMATE_ACCOUNT, JSON.stringify(outcomeB));
    } finally {
      cleanupDir(tmp);
    }
  });

  // A DISTINCT, narrower scenario from the one above: here the SOURCE READ
  // itself never resolves (the listener is therefore never even invoked --
  // pendingCredentialSettlement never gets created at all), and the
  // connection then stops involuntarily (a malformed frame), never via an
  // explicit close() call, BEFORE the hung read finally resolves late. This
  // test originally caught a real, second gap in the fix: finalizeStop's own
  // abort hook (settlePendingCredentialOutcome) only aborts a settlement
  // that ALREADY EXISTS at stop time -- it was a no-op here, since the
  // listener had not been invoked yet. When the hung read later resolved,
  // the credentialBinding listener was invoked for the FIRST time on an
  // ALREADY-STOPPED connection with no isTerminal() guard, creating a fresh
  // pendingCredentialSettlement nothing would ever settle -- toolkit-
  // specialist fixed this by having the listener itself check isTerminal()
  // and reject immediately if the connection is already stopped by the time
  // it is invoked (runtime-bridge-codex.cjs:~1617-1631).
  test('FIX (confirmed correct once toolkit-specialist\'s isTerminal()-guard fix landed): the credentialBinding listener rejects immediately (never creates a stuck pending settlement) when invoked on an ALREADY-STOPPED connection -- covers a hung source read that only resolves AFTER an unrelated, involuntary STOP (a malformed frame, never an explicit close()) already tore the connection down', async () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-block-a-stop-hung-source-'));
    const fixture = makeSealedIsolationFixture(tmp);
    const LOGIN_ACCOUNT = 'acct-block-a-stophung-login';
    const DIFFERENT_LEGITIMATE_ACCOUNT = 'acct-block-a-stophung-unrelated';
    try {
      let sourceReadCallCount = 0;
      let resolveHangingRead = null;
      const deps = validAuthoritiesDeps(fixture, {
        expectedRoster: [{ role: 'verifier', ordinal: 0 }, { role: 'verifier', ordinal: 1 }],
        sourceProvider: {
          read: () => {
            sourceReadCallCount += 1;
            if (sourceReadCallCount === 1) {
              return new Promise((resolve) => { resolveHangingRead = resolve; });
            }
            return { ok: true, credentials: { accessToken: syntheticSecret('block-a-stophung-' + sourceReadCallCount), chatgptAccountId: DIFFERENT_LEGITIMATE_ACCOUNT, chatgptPlanType: 'plus' }, otherCredentialFields: {}, expiresAt: futureIso(400 * 1000), sourceIdentity: 'block-a-stophung-fixture' };
          },
        },
      });
      const authorities = rbc.createRunAuthorities(deps);
      const bindingA = authorities.bindConnection({ role: 'verifier', ordinal: 0 });
      const bindingB = authorities.bindConnection({ role: 'verifier', ordinal: 1 });
      assert.strictEqual(typeof bindingA.reason, 'undefined', JSON.stringify(bindingA));
      assert.strictEqual(typeof bindingB.reason, 'undefined', JSON.stringify(bindingB));

      const { connection: connectionA, stdout: stdoutA } = await createAuthenticatedConnection(bindingA, LOGIN_ACCOUNT);

      await new Promise((resolve) => rbc.writeJsonlFrame(stdoutA, { id: 'block-a-stophung-refresh-1', method: 'account/chatgptAuthTokens/refresh', params: { reason: 'unauthorized' } }, resolve));
      await new Promise((resolve) => setImmediate(resolve));
      assert.strictEqual(connectionA.isStopped(), false, 'test precondition: the connection must still be live while the source read is genuinely still hung');
      assert.ok(resolveHangingRead, 'test precondition: the source read must genuinely be suspended at this point');

      await new Promise((resolve) => stdoutA.write('not valid json {{{\n', 'utf8', resolve));
      const stopped = await waitUntil(() => connectionA.isStopped());
      assert.strictEqual(stopped, true, 'test precondition: the malformed frame must genuinely stop the connection: ' + JSON.stringify({ phase: connectionA.connectionPhase(), reason: connectionA.stopReason() }));

      resolveHangingRead({ ok: true, credentials: { accessToken: syntheticSecret('block-a-stophung-late'), chatgptAccountId: LOGIN_ACCOUNT, chatgptPlanType: 'plus' }, otherCredentialFields: {}, expiresAt: futureIso(400 * 1000), sourceIdentity: 'block-a-stophung-fixture' });
      await new Promise((resolve) => setImmediate(resolve));
      await new Promise((resolve) => setImmediate(resolve));

      const outcomeB = bindingB.refreshProvider({});
      assert.strictEqual(outcomeB.ok, true, 'a credential arriving on an already-STOPPED connection (the source read only resolved AFTER an unrelated malformed frame tore the connection down) must never be committed broker-side -- without the isTerminal() guard, the listener returns undefined (passive), which falls to the unconditional commitNow() branch and wrongly commits this late-arriving, never-confirmed credential; connection B\'s own unrelated, legitimate refresh must succeed cleanly: ' + JSON.stringify(outcomeB));
      assert.strictEqual(outcomeB.chatgptAccountId, DIFFERENT_LEGITIMATE_ACCOUNT, JSON.stringify(outcomeB));
    } finally {
      cleanupDir(tmp);
    }
  });

  test('FIX (confirmed correct once toolkit-specialist\'s fix landed -- mutation-revert verified alongside the settlement-pending-STOP and hung-source-STOP tests in the same cycle): a refresh reply whose flush is NEVER confirmed (the stdin write\'s own callback never fires) times out after DEFAULT_RPC_TIMEOUT_MS and is treated as an abort, never a commit -- uses node:test\'s mock timers rather than a real 10-second wait', async (t) => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-block-a-timeout-'));
    const fixture = makeSealedIsolationFixture(tmp);
    const LOGIN_ACCOUNT = 'acct-block-a-timeout-login';
    const DIFFERENT_LEGITIMATE_ACCOUNT = 'acct-block-a-timeout-unrelated';
    try {
      let sourceReadCallCount = 0;
      const deps = validAuthoritiesDeps(fixture, {
        expectedRoster: [{ role: 'verifier', ordinal: 0 }, { role: 'verifier', ordinal: 1 }],
        sourceProvider: {
          read: () => {
            sourceReadCallCount += 1;
            const accountId = sourceReadCallCount === 1 ? LOGIN_ACCOUNT : DIFFERENT_LEGITIMATE_ACCOUNT;
            return { ok: true, credentials: { accessToken: syntheticSecret('block-a-timeout-' + sourceReadCallCount), chatgptAccountId: accountId, chatgptPlanType: 'plus' }, otherCredentialFields: {}, expiresAt: futureIso(400 * 1000), sourceIdentity: 'block-a-timeout-fixture' };
          },
        },
      });
      const authorities = rbc.createRunAuthorities(deps);
      const bindingA = authorities.bindConnection({ role: 'verifier', ordinal: 0 });
      const bindingB = authorities.bindConnection({ role: 'verifier', ordinal: 1 });
      assert.strictEqual(typeof bindingA.reason, 'undefined', JSON.stringify(bindingA));
      assert.strictEqual(typeof bindingB.reason, 'undefined', JSON.stringify(bindingB));

      // Real timers for the login handshake -- only the refresh reply's own
      // flush confirmation needs to be mocked/stuck.
      const { connection: connectionA, stdin: stdinA, stdout: stdoutA } = await createAuthenticatedConnection(bindingA, LOGIN_ACCOUNT);

      // Intercept writes AFTER login: silently swallow the refresh reply
      // write -- never invoke its own flush callback at all (neither success
      // nor failure), so the ONLY way this attempt can ever settle is via
      // the flush timeout itself.
      const originalWrite = stdinA.write.bind(stdinA);
      let interceptWrites = false;
      stdinA.write = function interceptedWrite(chunk, encoding, callback) {
        if (interceptWrites) {
          void callback; // deliberately never invoked -- the write is permanently unconfirmed.
          return true;
        }
        return originalWrite(chunk, encoding, callback);
      };

      t.mock.timers.enable({ apis: ['setTimeout'] });
      interceptWrites = true;
      await new Promise((resolve) => rbc.writeJsonlFrame(stdoutA, { id: 'block-a-timeout-refresh-1', method: 'account/chatgptAuthTokens/refresh', params: { reason: 'unauthorized' } }, resolve));
      await new Promise((resolve) => setImmediate(resolve));
      assert.strictEqual(connectionA.isStopped(), false, 'test precondition: the connection must still be live -- the flush is genuinely stuck, not yet timed out');

      t.mock.timers.tick(10000); // DEFAULT_RPC_TIMEOUT_MS
      await new Promise((resolve) => setImmediate(resolve));

      assert.strictEqual(connectionA.isStopped(), true, 'test precondition: the flush timeout must genuinely fire and stop the connection once DEFAULT_RPC_TIMEOUT_MS elapses: ' + JSON.stringify({ phase: connectionA.connectionPhase(), reason: connectionA.stopReason() }));
      assert.ok(String(connectionA.stopReason()).includes('refresh-reply-flush-timeout'), 'test precondition: the stop must be attributed to the flush timeout specifically: ' + connectionA.stopReason());

      const outcomeB = bindingB.refreshProvider({});
      assert.strictEqual(outcomeB.ok, true, 'a credential whose flush confirmation timed out (never confirmed delivered to C2) must never be committed broker-side -- connection B\'s own unrelated, legitimate refresh must succeed cleanly: ' + JSON.stringify(outcomeB));
      assert.strictEqual(outcomeB.chatgptAccountId, DIFFERENT_LEGITIMATE_ACCOUNT, JSON.stringify(outcomeB));
    } finally {
      cleanupDir(tmp);
    }
  });
});

// ══════════════════════════════════════════════════════════════════════════
// CORRECTION ROUND -- Item A: lastCredentialRefreshOutcome() public accessor
// redacted (secret-token leak fix). toolkit-specialist removed the public
// `lastCredentialRefreshOutcome: () => lastCredentialRefreshOutcome` accessor
// from createAppServerConnection's own returned surface (it leaked the raw,
// committed accessToken -- and the complete credential object -- to any
// caller) and replaced it with a redacted, test-capability-gated
// introspection function, `rbc.__testOnlyInspectCredentialRefreshOutcome
// (connection)`, mirroring the established __testOnlyInspectFinalizationState
// convention: undefined for a foreign/unrecognized object, null if no
// outcome has been observed yet, or {committed,reason,observedAt} (no
// accessToken/chatgptAccountId/chatgptPlanType/outcome field at all) once
// one has. The test below is the structural regression this fix requires.
// ══════════════════════════════════════════════════════════════════════════

describe('CORRECTION ROUND -- Item A: lastCredentialRefreshOutcome() public accessor redacted', () => {
  // Local copy -- the sibling Block A describe block's own waitUntil is not
  // in scope from this describe block.
  async function waitUntil(predicate, maxIterations) {
    for (let i = 0; i < (maxIterations || 50); i++) {
      if (predicate()) return true;
      await new Promise((resolve) => setImmediate(resolve));
    }
    return predicate();
  }

  // Local copy -- the sibling Block A/Block B Group 1 describe blocks' own
  // createAuthenticatedConnection is not in scope from this describe block.
  async function createAuthenticatedConnection(binding, accountId) {
    const stdin = new PassThrough();
    const stdout = new PassThrough();
    const connection = rbc.createAppServerConnection({ stdin, stdout, refreshProvider: binding.refreshProvider, credentialBinding: binding });
    const capturedIds = {};
    stdin.on('data', (chunk) => {
      for (const line of chunk.toString('utf8').split('\n')) {
        if (!line.trim()) continue;
        try { const frame = JSON.parse(line); if (frame.method) capturedIds[frame.method] = frame.id; } catch (err) { /* partial chunk fragment */ }
      }
    });
    const initPromise = connection.initialize();
    await new Promise((resolve) => setImmediate(resolve));
    await new Promise((resolve) => rbc.writeJsonlFrame(stdout, { id: capturedIds['initialize'], result: { codexHome: '/fake', platformFamily: 'unix', platformOs: 'macos', userAgent: 'fake' } }, resolve));
    const initResult = await initPromise;
    if (!initResult.ok) throw new Error('createAuthenticatedConnection precondition (initialize) failed: ' + JSON.stringify(initResult));

    const loginPromise = connection.login({ accessToken: 'fake-login-token-' + accountId, chatgptAccountId: accountId, chatgptPlanType: 'plus' });
    await new Promise((resolve) => setImmediate(resolve));
    await new Promise((resolve) => rbc.writeJsonlFrame(stdout, { id: capturedIds['account/login/start'], result: { type: 'chatgptAuthTokens', accessToken: 'fake-login-token-' + accountId, chatgptAccountId: accountId, chatgptPlanType: 'plus' } }, resolve));
    await new Promise((resolve) => rbc.writeJsonlFrame(stdout, { method: 'account/updated', params: { authMode: 'chatgptAuthTokens', planType: 'plus' } }, resolve));
    const loginResult = await loginPromise;
    if (!loginResult.ok) throw new Error('createAuthenticatedConnection precondition (login) failed: ' + JSON.stringify(loginResult));

    return { connection, stdin, stdout };
  }

  test('FIX: lastCredentialRefreshOutcome is structurally absent from createAppServerConnection\'s own public surface, no zero-arg public member can be made to reveal the committed accessToken, and the redacted __testOnlyInspectCredentialRefreshOutcome introspection hook reports only {committed,reason,observedAt} -- structural regression proving the public production surface cannot reveal the token or complete credential object', async () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-itema-redact-'));
    const fixture = makeSealedIsolationFixture(tmp);
    const LOGIN_ACCOUNT = 'acct-itema-redact';
    const KNOWN_SECRET = syntheticSecret('itema-redact-accesstoken');
    try {
      const deps = validAuthoritiesDeps(fixture, {
        expectedRoster: [{ role: 'verifier', ordinal: 0 }],
        sourceProvider: {
          read: () => ({ ok: true, credentials: { accessToken: KNOWN_SECRET, chatgptAccountId: LOGIN_ACCOUNT, chatgptPlanType: 'plus' }, otherCredentialFields: {}, expiresAt: futureIso(400 * 1000), sourceIdentity: 'itema-redact-fixture' }),
        },
      });
      const authorities = rbc.createRunAuthorities(deps);
      const binding = authorities.bindConnection({ role: 'verifier', ordinal: 0 });
      assert.strictEqual(typeof binding.reason, 'undefined', JSON.stringify(binding));

      const { connection, stdout } = await createAuthenticatedConnection(binding, LOGIN_ACCOUNT);

      // Drive a REAL, successful refresh over the wire (matching login's own
      // account, so C2's own identity check passes) so a credential is
      // genuinely committed via credentialBinding's real settlement wiring,
      // never merely a direct, unconfirmed refreshProvider() call.
      await new Promise((resolve) => rbc.writeJsonlFrame(stdout, { id: 'itema-redact-refresh-1', method: 'account/chatgptAuthTokens/refresh', params: { reason: 'unauthorized' } }, resolve));
      await new Promise((resolve) => setImmediate(resolve));
      await new Promise((resolve) => setImmediate(resolve));
      await new Promise((resolve) => setImmediate(resolve));
      assert.strictEqual(connection.isStopped(), false, 'test precondition: the refresh must genuinely succeed, keeping the connection alive: ' + JSON.stringify({ phase: connection.connectionPhase(), reason: connection.stopReason() }));
      assert.strictEqual(connection.connectionPhase(), 'AUTHENTICATED', 'test precondition: ' + connection.connectionPhase());

      // 1. The key must be structurally absent from the connection's own
      // public surface, not merely unhelpful.
      const ownKeys = Object.keys(connection);
      assert.ok(!ownKeys.includes('lastCredentialRefreshOutcome'), 'the connection\'s own public surface must not expose a lastCredentialRefreshOutcome key at all: ' + JSON.stringify(ownKeys));

      // 2. Walk the ENTIRE public surface -- call every zero-required-arg
      // function member and assert none of the returned values, once
      // JSON.stringify'd, contain the known synthetic secret.
      for (const key of ownKeys) {
        const member = connection[key];
        if (typeof member !== 'function' || member.length !== 0) continue;
        let value;
        try {
          value = member();
        } catch (err) {
          continue; // a member that throws with no args reveals nothing.
        }
        const serialized = JSON.stringify(value);
        if (typeof serialized !== 'string') continue;
        assert.ok(!serialized.includes(KNOWN_SECRET), 'public zero-arg member "' + key + '" must never reveal the known synthetic accessToken: ' + serialized);
      }

      // 3. The redacted, test-capability-gated introspection function must
      // exist (only true because NODE_ENV=test + RUNTIME_BRIDGE_CODEX_TEST_CAPABILITY
      // are set for this whole suite, matching the established
      // __testOnlyInspectFinalizationState convention).
      assert.strictEqual(typeof rbc.__testOnlyInspectCredentialRefreshOutcome, 'function', '__testOnlyInspectCredentialRefreshOutcome must exist as a real, shipped, test-capability-gated export');

      // 4. Calling it after the successful refresh returns the redacted
      // shape, with no outcome/accessToken/chatgptAccountId/chatgptPlanType
      // key anywhere, and no occurrence of the known secret.
      const inspected = rbc.__testOnlyInspectCredentialRefreshOutcome(connection);
      assert.ok(inspected, 'test precondition: an outcome must genuinely have been observed by this point: ' + JSON.stringify(inspected));
      assert.strictEqual(inspected.committed, true, JSON.stringify(inspected));
      // On a successfully COMMITTED refresh, reason is undefined -- this
      // file's own established convention (an {ok:true}-shaped result never
      // carries a meaningful reason, e.g. bindConnection's own successful-
      // bind shape) means only a failed/aborted outcome carries a string
      // reason; verified directly against runRefreshCheckpointOrder's own
      // finishHoldingLock success return (no .reason field at all on
      // {ok:true,...}), which flows verbatim through settleAndReturn's
      // outcomeListener(flatOutcome, flatOutcome.reason) call.
      assert.strictEqual(typeof inspected.reason, 'undefined', JSON.stringify(inspected));
      assert.strictEqual(typeof inspected.observedAt, 'string', JSON.stringify(inspected));
      assert.ok(Number.isFinite(Date.parse(inspected.observedAt)), 'observedAt must be a valid ISO-8601 timestamp: ' + JSON.stringify(inspected));
      assert.deepStrictEqual(Object.keys(inspected).sort(), ['committed', 'observedAt', 'reason'], 'the redacted shape must carry EXACTLY {committed,reason,observedAt} -- no outcome/accessToken/chatgptAccountId/chatgptPlanType key anywhere: ' + JSON.stringify(inspected));
      assert.ok(!JSON.stringify(inspected).includes(KNOWN_SECRET), 'the redacted introspection result must never contain the known synthetic secret: ' + JSON.stringify(inspected));

      // 5. A foreign, unrelated object returns undefined.
      assert.strictEqual(rbc.__testOnlyInspectCredentialRefreshOutcome({}), undefined, 'a foreign, unrecognized object must yield undefined, never throw or return a stale/default shape');
    } finally {
      cleanupDir(tmp);
    }
  });

  test('CONFIRMATION: on a GENUINELY ABORTED refresh (the broker\'s own pre-checks -- margin, and account-mismatch against hostWideBoundAccountId, which is still null on this FIRST refresh -- pass cleanly, but C2\'s own identity check against the login\'s own account LATER rejects it, so hostWideBoundAccountId is never actually committed) __testOnlyInspectCredentialRefreshOutcome reports committed:false and a genuine, non-empty string reason -- proves "committed" tracks the FINAL settlement outcome, not merely that the broker\'s own pre-checks happened to pass; companion to the FIX test above, which only exercised the success branch', async () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-itema-redact-aborted-'));
    const fixture = makeSealedIsolationFixture(tmp);
    const LOGIN_ACCOUNT = 'acct-itema-redact-aborted-login';
    const MISMATCHED_REFRESH_ACCOUNT = 'acct-itema-redact-aborted-mismatched';
    try {
      const deps = validAuthoritiesDeps(fixture, {
        expectedRoster: [{ role: 'verifier', ordinal: 0 }],
        sourceProvider: {
          read: () => ({ ok: true, credentials: { accessToken: syntheticSecret('itema-redact-aborted'), chatgptAccountId: MISMATCHED_REFRESH_ACCOUNT, chatgptPlanType: 'plus' }, otherCredentialFields: {}, expiresAt: futureIso(400 * 1000), sourceIdentity: 'itema-redact-aborted-fixture' }),
        },
      });
      const authorities = rbc.createRunAuthorities(deps);
      const binding = authorities.bindConnection({ role: 'verifier', ordinal: 0 });
      assert.strictEqual(typeof binding.reason, 'undefined', JSON.stringify(binding));

      const { connection, stdout } = await createAuthenticatedConnection(binding, LOGIN_ACCOUNT);

      await new Promise((resolve) => rbc.writeJsonlFrame(stdout, { id: 'itema-redact-aborted-refresh-1', method: 'account/chatgptAuthTokens/refresh', params: { reason: 'unauthorized' } }, resolve));
      const stopped = await waitUntil(() => connection.isStopped());
      assert.strictEqual(stopped, true, 'test precondition: C2\'s own identity check must genuinely reject the mismatched-account refresh and stop the connection: ' + JSON.stringify({ phase: connection.connectionPhase(), reason: connection.stopReason() }));

      const inspected = rbc.__testOnlyInspectCredentialRefreshOutcome(connection);
      assert.ok(inspected, 'test precondition: an outcome must genuinely have been observed: ' + JSON.stringify(inspected));
      assert.strictEqual(inspected.committed, false, '"committed" must reflect the FINAL settlement outcome (never confirmed by C2, so never committed to hostWideBoundAccountId), not merely that the broker\'s own pre-checks (margin, pre-existing-account-conflict) happened to pass: ' + JSON.stringify(inspected));
      assert.strictEqual(typeof inspected.reason, 'string', 'an ABORTED outcome must carry a genuine, non-empty string reason: ' + JSON.stringify(inspected));
      assert.ok(inspected.reason.length > 0, JSON.stringify(inspected));
      assert.ok(!JSON.stringify(inspected).includes(MISMATCHED_REFRESH_ACCOUNT), 'the redacted introspection result must never contain the account id involved in this attempt: ' + JSON.stringify(inspected));
    } finally {
      cleanupDir(tmp);
    }
  });
});

// ══════════════════════════════════════════════════════════════════════════
// CORRECTION ROUND -- Block B Group 1: durable evidence and finalization.
// team-lead-approved scope (toolkit-specialist's design, not yet
// implemented): (1) checkpointAuthority.hadWriteFailure() getter exposing
// the existing in-memory checkpointState.everHadWriteFailure; (2) a
// best-effort durable marker file on write failure, defense-in-depth;
// (3) a new unconditional-first gate in publishAndFinalize, right after the
// existing isPoisoned() check, returning {state:'PUBLICATION_INVALID',
// reason:'CHECKPOINT_WRITE_FAILURE_RECORDED'} permanently once either signal
// is set; (4) close() reports its own checkpoint-write failure honestly
// ({ok:false,reason}) while still unconditionally releasing the lease.
//
// Standing decision (team-lead, not relitigated here): a checkpoint-write
// failure during an in-flight REFRESH does not change that refresh's own
// success/failure signal to C2 -- it only feeds the new permanence gate.
// close() is different (no credential-validity concern there) and reports
// its own failure honestly.
//
// Fault injection: NO new seam needed -- confirmed empirically this round
// that chmod-ing the real checkpoint directory
// (`${registryRepoDir}/credential-absence-checkpoints/`) to 0o500
// (read+execute, no write) immediately before a checkpoint write attempt
// produces a genuine CHECKPOINT_WRITE_FAILED through the real fd-bound
// write path -- no mock, no injected fault flag. Every test below restores
// 0o700 before its own cleanup so temp-dir removal still succeeds.
// ══════════════════════════════════════════════════════════════════════════

describe('CORRECTION ROUND -- Block B Group 1: durable evidence permanence (checkpoint-write-failure gate)', () => {
  function checkpointDirFor(repoId) {
    return path.join(rll.registryRepoDir({ repoId }), 'credential-absence-checkpoints');
  }
  function checkpointFileFor(repoId, runId) {
    return path.join(checkpointDirFor(repoId), runId + '.json');
  }

  // Local copy -- the Block A describe block's own createAuthenticatedConnection
  // is not in scope from this sibling describe block.
  async function createAuthenticatedConnection(binding, accountId) {
    const stdin = new PassThrough();
    const stdout = new PassThrough();
    const connection = rbc.createAppServerConnection({ stdin, stdout, refreshProvider: binding.refreshProvider, credentialBinding: binding });
    const capturedIds = {};
    stdin.on('data', (chunk) => {
      for (const line of chunk.toString('utf8').split('\n')) {
        if (!line.trim()) continue;
        try { const frame = JSON.parse(line); if (frame.method) capturedIds[frame.method] = frame.id; } catch (err) { /* partial chunk fragment */ }
      }
    });
    const initPromise = connection.initialize();
    await new Promise((resolve) => setImmediate(resolve));
    await new Promise((resolve) => rbc.writeJsonlFrame(stdout, { id: capturedIds['initialize'], result: { codexHome: '/fake', platformFamily: 'unix', platformOs: 'macos', userAgent: 'fake' } }, resolve));
    const initResult = await initPromise;
    if (!initResult.ok) throw new Error('createAuthenticatedConnection precondition (initialize) failed: ' + JSON.stringify(initResult));
    const loginPromise = connection.login({ accessToken: 'fake-login-token-' + accountId, chatgptAccountId: accountId, chatgptPlanType: 'plus' });
    await new Promise((resolve) => setImmediate(resolve));
    await new Promise((resolve) => rbc.writeJsonlFrame(stdout, { id: capturedIds['account/login/start'], result: { type: 'chatgptAuthTokens', accessToken: 'fake-login-token-' + accountId, chatgptAccountId: accountId, chatgptPlanType: 'plus' } }, resolve));
    await new Promise((resolve) => rbc.writeJsonlFrame(stdout, { method: 'account/updated', params: { authMode: 'chatgptAuthTokens', planType: 'plus' } }, resolve));
    const loginResult = await loginPromise;
    if (!loginResult.ok) throw new Error('createAuthenticatedConnection precondition (login) failed: ' + JSON.stringify(loginResult));
    return { connection, stdin, stdout };
  }

  test('FIX (confirmed correct once toolkit-specialist\'s Group 1 fix landed; mutation-revert verified both directly by me and independently by toolkit-specialist): once a checkpoint write genuinely fails, publishAndFinalize() returns PUBLICATION_INVALID/CHECKPOINT_WRITE_FAILURE_RECORDED on EVERY subsequent call, regardless of what the checkpoints array structurally looks like afterward -- previously it wrongly reached PUBLISHED_VALID then FINALIZED once a later, structurally-complete record landed on disk', async () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-block-b-permanence-'));
    const fixture = makeSealedIsolationFixture(tmp);
    try {
      const fakePub = makeFakePublisher(['PUBLISHED'], [true]);
      const authorities = rbc.createRunAuthorities(validAuthoritiesDeps(fixture, { publisherFactory: fakePub.publisherFactory, expectedRoster: [{ role: 'verifier', ordinal: 0 }] }));
      const bound = authorities.bindConnection({ role: 'verifier', ordinal: 0 });
      assert.strictEqual(typeof bound.reason, 'undefined', JSON.stringify(bound));

      const checkpointDir = checkpointDirFor(fixture.repoId);
      fs.chmodSync(checkpointDir, 0o500);
      const failedCheckpoint = bound.checkout().recordLogin('pre');
      fs.chmodSync(checkpointDir, 0o700); // restore -- FUTURE writes succeed structurally; the failure must remain permanent regardless.
      assert.strictEqual(failedCheckpoint.ok, false, 'test precondition: the checkpoint write must genuinely fail while the directory is read-only: ' + JSON.stringify(failedCheckpoint));
      assert.strictEqual(failedCheckpoint.reason, 'CHECKPOINT_WRITE_FAILED', JSON.stringify(failedCheckpoint));

      bound.close();

      // Fabricate a STRUCTURALLY-COMPLETE checkpoint record directly on
      // disk, overwriting whatever partial state exists -- proves the
      // permanence gate must hold regardless of what the checkpoints array
      // looks like afterward, not merely "while it still looks incomplete".
      // Explicit mode:0o600 -- matches the real production writer exactly, so
      // the fd-bound reader's exact-mode check never rejects this fabrication.
      fs.writeFileSync(checkpointFileFor(fixture.repoId, fixture.runId), JSON.stringify({
        schema: 'coordination/credential-absence-checkpoints/v1', run_id: fixture.runId, mode: 'app-server', root_ids: [],
        checkpoints: [
          { name: 'login:pre@verifier:0', ok: true }, { name: 'login:post@verifier:0', ok: true },
          { name: 'turn:pre@verifier:0', ok: true }, { name: 'turn:during@verifier:0', ok: true }, { name: 'turn:post@verifier:0', ok: true },
          { name: 'cleanup:pre@verifier:0', ok: true }, { name: 'cleanup:post@verifier:0', ok: true },
        ],
        complete: true,
      }), { mode: 0o600 });

      const first = await authorities.publishAndFinalize();
      assert.strictEqual(first.state, 'PUBLICATION_INVALID', 'a checkpoint write failure recorded earlier in this run must permanently block finalization, even once a later, structurally-complete checkpoint record is on disk: ' + JSON.stringify(first));
      assert.strictEqual(first.reason, 'CHECKPOINT_WRITE_FAILURE_RECORDED', JSON.stringify(first));

      const second = await authorities.publishAndFinalize();
      assert.strictEqual(second.state, 'PUBLICATION_INVALID', 'the permanence gate must hold on EVERY subsequent call, never just the first: ' + JSON.stringify(second));
      assert.strictEqual(second.reason, 'CHECKPOINT_WRITE_FAILURE_RECORDED', JSON.stringify(second));
    } finally {
      cleanupDir(tmp);
    }
  });

  test('CONFIRMATION (already correct today per direct verification -- kept as a regression guard for Block B Group 1, not a RED test): a checkpoint write failure at the "post" phase of an OTHERWISE-VALID, already-confirmed-flushed refresh does NOT change that refresh\'s own success signal to C2 -- the connection stays healthy and the credential remains usable, matching the standing decision that credential validity and checkpoint durability are independent concerns', async () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-block-b-post-healthy-'));
    const fixture = makeSealedIsolationFixture(tmp);
    const LOGIN_ACCOUNT = 'acct-block-b-post-login';
    try {
      let resolveHangingRead = null;
      const deps = validAuthoritiesDeps(fixture, {
        expectedRoster: [{ role: 'verifier', ordinal: 0 }],
        // Deliberately async and controllable -- lets pre/during checkpoints
        // fire (and succeed, directory still writable) BEFORE the checkpoint
        // directory is made read-only, isolating the failure to 'post' alone.
        sourceProvider: { read: () => new Promise((resolve) => { resolveHangingRead = resolve; }) },
      });
      const authorities = rbc.createRunAuthorities(deps);
      const bound = authorities.bindConnection({ role: 'verifier', ordinal: 0 });
      assert.strictEqual(typeof bound.reason, 'undefined', JSON.stringify(bound));

      const { connection, stdout } = await createAuthenticatedConnection(bound, LOGIN_ACCOUNT);

      await new Promise((resolve) => rbc.writeJsonlFrame(stdout, { id: 'block-b-post-refresh-1', method: 'account/chatgptAuthTokens/refresh', params: { reason: 'unauthorized' } }, resolve));
      await new Promise((resolve) => setImmediate(resolve));
      assert.strictEqual(connection.isStopped(), false, 'test precondition: connection must still be live -- source read (and therefore settlement) genuinely still pending');
      assert.ok(resolveHangingRead, 'test precondition: the source read must genuinely be suspended -- pre/during checkpoints have already fired successfully at this point');

      const checkpointDir = checkpointDirFor(fixture.repoId);
      fs.chmodSync(checkpointDir, 0o500);
      resolveHangingRead({ ok: true, credentials: { accessToken: syntheticSecret('block-b-post'), chatgptAccountId: LOGIN_ACCOUNT, chatgptPlanType: 'plus' }, otherCredentialFields: {}, expiresAt: futureIso(400 * 1000), sourceIdentity: 'block-b-post-fixture' });
      await new Promise((resolve) => setImmediate(resolve));
      await new Promise((resolve) => setImmediate(resolve));
      await new Promise((resolve) => setImmediate(resolve));
      fs.chmodSync(checkpointDir, 0o700);

      assert.strictEqual(connection.isStopped(), false, 'a checkpoint write failure at the "post" phase must never retroactively stop an already-confirmed-flushed refresh: ' + JSON.stringify({ phase: connection.connectionPhase(), reason: connection.stopReason() }));
      assert.strictEqual(connection.connectionPhase(), 'AUTHENTICATED', 'the connection must remain fully operative, not merely "not yet torn down": ' + connection.connectionPhase());
    } finally {
      cleanupDir(tmp);
    }
  });

  test('FIX (confirmed correct once toolkit-specialist\'s Group 1 fix landed; mutation-revert verified both directly by me and independently by toolkit-specialist): that SAME run -- a "post"-phase checkpoint write failure during an otherwise-healthy, C2-confirmed refresh -- can never subsequently reach FINALIZED, no matter what later checkpoint/publish activity occurs', async () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-block-b-post-permanent-'));
    const fixture = makeSealedIsolationFixture(tmp);
    const LOGIN_ACCOUNT = 'acct-block-b-postperm-login';
    try {
      let resolveHangingRead = null;
      const fakePub = makeFakePublisher(['PUBLISHED'], [true, true]);
      const deps = validAuthoritiesDeps(fixture, {
        expectedRoster: [{ role: 'verifier', ordinal: 0 }],
        sourceProvider: { read: () => new Promise((resolve) => { resolveHangingRead = resolve; }) },
        publisherFactory: fakePub.publisherFactory,
      });
      const authorities = rbc.createRunAuthorities(deps);
      const bound = authorities.bindConnection({ role: 'verifier', ordinal: 0 });
      assert.strictEqual(typeof bound.reason, 'undefined', JSON.stringify(bound));

      const { connection, stdout } = await createAuthenticatedConnection(bound, LOGIN_ACCOUNT);
      await new Promise((resolve) => rbc.writeJsonlFrame(stdout, { id: 'block-b-postperm-refresh-1', method: 'account/chatgptAuthTokens/refresh', params: { reason: 'unauthorized' } }, resolve));
      await new Promise((resolve) => setImmediate(resolve));
      assert.ok(resolveHangingRead, 'test precondition: the source read must genuinely be suspended at this point');

      const checkpointDir = checkpointDirFor(fixture.repoId);
      fs.chmodSync(checkpointDir, 0o500);
      resolveHangingRead({ ok: true, credentials: { accessToken: syntheticSecret('block-b-postperm'), chatgptAccountId: LOGIN_ACCOUNT, chatgptPlanType: 'plus' }, otherCredentialFields: {}, expiresAt: futureIso(400 * 1000), sourceIdentity: 'block-b-postperm-fixture' });
      await new Promise((resolve) => setImmediate(resolve));
      await new Promise((resolve) => setImmediate(resolve));
      await new Promise((resolve) => setImmediate(resolve));
      fs.chmodSync(checkpointDir, 0o700);
      assert.strictEqual(connection.isStopped(), false, 'test precondition: the refresh must have completed healthily despite the post-checkpoint failure (verified by the CONFIRMATION test above; re-asserted here as this test\'s own precondition)');

      bound.close();

      // Fabricate a STRUCTURALLY-COMPLETE checkpoint record, same technique
      // as the write-failure-permanence test above -- proves the SAME run
      // can never reach FINALIZED regardless of later activity.
      // Explicit mode:0o600 -- matches the real production writer exactly, so
      // the fd-bound reader's exact-mode check never rejects this fabrication.
      fs.writeFileSync(checkpointFileFor(fixture.repoId, fixture.runId), JSON.stringify({
        schema: 'coordination/credential-absence-checkpoints/v1', run_id: fixture.runId, mode: 'app-server', root_ids: [],
        checkpoints: [
          { name: 'login:pre@verifier:0', ok: true }, { name: 'login:post@verifier:0', ok: true },
          { name: 'turn:pre@verifier:0', ok: true }, { name: 'turn:during@verifier:0', ok: true }, { name: 'turn:post@verifier:0', ok: true },
          { name: 'cleanup:pre@verifier:0', ok: true }, { name: 'cleanup:post@verifier:0', ok: true },
        ],
        complete: true,
      }), { mode: 0o600 });

      let result;
      for (let i = 0; i < 5; i++) {
        result = await authorities.publishAndFinalize();
        if (result.state === 'FINALIZED') break;
      }
      assert.notStrictEqual(result.state, 'FINALIZED', 'a run whose refresh succeeded but whose "post" checkpoint failed to durably write must NEVER reach FINALIZED, no matter how many times publishAndFinalize() is called or how complete the checkpoints array later looks: ' + JSON.stringify(result));
      assert.strictEqual(result.state, 'PUBLICATION_INVALID', JSON.stringify(result));
      assert.strictEqual(result.reason, 'CHECKPOINT_WRITE_FAILURE_RECORDED', JSON.stringify(result));
    } finally {
      cleanupDir(tmp);
    }
  });

  // Uses the newly-added activeLeaseCount field on __testOnlyInspectFinalizationState
  // (toolkit-specialist, this round) -- necessary because the SAME checkpoint
  // failure this test triggers also permanently trips the write-failure gate
  // above, which would otherwise mask publishAndFinalize()'s own LEASES_ACTIVE
  // reason for the rest of this run, leaving no other black-box way to prove
  // the lease was genuinely released.
  test('FIX (confirmed correct once toolkit-specialist\'s Group 1 fix landed, mutation-revert verified both directly by me and independently by toolkit-specialist) + CONFIRMATION (the lease-release half already held before this fix too, kept as a regression guard): close() reports {ok:false,reason} when its OWN close-checkpoint write genuinely fails, while STILL unconditionally releasing the lease', () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-block-b-close-failure-'));
    const fixture = makeSealedIsolationFixture(tmp);
    try {
      const authorities = rbc.createRunAuthorities(validAuthoritiesDeps(fixture, { expectedRoster: [{ role: 'verifier', ordinal: 0 }] }));
      const bound = authorities.bindConnection({ role: 'verifier', ordinal: 0 });
      assert.strictEqual(typeof bound.reason, 'undefined', JSON.stringify(bound));

      assert.strictEqual(typeof rbc.__testOnlyInspectFinalizationState, 'function', '__testOnlyInspectFinalizationState must exist -- needed to observe lease state independently of the write-failure gate this same test trips');
      const beforeClose = rbc.__testOnlyInspectFinalizationState(authorities);
      assert.strictEqual(beforeClose.activeLeaseCount, 1, 'test precondition: exactly one lease (this one bound connection) must be active before close(): ' + JSON.stringify(beforeClose));

      const checkpointDir = checkpointDirFor(fixture.repoId);
      fs.chmodSync(checkpointDir, 0o500);
      let closeResult;
      try {
        closeResult = bound.close();
      } finally {
        fs.chmodSync(checkpointDir, 0o700);
      }

      assert.strictEqual(closeResult.ok, false, 'close() must honestly report failure when its own close-checkpoint write fails -- credential validity is not in question here (unlike an in-flight refresh), so close() reports its own durability failure directly rather than silently swallowing it: ' + JSON.stringify(closeResult));
      assert.strictEqual(typeof closeResult.reason, 'string', JSON.stringify(closeResult));

      const afterClose = rbc.__testOnlyInspectFinalizationState(authorities);
      assert.strictEqual(afterClose.activeLeaseCount, 0, 'the lease must be released UNCONDITIONALLY even though close()\'s own checkpoint write failed -- a checkpoint I/O hiccup at close time must never deadlock the run via a stuck lease: ' + JSON.stringify(afterClose));
    } finally {
      cleanupDir(tmp);
    }
  });
});

// ══════════════════════════════════════════════════════════════════════════
// CORRECTION ROUND -- Findings 3+5: isCredentialEvidenceComplete (reader) and
// computeCredentialEvidenceComplete (writer) hardening. team-lead-approved
// scope (toolkit-specialist's design, not yet implemented): mode equality
// against the run's own actual mode (not just enum validity), root_ids
// shape + exact-match validation, closed checkpoint-entry shape, duplicate-
// name detection, malformed-name fail-closed (writer side), a closed
// family:phase allowlist (extra/unrecognized rejected), cross-family
// ordering (item 7, PENDING team-lead's exact rule -- not tested here yet),
// and record.complete cross-checked against a fresh re-derivation off the
// SAME checkpoints array (the mismatch-detection half of "old finding 6" --
// distinct from Group 1's write-failure permanence gate, which handles a
// durable WRITE FAILURE; this is about a record that read back successfully
// but whose own complete claim disagrees with what re-deriving the same
// checkpoints genuinely computes -- tampering or a writer-logic bug).
//
// Every RED scenario below was verified empirically against the CURRENT
// (pre-fix) code via a standalone diagnostic before writing any assertion:
// all wrongly reach PUBLISHED_VALID today. Item 5 (malformed checkpoint
// name) is intentionally NOT included as a RED test here -- verified this
// round that isCredentialEvidenceComplete's own wrapper already rejects it
// via a separate, pre-existing check (checkpointsValid) that runs BEFORE
// computeCredentialEvidenceComplete is ever reached from this black-box
// path, so it is not independently observable as a gap this way; holding
// for toolkit-specialist's guidance on whether/how to test the writer-side
// half directly.
// ══════════════════════════════════════════════════════════════════════════

describe('CORRECTION ROUND -- Findings 3+5: credential evidence completeness hardening', () => {
  function checkpointDirFor(repoId) {
    return path.join(rll.registryRepoDir({ repoId }), 'credential-absence-checkpoints');
  }
  function checkpointFileFor(repoId, runId) {
    return path.join(checkpointDirFor(repoId), runId + '.json');
  }
  function baseCheckpoints() {
    const now = new Date().toISOString();
    return [
      { name: 'login:pre@verifier:0', at: now, roots_scanned: 1, captures_scanned: 0, ok: true },
      { name: 'login:post@verifier:0', at: now, roots_scanned: 1, captures_scanned: 0, ok: true },
      { name: 'turn:pre@verifier:0', at: now, roots_scanned: 1, captures_scanned: 0, ok: true },
      { name: 'turn:during@verifier:0', at: now, roots_scanned: 1, captures_scanned: 0, ok: true },
      { name: 'turn:post@verifier:0', at: now, roots_scanned: 1, captures_scanned: 0, ok: true },
      { name: 'cleanup:pre@verifier:0', at: now, roots_scanned: 1, captures_scanned: 0, ok: true },
      { name: 'cleanup:post@verifier:0', at: now, roots_scanned: 1, captures_scanned: 0, ok: true },
    ];
  }

  // Real, sealed fixture + real composition root (mode explicitly pinned to
  // 'app-server' -- validAuthoritiesDeps's own default, 'conformance', is
  // never a valid credential-absence-checkpoints/v1 record mode, which would
  // make every scenario here -- including the baseline -- fail the EXISTING
  // enum check for an unrelated reason). Writes a fully-valid, structurally-
  // complete checkpoint record shaped by `mutateRecord` (called with the
  // base valid record; mutate in place) directly to disk.
  async function setupWithFabricatedRecord(mutateRecord) {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-findings35-'));
    const fixture = makeSealedIsolationFixture(tmp);
    const fakePub = makeFakePublisher(['PUBLISHED'], [true, true]);
    const authorities = rbc.createRunAuthorities(validAuthoritiesDeps(fixture, {
      mode: 'app-server',
      publisherFactory: fakePub.publisherFactory,
      expectedRoster: [{ role: 'verifier', ordinal: 0 }],
    }));
    const record = {
      schema: 'coordination/credential-absence-checkpoints/v1',
      run_id: fixture.runId,
      mode: 'app-server',
      root_ids: [rbc.computeRootId(fixture.instanceId)],
      checkpoints: baseCheckpoints(),
      complete: true,
    };
    mutateRecord(record);
    fs.mkdirSync(checkpointDirFor(fixture.repoId), { recursive: true, mode: 0o700 });
    // Explicit mode:0o600 -- matches the real production writer exactly, so
    // the fd-bound reader's exact-mode check never rejects this fabrication
    // regardless of local umask (fixes ALL callers of this shared helper).
    fs.writeFileSync(checkpointFileFor(fixture.repoId, fixture.runId), JSON.stringify(record), { mode: 0o600 });
    return { tmp, fixture, authorities };
  }

  test('CONFIRMATION (fixture sanity check, not itself a finding): a fabricated, fully-valid, structurally-complete checkpoint record reaches PUBLISHED_VALID -- proves the fixture technique itself is sound before every mutated-record test below relies on it', async () => {
    const { tmp, authorities } = await setupWithFabricatedRecord(() => {});
    try {
      const result = await authorities.publishAndFinalize();
      assert.strictEqual(result.state, 'PUBLISHED_VALID', JSON.stringify(result));
    } finally {
      cleanupDir(tmp);
    }
  });

  test('FIX (Findings 3+5 item 1, confirmed correct + mutation-revert proven): record.mode is a VALID enum member ("mcp") but does not equal this run\'s OWN actual mode ("app-server") -- previously wrongly reached PUBLISHED_VALID (mode was checked only for enum membership, never cross-checked for equality against the run); now correctly rejected', async () => {
    const { tmp, authorities } = await setupWithFabricatedRecord((r) => { r.mode = 'mcp'; });
    try {
      const result = await authorities.publishAndFinalize();
      assert.notStrictEqual(result.state, 'PUBLISHED_VALID', 'a checkpoint record whose mode does not match this run\'s own actual mode must never be treated as valid evidence, even if the claimed mode is itself a valid enum member: ' + JSON.stringify(result));
      assert.strictEqual(result.state, 'OPEN', JSON.stringify(result));
    } finally {
      cleanupDir(tmp);
    }
  });

  const rootIdsScenarios = [
    ['a wrong-but-validly-shaped root id (correct length/format, wrong hash)', (r) => { r.root_ids = [crypto.randomBytes(32).toString('hex')]; }],
    ['root_ids is not an array at all', (r) => { r.root_ids = 'not-an-array'; }],
    ['root_ids is an empty array', (r) => { r.root_ids = []; }],
  ];
  for (const [label, mutate] of rootIdsScenarios) {
    test('FIX (Findings 3+5 item 2, confirmed correct + mutation-revert proven): ' + label + ' -- previously wrongly reached PUBLISHED_VALID (root_ids was read but never validated); now correctly rejected', async () => {
      const { tmp, authorities } = await setupWithFabricatedRecord(mutate);
      try {
        const result = await authorities.publishAndFinalize();
        assert.notStrictEqual(result.state, 'PUBLISHED_VALID', 'root_ids must be validated (shape + exact match to this run\'s own sealed root) before evidence can be treated as valid: ' + JSON.stringify(result));
        assert.strictEqual(result.state, 'OPEN', JSON.stringify(result));
      } finally {
        cleanupDir(tmp);
      }
    });
  }

  const entryShapeScenarios = [
    ['carries an extra, unexpected key', (r) => { r.checkpoints[0].extraField = 'unexpected'; }],
    ['captures_scanned is negative', (r) => { r.checkpoints[0].captures_scanned = -1; }],
    ['at is not a parseable timestamp', (r) => { r.checkpoints[0].at = 'not-a-date'; }],
    ['is missing the captures_scanned key entirely', (r) => { delete r.checkpoints[0].captures_scanned; }],
  ];
  for (const [label, mutate] of entryShapeScenarios) {
    test('FIX (Findings 3+5 item 3, confirmed correct + mutation-revert proven): a checkpoint entry ' + label + ' -- previously wrongly reached PUBLISHED_VALID (only .name was validated, not the full {at,captures_scanned,name,ok,roots_scanned} shape); now correctly rejected', async () => {
      const { tmp, authorities } = await setupWithFabricatedRecord(mutate);
      try {
        const result = await authorities.publishAndFinalize();
        assert.notStrictEqual(result.state, 'PUBLISHED_VALID', 'a structurally-invalid checkpoint entry must never be treated as valid evidence: ' + JSON.stringify(result));
        assert.strictEqual(result.state, 'OPEN', JSON.stringify(result));
      } finally {
        cleanupDir(tmp);
      }
    });
  }

  test('CONFIRMATION (already correct today, accidentally -- not a dedicated shape validator): a checkpoint entry whose ok field is a STRING ("true") rather than a boolean is already rejected, via the pre-existing strict c.ok===true equality check inside computeCredentialEvidenceComplete, not because any dedicated entry-shape validator exists yet', async () => {
    const { tmp, authorities } = await setupWithFabricatedRecord((r) => { r.checkpoints[0].ok = 'true'; });
    try {
      const result = await authorities.publishAndFinalize();
      assert.notStrictEqual(result.state, 'PUBLISHED_VALID', JSON.stringify(result));
    } finally {
      cleanupDir(tmp);
    }
  });

  test('FIX (Findings 3+5 item 4, confirmed correct + mutation-revert proven): the SAME checkpoint name (family:phase@role:ordinal) appears twice -- previously wrongly reached PUBLISHED_VALID (the per-member order check used indexOf, first-occurrence only, so a duplicate was silently invisible); now correctly rejected', async () => {
    const { tmp, authorities } = await setupWithFabricatedRecord((r) => { r.checkpoints.push(Object.assign({}, r.checkpoints[0])); });
    try {
      const result = await authorities.publishAndFinalize();
      assert.notStrictEqual(result.state, 'PUBLISHED_VALID', 'a duplicate checkpoint entry must be detected and rejected, never silently tolerated: ' + JSON.stringify(result));
      assert.strictEqual(result.state, 'OPEN', JSON.stringify(result));
    } finally {
      cleanupDir(tmp);
    }
  });

  test('FIX (Findings 3+5 item 6a, confirmed correct + mutation-revert proven): an extra checkpoint entry uses a family:phase combination outside the closed set this file\'s own code actually produces -- previously wrongly reached PUBLISHED_VALID (there was no closed allowlist, any well-formed-LOOKING name was silently accepted); now correctly rejected', async () => {
    const { tmp, authorities } = await setupWithFabricatedRecord((r) => { r.checkpoints.push({ name: 'made-up-family:bogus-phase@verifier:0', at: new Date().toISOString(), roots_scanned: 1, captures_scanned: 0, ok: true }); });
    try {
      const result = await authorities.publishAndFinalize();
      assert.notStrictEqual(result.state, 'PUBLISHED_VALID', 'an unrecognized family:phase combination must be rejected, never silently tolerated as if it were a genuine checkpoint: ' + JSON.stringify(result));
      assert.strictEqual(result.state, 'OPEN', JSON.stringify(result));
    } finally {
      cleanupDir(tmp);
    }
  });

  test('FIX (Findings 3+5 item 6b, test-specialist\'s own find, confirmed correct + mutation-revert proven -- isolated: disabling ONLY this guard against current HEAD produced exactly 1 failure, this test, restored to 261/261): a checkpoint entry exists for a role:ordinal that is NOT in expectedRoster at all (a real, plausible role name -- "quality-gater" -- just not part of THIS run\'s own roster) -- the completeness loop only ever walks roster members, so an entry for a role/ordinal outside the roster would otherwise be silently invisible to it, regardless of how well-formed its own family:phase is', async () => {
    const { tmp, authorities } = await setupWithFabricatedRecord((r) => { r.checkpoints.push({ name: 'login:pre@quality-gater:0', at: new Date().toISOString(), roots_scanned: 1, captures_scanned: 0, ok: true }); });
    try {
      const result = await authorities.publishAndFinalize();
      assert.notStrictEqual(result.state, 'PUBLISHED_VALID', 'a checkpoint entry for a role:ordinal outside expectedRoster must be rejected as anomalous, never silently ignored: ' + JSON.stringify(result));
      assert.strictEqual(result.state, 'OPEN', JSON.stringify(result));
    } finally {
      cleanupDir(tmp);
    }
  });

  test('FIX (Findings 3+5 item 8, confirmed correct + mutation-revert proven): record.complete LIES (claims false) while the checkpoints array is genuinely, structurally COMPLETE -- previously wrongly reached PUBLISHED_VALID (record.complete was discarded entirely, never cross-checked against a fresh re-derivation off the SAME checkpoints array); now correctly rejected (the mismatch-detection half of the old finding 6, distinct from Group 1\'s write-failure permanence gate -- an earlier attempt at this test used a genuinely-incomplete checkpoints array which wrongly conflated this property with plain EVIDENCE_INCOMPLETE; corrected before landing)', async () => {
    const { tmp, authorities } = await setupWithFabricatedRecord((r) => { r.complete = false; });
    try {
      const result = await authorities.publishAndFinalize();
      assert.notStrictEqual(result.state, 'PUBLISHED_VALID', 'a record whose own complete flag disagrees with a fresh re-derivation off the same checkpoints array must be rejected as suspect (tampering or a writer bug), never silently trusted via the re-derivation alone: ' + JSON.stringify(result));
      assert.strictEqual(result.state, 'OPEN', JSON.stringify(result));
    } finally {
      cleanupDir(tmp);
    }
  });

  test('FIX (Findings 3+5 bonus item, confirmed correct + mutation-revert proven): the whole checkpoint record carries an extra, unexpected top-level key beyond {checkpoints,complete,mode,root_ids,run_id,schema} -- previously wrongly reached PUBLISHED_VALID (no whole-record closed shape check existed); now correctly rejected', async () => {
    const { tmp, authorities } = await setupWithFabricatedRecord((r) => { r.unexpectedTopLevelKey = 'x'; });
    try {
      const result = await authorities.publishAndFinalize();
      assert.notStrictEqual(result.state, 'PUBLISHED_VALID', 'a checkpoint record with an unrecognized top-level key must be rejected as malformed, never silently accepted: ' + JSON.stringify(result));
      assert.strictEqual(result.state, 'OPEN', JSON.stringify(result));
    } finally {
      cleanupDir(tmp);
    }
  });

  test('FIX (Findings 3+5 item 7, confirmed correct + mutation-revert proven): bind@<role>:<ordinal> (attestPreBind\'s own checkpoint, already a recognized family:phase via FIXED_RECOGNIZED_FAMILY_PHASES) appears AFTER another checkpoint for the same member (login:pre), rather than being the first entry for that member -- previously wrongly reached PUBLISHED_VALID (bind\'s position relative to the rest of a member\'s sequence was not checked, only that it was a recognized name); now correctly rejected via memberHasBindNotFirst', async () => {
    const { tmp, authorities } = await setupWithFabricatedRecord((r) => {
      r.checkpoints.splice(1, 0, { name: 'bind@verifier:0', at: new Date().toISOString(), roots_scanned: 1, captures_scanned: 0, ok: true });
    });
    try {
      const result = await authorities.publishAndFinalize();
      assert.notStrictEqual(result.state, 'PUBLISHED_VALID', 'bind must be the first checkpoint recorded for a given role:ordinal member -- a bind entry appearing after another checkpoint for the same member must be rejected, never silently tolerated: ' + JSON.stringify(result));
      assert.strictEqual(result.state, 'OPEN', JSON.stringify(result));
    } finally {
      cleanupDir(tmp);
    }
  });

  test('FIX (Findings 3+5 item 5, confirmed correct + mutation-revert proven): computeCredentialEvidenceComplete, called DIRECTLY via the isTestCapability()-gated export (isCredentialEvidenceComplete\'s own outer checkpointsValid guard makes this black-box-unreachable via on-disk fabrication, since a malformed name is caught THERE first, before this function is ever reached) -- an extra checkpoint entry whose .name fails parseCorrelatedCheckpointName was previously silently DROPPED by the internal .filter(p => p !== null) rather than treated as a rejection signal (a checkpoints array otherwise fully complete for the roster still evaluated to true even with a malformed intruder entry mixed in); now correctly rejected via an explicit some(p => p === null) check', () => {
    const roster = [{ role: 'verifier', ordinal: 0 }];
    const checkpoints = baseCheckpoints();
    checkpoints.push({ name: 'not-a-valid-checkpoint-name-at-all', at: new Date().toISOString(), roots_scanned: 1, captures_scanned: 0, ok: true });
    const result = rbc.computeCredentialEvidenceComplete(checkpoints, roster);
    assert.strictEqual(result, false, 'a checkpoints array containing an entry whose name fails to parse must never be treated as complete, even when the REST of the array independently satisfies the roster -- a malformed entry must be a hard rejection signal, never silently filtered out and ignored: computeCredentialEvidenceComplete returned ' + JSON.stringify(result));
  });
});

describe('CORRECTION ROUND -- Finding 2: revalidation gating (PUBLISHED_VALID re-derivation + bindConnection finalizationState awareness)', () => {
  function checkpointDirFor(repoId) {
    return path.join(rll.registryRepoDir({ repoId }), 'credential-absence-checkpoints');
  }
  function checkpointFileFor(repoId, runId) {
    return path.join(checkpointDirFor(repoId), runId + '.json');
  }
  function baseCheckpointsFor(role, ordinal) {
    const now = new Date().toISOString();
    return ['login:pre', 'login:post', 'turn:pre', 'turn:during', 'turn:post', 'cleanup:pre', 'cleanup:post'].map((familyPhase) => (
      { name: familyPhase + '@' + role + ':' + ordinal, at: now, roots_scanned: 1, captures_scanned: 0, ok: true }
    ));
  }
  function writeFullyValidRecord(fixture, members) {
    const roster = members || [{ role: 'verifier', ordinal: 0 }];
    const checkpoints = [];
    for (const m of roster) checkpoints.push(...baseCheckpointsFor(m.role, m.ordinal));
    const record = {
      schema: 'coordination/credential-absence-checkpoints/v1',
      run_id: fixture.runId,
      mode: 'app-server',
      root_ids: [rbc.computeRootId(fixture.instanceId)],
      checkpoints,
      complete: true,
    };
    fs.mkdirSync(checkpointDirFor(fixture.repoId), { recursive: true, mode: 0o700 });
    // Explicit mode:0o600 -- matches the real production writer exactly, so
    // the fd-bound reader's exact-mode check never rejects this fabrication
    // regardless of local umask (fixes ALL callers of this shared helper).
    fs.writeFileSync(checkpointFileFor(fixture.repoId, fixture.runId), JSON.stringify(record), { mode: 0o600 });
    return record;
  }

  test('FIX (Finding 2a): PUBLISHED_VALID -> FINALIZING never re-derives credential evidence completeness -- only the external canonical-manifest validator (safeValidate) gates this transition. Once evidence genuinely regresses after PUBLISHED_VALID was reached (a dangling refresh-checkout:pre with no matching :post, appended directly to the durable record on disk), a SECOND publishAndFinalize() call currently proceeds toward FINALIZING/FINALIZED anyway, since the fake validator stays green regardless of what the checkpoints array actually contains (verified empirically this round before writing this assertion)', async () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'finding2a-'));
    const fixture = makeSealedIsolationFixture(tmp);
    try {
      const fakePub = makeFakePublisher(['PUBLISHED'], [true, true]);
      const authorities = rbc.createRunAuthorities(validAuthoritiesDeps(fixture, {
        mode: 'app-server',
        publisherFactory: fakePub.publisherFactory,
        expectedRoster: [{ role: 'verifier', ordinal: 0 }],
      }));
      const record = writeFullyValidRecord(fixture);

      const first = await authorities.publishAndFinalize();
      assert.strictEqual(first.state, 'PUBLISHED_VALID', JSON.stringify(first));

      // Evidence regresses: a dangling refresh-checkout:pre, no matching :post.
      record.checkpoints.push({ name: 'refresh-checkout:pre@verifier:0', at: new Date().toISOString(), roots_scanned: 1, captures_scanned: 0, ok: true });
      // Explicit mode:0o600 -- matches the real production writer exactly, so
      // the fd-bound reader's exact-mode check never rejects this fabrication.
      fs.writeFileSync(checkpointFileFor(fixture.repoId, fixture.runId), JSON.stringify(record), { mode: 0o600 });

      const second = await authorities.publishAndFinalize();
      assert.strictEqual(second.state, 'PUBLICATION_INVALID', 'once evidence completeness regresses after PUBLISHED_VALID was reached, the PUBLISHED_VALID->FINALIZING transition must re-derive it and refuse to proceed toward FINALIZING/FINALIZED: ' + JSON.stringify(second));
    } finally {
      cleanupDir(tmp);
    }
  });

  test('FIX: bindConnection now correctly allows binding while genuinely PUBLISHED_VALID (not merely during the OPEN async-await race window) -- proves PLAN.md\'s "PUBLISHED_VALID -- leases>0 (re-checked) --> stays PUBLISHED_VALID" transition is real, not dead code', async () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'finding2b-published-'));
    const fixture = makeSealedIsolationFixture(tmp);
    try {
      const fakePub = makeFakePublisher(['PUBLISHED'], [true, true]);
      const authorities = rbc.createRunAuthorities(validAuthoritiesDeps(fixture, {
        mode: 'app-server',
        publisherFactory: fakePub.publisherFactory,
        expectedRoster: [{ role: 'verifier', ordinal: 0 }],
      }));
      // Fabricate evidence for verifier:0 directly on disk (same technique as
      // the pre-existing "PUBLISHED_VALID + leases>0 (re-checked)" test at
      // ~L1700-1793, which explains this roster-exhaustion mechanics in
      // full) -- never really bound, so boundCountByRole stays 0, and
      // ordinal 0 remains genuinely available for a real bind below.
      writeFullyValidRecord(fixture);

      const published = await authorities.publishAndFinalize();
      assert.strictEqual(published.state, 'PUBLISHED_VALID', JSON.stringify(published));

      const bound = authorities.bindConnection({ role: 'verifier', ordinal: 0 });
      // A successful bind never carries an `.ok` field at all (only a
      // rejected bind carries {ok:false,reason} -- confirmed against the
      // established shape used throughout this file, e.g. L1765's "the bind
      // must succeed HERE" assertion), so `typeof bound.reason==='undefined'`
      // is the correct, sole success signal here -- an `bound.ok===true`
      // check would wrongly fail even on a genuine success.
      assert.strictEqual(typeof bound.reason, 'undefined', 'bindConnection must now genuinely succeed while finalizationState is PUBLISHED_VALID, for a roster member that has never actually consumed its ordinal: ' + JSON.stringify(bound));

      const second = await authorities.publishAndFinalize();
      assert.strictEqual(second.state, 'PUBLISHED_VALID', 'a genuine post-PUBLISHED_VALID bind must keep the run in PUBLISHED_VALID, proving PLAN.md\'s "PUBLISHED_VALID -- leases>0 (re-checked) --> stays PUBLISHED_VALID" transition is real, not dead code: ' + JSON.stringify(second));
      assert.strictEqual(second.reason, 'LEASES_ACTIVE', JSON.stringify(second));
    } finally {
      cleanupDir(tmp);
    }
  });

  test('FIX (Finding 2b, PUBLICATION_INVALID variant): same gap, reached via PUBLICATION_INVALID instead -- broker.zero() is likewise never called on this path (PUBLICATION_INVALID is an early-return terminal branch in publishAndFinalize, reached WITHOUT ever entering the FINALIZING branch that owns attemptTeardown/broker.zero()), so bindConnection must reject just as uniformly once this run can never be published again, not merely mid-happy-path (verified empirically this round before writing this assertion)', async () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'finding2b-invalid-'));
    const fixture = makeSealedIsolationFixture(tmp);
    try {
      const fakePub = makeFakePublisher(['PUBLISHED'], [true, false]); // succeeds initial publish, fails PUBLISHED_VALID's own pre-existing re-validation.
      const authorities = rbc.createRunAuthorities(validAuthoritiesDeps(fixture, {
        mode: 'app-server',
        publisherFactory: fakePub.publisherFactory,
        expectedRoster: [{ role: 'verifier', ordinal: 0 }],
      }));
      writeFullyValidRecord(fixture);

      const firstResult = await authorities.publishAndFinalize();
      assert.strictEqual(firstResult.state, 'PUBLISHED_VALID', JSON.stringify(firstResult));
      const secondResult = await authorities.publishAndFinalize();
      assert.strictEqual(secondResult.state, 'PUBLICATION_INVALID', JSON.stringify(secondResult));

      const bound = authorities.bindConnection({ role: 'verifier', ordinal: 0 });
      assert.strictEqual(bound.ok, false, 'no new connection should be able to bind once this run has been permanently invalidated: ' + JSON.stringify(bound));
    } finally {
      cleanupDir(tmp);
    }
  });
});

describe('CORRECTION ROUND -- Finding 4: supervisor-wide teardown evidence (attemptTeardown scan-and-record)', () => {
  function checkpointDirFor(repoId) {
    return path.join(rll.registryRepoDir({ repoId }), 'credential-absence-checkpoints');
  }

  test('FIX (Finding 4, confirmed correct + mutation-revert proven): reaching FINALIZED previously never wrote a supervisor-wide teardown checkpoint record at all -- attemptTeardown performed zero checkpoint/attestation calls, only broker.zero()/clearSecretMatcherInternal/clearCaptureRegistryInternal plus re-verification; now genuinely scans and records both before and after zeroing the broker, folded into the SAME credential-absence-checkpoints/v1 record every other checkpoint uses (via attestSupervisorTeardown/publishDurableCheckpoint, under the reserved teardown:pre/teardown:post names -- never a separate schema/file)', async () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'finding4-happy-'));
    const fixture = makeSealedIsolationFixture(tmp);
    try {
      const fakePub = makeFakePublisher(['PUBLISHED'], [true, true]);
      const authorities = rbc.createRunAuthorities(validAuthoritiesDeps(fixture, {
        mode: 'app-server',
        publisherFactory: fakePub.publisherFactory,
        expectedRoster: [], // empty roster keeps evidence trivially complete, isolating this property.
      }));
      let result;
      for (let i = 0; i < 5; i++) {
        result = await authorities.publishAndFinalize();
        if (result.state === 'FINALIZED') break;
      }
      assert.strictEqual(result.state, 'FINALIZED', JSON.stringify(result));
      const mainCheckpointFile = path.join(checkpointDirFor(fixture.repoId), fixture.runId + '.json');
      const record = readJsonFile(mainCheckpointFile);
      const names = record.checkpoints.map((c) => c.name);
      assert.ok(names.includes('teardown:pre'), 'the main credential-absence-checkpoints/v1 record must contain a teardown:pre entry once FINALIZED, proving attemptTeardown genuinely scanned BEFORE zeroing the broker: ' + JSON.stringify(names));
      assert.ok(names.includes('teardown:post'), 'the main credential-absence-checkpoints/v1 record must contain a teardown:post entry once FINALIZED, proving attemptTeardown genuinely scanned AFTER zeroing the broker: ' + JSON.stringify(names));
    } finally {
      cleanupDir(tmp);
    }
  });

  test('FIX (Finding 4, confirmed correct + mutation-revert proven): a genuine leak present ONLY at teardown time (registered secret via a real, clean refresh; the dirty capture is planted AFTER the connection has already closed, so no PER-CONNECTION scan ever sees it) previously went completely undetected -- attemptTeardown performed no scan of its own, so a dangling leak sitting in the shared, run-wide CaptureRegistry at the moment of teardown was silently cleared (never inspected) rather than caught; now correctly rejected (LEAK_DETECTED)', async () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'finding4-leak-'));
    const fixture = makeSealedIsolationFixture(tmp);
    try {
      const KNOWN_SECRET = syntheticSecret('finding4-teardown-leak');
      const fakePub = makeFakePublisher(['PUBLISHED'], [true, true]);
      const authorities = rbc.createRunAuthorities(validAuthoritiesDeps(fixture, {
        mode: 'app-server',
        sourceProvider: fakeSourceProviderBlock2({
          read: () => ({ ok: true, credentials: { token: KNOWN_SECRET }, otherCredentialFields: {}, expiresAt: futureIso(400 * 1000), sourceIdentity: 'finding4-teardown-leak-fixture' }),
        }),
        publisherFactory: fakePub.publisherFactory,
        expectedRoster: [{ role: 'verifier', ordinal: 0 }],
      }));
      // Real bind + a clean refresh (registers KNOWN_SECRET into the shared,
      // live SecretMatcher) + close, done FIRST -- refreshProvider() writes
      // its own real refresh:<attemptNumber>:<phase> checkpoints via the
      // in-memory checkpointState, which would otherwise clobber a
      // fabricated record written BEFORE this activity (the in-memory state
      // never knew about it, so the next real write silently drops it).
      const bound = authorities.bindConnection({ role: 'verifier', ordinal: 0 });
      assert.strictEqual(typeof bound.reason, 'undefined', JSON.stringify(bound));
      const cleanRefresh = bound.refreshProvider({});
      assert.strictEqual(cleanRefresh.ok, true, 'setup: the registering refresh itself must complete cleanly, with no capture yet planted: ' + JSON.stringify(cleanRefresh));
      bound.close();

      // NOW fabricate fully-valid evidence directly on disk, AFTER the real
      // activity above -- this is the LAST write to the file, so it is not
      // at risk of being clobbered by anything else. boundCountByRole is
      // irrelevant here (the real bind above already consumed ordinal 0
      // legitimately); this fabrication exists purely to satisfy
      // isCredentialEvidenceComplete's own required login/turn/cleanup
      // sequence, which the real activity above never performed.
      const checkpointFile = path.join(checkpointDirFor(fixture.repoId), fixture.runId + '.json');
      fs.mkdirSync(checkpointDirFor(fixture.repoId), { recursive: true, mode: 0o700 });
      // Explicit mode:0o600 -- matches the real production writer exactly, so
      // the fd-bound reader's exact-mode check never rejects this fabrication.
      fs.writeFileSync(checkpointFile, JSON.stringify({
        schema: 'coordination/credential-absence-checkpoints/v1',
        run_id: fixture.runId,
        mode: 'app-server',
        root_ids: [rbc.computeRootId(fixture.instanceId)],
        checkpoints: ['login:pre', 'login:post', 'turn:pre', 'turn:during', 'turn:post', 'cleanup:pre', 'cleanup:post'].map((familyPhase) => (
          { name: familyPhase + '@verifier:0', at: new Date().toISOString(), roots_scanned: 1, captures_scanned: 0, ok: true }
        )),
        complete: true,
      }), { mode: 0o600 });

      // NOW plant a capture mentioning the already-registered secret -- the
      // connection is already closed, so no per-connection checkpoint call
      // will ever run again to catch this. Only a SUPERVISOR-WIDE scan at
      // teardown time could still catch it.
      authorities.captureSink.register(Buffer.from('later child output mentioning ' + KNOWN_SECRET, 'utf8'));

      let result;
      for (let i = 0; i < 5; i++) {
        result = await authorities.publishAndFinalize();
        if (result.state === 'FINALIZED' || result.state === 'PUBLICATION_INVALID') break;
      }
      assert.notStrictEqual(result.state, 'FINALIZED', 'a leak sitting in the shared CaptureRegistry at teardown time must block finalization (LEAK_DETECTED), never be silently cleared without ever being inspected: ' + JSON.stringify(result));
    } finally {
      cleanupDir(tmp);
    }
  });

  test('FIX (Finding 4, confirmed correct + mutation-revert proven): a genuine write failure on the supervisor-wide teardown checkpoint record must block finalization, mirroring the main record\'s own write-failure-permanence gate (checkpointState.everHadWriteFailure/hadWriteFailure()) -- previously there was no write happening at attemptTeardown time at all, so an unwritable directory had ZERO effect and finalization proceeded to FINALIZED regardless; now genuinely blocked', async () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'finding4-writefail-'));
    const fixture = makeSealedIsolationFixture(tmp);
    try {
      const fakePub = makeFakePublisher(['PUBLISHED'], [true, true]);
      const authorities = rbc.createRunAuthorities(validAuthoritiesDeps(fixture, {
        mode: 'app-server',
        publisherFactory: fakePub.publisherFactory,
        expectedRoster: [],
      }));
      const checkpointDir = checkpointDirFor(fixture.repoId);
      fs.mkdirSync(checkpointDir, { recursive: true, mode: 0o700 });
      fs.chmodSync(checkpointDir, 0o500);
      let result;
      try {
        for (let i = 0; i < 5; i++) {
          result = await authorities.publishAndFinalize();
          if (result.state === 'FINALIZED') break;
        }
      } finally {
        fs.chmodSync(checkpointDir, 0o700); // always restore, even if the assertion below throws.
      }
      assert.notStrictEqual(result.state, 'FINALIZED', 'a genuine write failure on the supervisor-teardown record must block finalization, never silently succeed regardless of directory permissions: ' + JSON.stringify(result));
    } finally {
      cleanupDir(tmp);
    }
  });
});

