    // the root-provisioning fabrication a few lines down).
    const finalPathStatForIntent = fs.existsSync(finalPath) ? fs.statSync(finalPath, { bigint: true }) : null;
    const rootInodeForIntent = finalPathStatForIntent
      ? { dev: finalPathStatForIntent.dev.toString(), ino: finalPathStatForIntent.ino.toString() }
      : { dev: '111', ino: '222' };
