describe('CORRECTION PASS ROUND 5 -- Finding 9: finalizeRunRoot\'s drift-triggered internal cleanupRoot(...) call discards its own return value', () => {
  test('ATTACK: when a drift-detected finalizeRunRoot\'s own internal tombstone attempt ALSO fails (the .tombstone container\'s own parent directory is unwritable, so cleanupRoot\'s own cleanup-intent/v1 publish cannot even create its container directory), finalized.reason is STILL exactly ROOT_FINALIZE_IDENTITY_DRIFT -- identical to the case where the tombstone succeeds -- with no distinguishable signal, and the root is left sitting completely untouched at its ORIGINAL live path despite the caller having no way to tell', () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-r5-f9-doublefault-'));
    const issuer = createFakeReadViewIssuer();
    const isolationProvider = rbc.createIsolationProvider({
      readViewAuthority: issuer.asReadViewAuthority(),
      strictConfigValidator: () => ({ ok: true }),
      projectRoot: process.cwd(),
    });
    const repoId = crypto.randomBytes(16).toString('hex');
    const instanceId = crypto.randomBytes(16).toString('hex');
    const runId = crypto.randomBytes(16).toString('hex');
    const savedFault = process.env.RUNTIME_BRIDGE_CODEX_FAULT_ROOT_FINALIZE;
    const tombstoneParentDir = path.join(rll.registryRepoDir({ repoId }), '.tombstone');
    try {
      const created = isolationProvider.createRunRoot({ instanceId, repoId, runId, ownerIdentity: fakeOwnerIdentityBlock2() });
      assert.strictEqual(created.ok, true, JSON.stringify(created));

      // Force the INTERNAL cleanupRoot(...) call (inside finalizeRunRoot's
      // own drift branch) to itself fail: pre-create the tombstone
      // container's own PARENT directory read-only, so publishNoClobber's
      // own fs.mkdirSync(containerDir,{recursive:true}) cannot create the
      // leaf container under it.
      fs.mkdirSync(tombstoneParentDir, { recursive: true, mode: 0o700 });
      fs.chmodSync(tombstoneParentDir, 0o500);

      const capability = issuer.issue('verifier', runId).capability;
      process.env.RUNTIME_BRIDGE_CODEX_FAULT_ROOT_FINALIZE = 'post-snapshot-mutate';
      let finalized;
      try {
        finalized = isolationProvider.finalizeRunRoot(created.handle, { role: 'verifier', capability });
      } finally {
        if (savedFault === undefined) delete process.env.RUNTIME_BRIDGE_CODEX_FAULT_ROOT_FINALIZE;
        else process.env.RUNTIME_BRIDGE_CODEX_FAULT_ROOT_FINALIZE = savedFault;
        fs.chmodSync(tombstoneParentDir, 0o700); // restore, so cleanup below can actually remove things.
      }
      assert.strictEqual(finalized.ok, false, 'test precondition: the drift must still be detected: ' + JSON.stringify(finalized));

      assert.notStrictEqual(finalized.reason, 'ROOT_FINALIZE_IDENTITY_DRIFT', 'finalizeRunRoot must surface a DISTINGUISHABLE signal when its own internal tombstone attempt (triggered by the drift it just detected) ALSO fails -- today the discarded internal cleanupRoot(...) return value means finalized.reason is the exact same ROOT_FINALIZE_IDENTITY_DRIFT regardless of whether the tombstone succeeded or failed underneath, so a caller can never tell a drifted-and-safely-tombstoned root apart from a drifted-and-STILL-live-at-its-original-path root: ' + JSON.stringify(finalized));
      assert.strictEqual(fs.existsSync(created.handle.intendedPath), true, 'proof of the silent failure and its real consequence: the root is STILL sitting, completely untouched, at its ORIGINAL live path -- the internal tombstone attempt never even got as far as renaming it, since it failed at the cleanup-intent/v1 publish step (container directory creation) before ever reaching the rename');
    } finally {
      cleanupRegistryFor(repoId);
      cleanupDir(tmp);
    }
  });
});

