describe('CORRECTION PASS ROUND 6 -- Finding C: cleanupRoot reports success even when instance-record retirement fails', () => {
  test('CONFIRMATION (was ATTACK; confirmed already landed as CORRECTION PASS ROUND 6 Finding C by direct source read, runtime-bridge-codex.cjs ~L5025-5040, before this test was written): when retireInstanceRecord\'s own internal conflict path triggers (a genuine content mismatch at the tombstone destination -- a pre-existing tombstone with DIFFERENT content than the live source, retireInstanceRecordLocked\'s own hard-STOP case), cleanupRoot now honestly reports the partial failure (ok:false, CLEANUP_RETIREMENT_FAILED) instead of silently claiming ok:true -- the instance record correctly survives, un-retired, at its original live location, while the already-durably-completed tombstone+cleanup-complete/v1 work is correctly left standing, never undone', () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'c3-r6-c-retirefail-'));
    const fixture = makeSealedIsolationFixture(tmp);
    try {
      // CORRECTION PASS ROUND 7 (Finding 1 item 2 cascade fix): a real,
      // LIVE instance record now genuinely exists -- NEVER_SPAWNED (this
      // test's old default authorization) is no longer valid once a real
      // record is present (Finding 1 item 2 fd-bound-checks for exactly
      // this). PID_ABSENT is the semantically-correct outcome here anyway,
      // fully accredited against this SAME live record.
      const FAKE_PID = 700096;
      const birthToken = 'synthetic-r6-c-retirefail-birth-token';
      const executablePath = process.execPath;
      const instancePath = instanceRecordPathFor(fixture.repoId, fixture.instanceId);
      fs.mkdirSync(path.dirname(instancePath), { recursive: true, mode: 0o700 });
      const sourceRecord = Object.assign(makeInstanceRecordFixture(), {
        instance_id: fixture.instanceId, pid: FAKE_PID, os_birth_token: birthToken, executable_path: executablePath,
      });
      fs.writeFileSync(instancePath, JSON.stringify(sourceRecord), { mode: 0o600 });
      const instanceRecordStat = fs.statSync(instancePath, { bigint: true });
      const instanceRecordIdentity = {
        dev: instanceRecordStat.dev.toString(), ino: instanceRecordStat.ino.toString(),
        mode: instanceRecordStat.mode.toString(), uid: instanceRecordStat.uid.toString(),
      };

      // Pre-plant a CONFLICTING tombstone -- different content than the live
      // source above -- so retireInstanceRecordLocked's own "destination
      // present with different content: hard STOP" case triggers when
      // cleanupRoot internally calls retireInstanceRecord.
      const instanceTombstonePath = instanceTombstonePathFor(fixture.repoId, fixture.instanceId);
      fs.mkdirSync(path.dirname(instanceTombstonePath), { recursive: true, mode: 0o700 });
      const conflictingRecord = Object.assign(makeInstanceRecordFixture(), { instance_id: fixture.instanceId, pid: 999999999 });
      fs.writeFileSync(instanceTombstonePath, JSON.stringify(conflictingRecord), { mode: 0o600 });

      const result = fixture.isolationProvider.cleanupRoot(fixture.sealHandle, minimalValidCleanupAuthorization(fixture.sealHandle, fixture.ownerToken, {
        outcome: 'PID_ABSENT', pid: FAKE_PID, birthToken, executableIdentity: executablePath, instanceRecordIdentity,
      }));
      assert.strictEqual(result.ok, false, 'cleanupRoot must honestly report a retirement failure, never silently claim ok:true when retireInstanceRecord\'s own internal conflict path stops it from actually retiring the instance record: ' + JSON.stringify(result));
      assert.strictEqual(result.reason, 'CLEANUP_RETIREMENT_FAILED', JSON.stringify(result));
      assert.strictEqual(result.finalPath, path.join(rll.registryRepoDir({ repoId: fixture.repoId }), '.tombstone', fixture.instanceId, 'root'), 'finalPath must still be surfaced -- the destructive tombstone work genuinely succeeded, even though retirement did not: ' + JSON.stringify(result));

      assert.strictEqual(fs.existsSync(instancePath), true, 'the instance record must survive, un-retired, at its original live location, since retirement genuinely failed');
      assert.deepStrictEqual(readJsonFile(instancePath), sourceRecord, 'the live instance record must be completely untouched -- exactly its original content');
      assert.deepStrictEqual(readJsonFile(instanceTombstonePath), conflictingRecord, 'the pre-existing conflicting tombstone must also be left exactly as planted, never silently overwritten');
      assert.strictEqual(fs.existsSync(fixture.sealHandle.intendedPath), false, 'the already-durably-completed tombstone work must NOT be undone by the later retirement failure -- the root itself was genuinely, correctly moved');
    } finally {
      cleanupDir(tmp);
    }
  });
});

